-- ===== 20261019000021_carline_vehicles.sql =====
-- ======================================================================
-- Car line vehicles. Whoever picks children up (parents, Family accounts,
-- staff) saves the vehicles they drive in My profile: make, type and color.
-- Announcing pickup records which vehicle is coming, so car line staff can
-- spot it on the board. The last one used is the default, which automatic
-- check-in and the car screen use too.
--
-- Vehicle types and colors are listed here and in src/carline/vehicles.ts;
-- change them together.
-- ======================================================================

create table public.vehicles (
  id           uuid primary key default gen_random_uuid(),
  owner_id     uuid not null references public.profiles (id) on delete cascade,
  make         text not null check (char_length(trim(make)) between 1 and 40),
  kind         text not null check (kind in ('car', 'truck', 'suv', 'van', 'hatchback', 'motorcycle', 'bicycle', 'golf_cart')),
  color        text not null check (color in ('white', 'silver', 'black', 'gray', 'red', 'blue', 'green', 'brown',
                                              'beige', 'gold', 'orange', 'yellow')),
  last_used_at timestamptz,
  created_at   timestamptz not null default now()
);
create index vehicles_owner on public.vehicles (owner_id, last_used_at desc nulls last, created_at desc);
alter table public.vehicles enable row level security;
create policy "your own vehicles" on public.vehicles for select to authenticated using (owner_id = auth.uid());
grant select on public.vehicles to authenticated;
revoke insert, update, delete on public.vehicles from anon, authenticated;
grant all on public.vehicles to service_role;

-- What was coming, as it was when announced (editing or deleting the vehicle later doesn't change it).
alter table public.carline_pickups add column vehicle jsonb;

/** "Silver Honda SUV" */
create function app.vehicle_label(v public.vehicles) returns text
language sql stable as $$
  select initcap(v.color) || ' ' || trim(v.make) || ' '
         || case v.kind when 'suv' then 'SUV' when 'golf_cart' then 'Golf cart' else initcap(v.kind) end
$$;

create function app.vehicle_snapshot(v public.vehicles) returns jsonb
language sql stable as $$
  select case when v.id is null then null
         else jsonb_build_object('id', v.id, 'make', trim(v.make), 'kind', v.kind, 'color', v.color, 'label', app.vehicle_label(v)) end
$$;

/** The vehicle for a pickup: the one asked for (it must be yours), else your default (last used, else newest). */
create function app.pickup_vehicle(p_vehicle uuid, u uuid default auth.uid()) returns public.vehicles
language plpgsql stable security definer set search_path = public as $$
declare v vehicles%rowtype;
begin
  if p_vehicle is not null then
    select * into v from vehicles where id = p_vehicle and owner_id = u;
    if not found then raise exception 'That vehicle isn''t one of yours.' using errcode = '42501'; end if;
    return v;
  end if;
  select * into v from vehicles where owner_id = u order by last_used_at desc nulls last, created_at desc limit 1;
  return v;  -- all null when they haven't saved one
end $$;

-- ----------------------------------------------------------------------
-- My vehicles
-- ----------------------------------------------------------------------

/** Add (p_id null) or change one of your vehicles. */
create function public.vehicle_save(p_id uuid, p_make text, p_kind text, p_color text) returns public.vehicles
language plpgsql security definer set search_path = public as $$
declare row vehicles%rowtype;
begin
  if coalesce(app.school_role(), 'student') = 'student' then
    raise exception 'Vehicles are for the adults who pick children up.' using errcode = '42501';
  end if;
  if coalesce(trim(p_make), '') = '' then raise exception 'Add the vehicle''s make, like Honda or Ford.'; end if;
  if char_length(trim(p_make)) > 40 then raise exception 'Keep the make to 40 characters.'; end if;
  if p_kind is null or p_kind not in ('car', 'truck', 'suv', 'van', 'hatchback', 'motorcycle', 'bicycle', 'golf_cart') then
    raise exception 'Pick the vehicle type.';
  end if;
  if p_color is null or p_color not in ('white', 'silver', 'black', 'gray', 'red', 'blue', 'green', 'brown',
                                        'beige', 'gold', 'orange', 'yellow') then
    raise exception 'Pick the vehicle color.';
  end if;
  if p_id is null then
    if (select count(*) from vehicles where owner_id = auth.uid()) >= 10 then raise exception 'You can save up to 10 vehicles.'; end if;
    insert into vehicles (owner_id, make, kind, color) values (auth.uid(), trim(p_make), p_kind, p_color) returning * into row;
  else
    update vehicles set make = trim(p_make), kind = p_kind, color = p_color
     where id = p_id and owner_id = auth.uid() returning * into row;
    if not found then raise exception 'That vehicle isn''t one of yours.' using errcode = '42501'; end if;
  end if;
  return row;
end $$;

create function public.vehicle_delete(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from vehicles where id = p_id and owner_id = auth.uid();
  if not found then raise exception 'That vehicle isn''t one of yours.' using errcode = '42501'; end if;
end $$;

/** Make one of your vehicles the default for the next pickup. */
create function public.vehicle_use(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  update vehicles set last_used_at = now() where id = p_id and owner_id = auth.uid();
  if not found then raise exception 'That vehicle isn''t one of yours.' using errcode = '42501'; end if;
end $$;

-- ----------------------------------------------------------------------
-- The car line records the vehicle
-- ----------------------------------------------------------------------

drop function public.carline_announce(uuid[], float8, float8, float8);
create function public.carline_announce(p_students uuid[], p_lat float8, p_lng float8, p_accuracy float8 default null,
                                        p_vehicle uuid default null)
returns setof public.carline_pickups
language plpgsql security definer set search_path = public as $$
declare kids uuid[]; dist int; v vehicles%rowtype; snap jsonb;
begin
  if coalesce(app.school_role(), 'student') = 'student' then
    raise exception 'Only parents can announce pickup.' using errcode = '42501';
  end if;
  if p_students is not null and exists (select 1 from unnest(p_students) s where not app.can_pick_up(s)) then
    raise exception 'You can only announce your own children.' using errcode = '42501';
  end if;
  kids := coalesce(p_students, array(select * from app.pickup_children()));
  if cardinality(kids) = 0 then raise exception 'No children are linked to your account yet.'; end if;
  if app.carline_window()->>'state' = 'closed' then raise exception 'The car line is closed right now.'; end if;
  dist := app.require_at_school(p_lat, p_lng, p_accuracy);
  v := app.pickup_vehicle(p_vehicle);
  snap := app.vehicle_snapshot(v);
  insert into carline_pickups (student_id, guardian_id, distance_m, vehicle)
    select distinct k, auth.uid(), dist, snap from unnest(kids) k
    on conflict (student_id, day) where status = 'waiting' do nothing;
  if snap is not null then
    -- Announcing again in another vehicle keeps the place in line and updates what staff look for.
    update carline_pickups set vehicle = snap
     where student_id = any (kids) and day = app.school_today() and status = 'waiting' and guardian_id = auth.uid();
    update vehicles set last_used_at = now() where id = v.id;
  end if;
  return query select * from carline_pickups
    where student_id = any (kids) and day = app.school_today() and status = 'waiting' order by arrived_at;
end $$;
revoke all on function public.carline_announce(uuid[], float8, float8, float8, uuid) from public, anon;
grant execute on function public.carline_announce(uuid[], float8, float8, float8, uuid) to authenticated, service_role;

/** Automatic check-in comes in the default vehicle. */
create or replace function public.carline_arrived(p_lat float8, p_lng float8, p_accuracy float8 default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare w jsonb := app.carline_window(); ids uuid[]; names text[]; dist int; v vehicles%rowtype; snap jsonb;
begin
  if app.school_role() is null then raise exception 'Sign in to use the car line.' using errcode = '42501'; end if;
  if w->>'state' <> 'open' then return w; end if;
  dist := app.require_at_school(p_lat, p_lng, p_accuracy);
  v := app.pickup_vehicle(null);
  snap := app.vehicle_snapshot(v);
  with ins as (
    insert into carline_pickups (student_id, guardian_id, via, distance_m, vehicle)
      select k.student_id, auth.uid(), 'arrival', dist, snap from app.pickup_children() k(student_id)
      where not exists (select 1 from carline_pickups c where c.student_id = k.student_id
                          and c.day = app.school_today() and c.status in ('waiting', 'picked_up'))
    on conflict (student_id, day) where status = 'waiting' do nothing
    returning id, student_id
  )
  select array_agg(ins.id order by p.first_name), array_agg(p.first_name order by p.first_name)
    into ids, names from ins join profiles p on p.id = ins.student_id;
  if snap is not null and cardinality(ids) > 0 then update vehicles set last_used_at = now() where id = v.id; end if;
  return jsonb_build_object('state', 'open', 'checkedIn', coalesce(to_jsonb(ids), '[]'::jsonb),
                            'names', coalesce(to_jsonb(names), '[]'::jsonb));
end $$;

/** Staff see the vehicle on the board, next to the pickup number. */
create or replace function public.carline_board() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not app.is_staff() then raise exception 'The car line board is for school staff.' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', c.id, 'studentId', c.student_id, 'status', c.status, 'via', c.via,
      'arrivedAt', c.arrived_at, 'pickedUpAt', c.picked_up_at, 'distanceM', c.distance_m,
      'number', n.number, 'name', trim(s.first_name || ' ' || s.last_name), 'grade', s.grade,
      'parent', trim(g.first_name || ' ' || g.last_name),
      'vehicle', c.vehicle->>'label', 'vehicleColor', c.vehicle->>'color', 'vehicleKind', c.vehicle->>'kind',
      'pickedUpBy', trim(coalesce(b.first_name, '') || ' ' || coalesce(b.last_name, '')))
      order by c.arrived_at)
    from carline_pickups c
    join profiles s on s.id = c.student_id
    left join pickup_numbers n on n.student_id = c.student_id
    left join profiles g on g.id = c.guardian_id
    left join profiles b on b.id = c.picked_up_by
    where c.day = app.school_today() and c.status in ('waiting', 'picked_up')), '[]'::jsonb);
end $$;

revoke all on function app.pickup_vehicle(uuid, uuid) from public, anon, authenticated;
revoke all on function public.vehicle_save(uuid, text, text, text), public.vehicle_delete(uuid), public.vehicle_use(uuid) from public, anon;
grant execute on function public.vehicle_save(uuid, text, text, text), public.vehicle_delete(uuid), public.vehicle_use(uuid)
  to authenticated, service_role;

insert into app.applied_migrations (name) values ('20261019000021_carline_vehicles.sql') on conflict do nothing;

-- ===== 20261019000022_critical_alerts.sql =====
-- ======================================================================
-- Critical alerts for teachers and staff: severe weather, an active threat
-- (lockdown), a dangerous situation, or another urgent message from the
-- administration. Admins with "Send critical alerts" (alerts.send) send them
-- and mark them all clear; every teacher and staff member gets them and
-- answers I'm safe or I need help, and the senders watch the answers live.
-- Parents, students and Family accounts never see them.
--
-- Delivery: alerts always push, whatever someone's notification settings or
-- quiet hours. data.level tells the send-push function how loud to be:
-- 'critical' (rings on silent and Do Not Disturb) once Apple has granted the
-- Critical Alerts entitlement and app.settings critical_alerts = 'on';
-- 'time-sensitive' until then.
-- ======================================================================

insert into app.settings values ('critical_alerts', 'off') on conflict (key) do nothing;

create table public.critical_alerts (
  id         uuid primary key default gen_random_uuid(),
  kind       text not null check (kind in ('weather', 'threat', 'danger', 'other')),
  title      text not null check (char_length(trim(title)) between 1 and 120),
  body       text not null default '' check (char_length(body) <= 1000),
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  ended_at   timestamptz,
  ended_by   uuid references public.profiles (id) on delete set null,
  end_note   text check (char_length(end_note) <= 500)
);
create index critical_alerts_recent on public.critical_alerts (created_at desc);

create table public.critical_alert_responses (
  alert_id   uuid not null references public.critical_alerts (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  status     text not null check (status in ('safe', 'help')),
  note       text check (char_length(note) <= 300),
  updated_at timestamptz not null default now(),
  primary key (alert_id, user_id)
);

alter table public.critical_alerts enable row level security;
alter table public.critical_alert_responses enable row level security;
create policy "teachers and staff" on public.critical_alerts for select to authenticated using (app.is_staff());
create policy "your own answer, or the senders" on public.critical_alert_responses for select to authenticated
  using (user_id = auth.uid() or app.has_permission('alerts.send'));
grant select on public.critical_alerts, public.critical_alert_responses to authenticated;
revoke insert, update, delete on public.critical_alerts, public.critical_alert_responses from anon, authenticated;
grant all on public.critical_alerts, public.critical_alert_responses to service_role;
alter publication supabase_realtime add table public.critical_alerts, public.critical_alert_responses;

/** How loudly alert pushes ring: 'critical' once Apple's entitlement is in the app, else 'time-sensitive'. */
create function app.alert_level() returns text
language sql stable as $$ select case when app.setting('critical_alerts') = 'on' then 'critical' else 'time-sensitive' end $$;

create function app.alert_icon(kind text) returns text
language sql immutable as $$
  select case kind when 'weather' then '⛈️' when 'threat' then '🚨' when 'danger' then '⚠️' else '📣' end
$$;

/** Everyone a critical alert goes to. */
create function app.alert_staff() returns setof uuid
language sql stable security definer set search_path = public as $$
  select id from profiles where school_role in ('admin', 'teacher', 'staff')
$$;

-- Critical alert traffic always pushes: no setting or quiet hours holds it back.
create or replace function app.wants_push(n public.notifications, u uuid, at timestamptz default now()) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare st user_settings%rowtype; t time;
begin
  if n.data ? 'alertId' then return true; end if;
  if n.audience in ('everyone', 'roles') and n.urgent then return true; end if;
  select * into st from user_settings where user_id = u;
  if not found then return true; end if;
  if n.audience in ('everyone', 'roles') and not st.push_school then return false; end if;
  if n.data ? 'reply' then
    if not st.push_replies then return false; end if;
  elsif n.audience = 'group' and not st.push_groups then return false;
  end if;
  if n.data ? 'listingId' and not st.push_marketplace then return false; end if;
  if n.data ? 'opportunityId' and not st.push_volunteer then return false; end if;
  if st.quiet_start is not null then
    t := (at at time zone 'America/Chicago')::time;
    if (st.quiet_start <= st.quiet_end and t >= st.quiet_start and t < st.quiet_end)
       or (st.quiet_start > st.quiet_end and (t >= st.quiet_start or t < st.quiet_end)) then
      return false;
    end if;
  end if;
  return true;
end $$;

-- ----------------------------------------------------------------------
-- Sending, answering and ending an alert
-- ----------------------------------------------------------------------

create function public.critical_alert_send(p_kind text, p_title text, p_body text default '') returns public.critical_alerts
language plpgsql security definer set search_path = public as $$
declare a critical_alerts%rowtype;
begin
  perform app.require_permission('alerts.send');
  if p_kind is null or p_kind not in ('weather', 'threat', 'danger', 'other') then raise exception 'Pick what kind of alert this is.'; end if;
  if coalesce(trim(p_title), '') = '' then raise exception 'Add a short title.'; end if;
  if char_length(trim(p_title)) > 120 then raise exception 'Keep the title to 120 characters.'; end if;
  if char_length(coalesce(p_body, '')) > 1000 then raise exception 'Keep the message to 1,000 characters.'; end if;
  insert into critical_alerts (kind, title, body, created_by)
  values (p_kind, trim(p_title), coalesce(trim(p_body), ''), auth.uid()) returning * into a;
  insert into notifications (audience, roles, title, body, data, urgent, created_by)
  values ('roles', array['admin', 'teacher', 'staff'], app.alert_icon(a.kind) || ' ' || a.title,
          coalesce(nullif(a.body, ''), 'Open KH Royals for details.'),
          jsonb_build_object('alertId', a.id, 'kind', a.kind, 'critical', true, 'level', app.alert_level()), true, auth.uid());
  perform app.audit(null, 'alert.sent', a.id::text, jsonb_build_object('kind', a.kind, 'title', a.title));
  return a;
end $$;

/** A teacher or staff member answers: safe, or needs help (the senders are told at once). */
create function public.critical_alert_respond(p_alert uuid, p_status text, p_note text default null)
returns public.critical_alert_responses
language plpgsql security definer set search_path = public as $$
declare a critical_alerts%rowtype; r critical_alert_responses%rowtype; u uuid;
begin
  if not app.is_staff() then raise exception 'Critical alerts are for teachers and staff.' using errcode = '42501'; end if;
  select * into a from critical_alerts where id = p_alert;
  if not found then raise exception 'No such alert.'; end if;
  if a.ended_at is not null then raise exception 'This alert has ended.'; end if;
  if p_status is null or p_status not in ('safe', 'help') then raise exception 'Choose I''m safe or I need help.'; end if;
  if char_length(coalesce(p_note, '')) > 300 then raise exception 'Keep the note to 300 characters.'; end if;
  insert into critical_alert_responses (alert_id, user_id, status, note)
  values (a.id, auth.uid(), p_status, nullif(trim(p_note), ''))
  on conflict (alert_id, user_id) do update set status = excluded.status, note = excluded.note, updated_at = now()
  returning * into r;
  if p_status = 'help' then
    for u in select id from profiles
             where school_role is not null and id <> auth.uid() and ('alerts.send' = any (app.permissions(id)) or id = a.created_by) loop
      perform app.notify_user(u, '🆘 ' || app.short_name(auth.uid()) || ' needs help', coalesce(r.note, a.title),
        jsonb_build_object('alertId', a.id, 'kind', a.kind, 'critical', true, 'level', app.alert_level()));
    end loop;
  end if;
  return r;
end $$;

create function public.critical_alert_end(p_alert uuid, p_note text default null) returns public.critical_alerts
language plpgsql security definer set search_path = public as $$
declare a critical_alerts%rowtype;
begin
  perform app.require_permission('alerts.send');
  if char_length(coalesce(p_note, '')) > 500 then raise exception 'Keep the note to 500 characters.'; end if;
  update critical_alerts set ended_at = now(), ended_by = auth.uid(), end_note = nullif(trim(p_note), '')
   where id = p_alert and ended_at is null returning * into a;
  if not found then raise exception 'This alert has already ended.'; end if;
  insert into notifications (audience, roles, title, body, data, urgent, created_by)
  values ('roles', array['admin', 'teacher', 'staff'], '✅ All clear: ' || a.title, coalesce(a.end_note, 'The alert is over.'),
          jsonb_build_object('alertId', a.id, 'kind', a.kind, 'level', 'time-sensitive'), true, auth.uid());
  perform app.audit(null, 'alert.ended', a.id::text, jsonb_build_object('title', a.title));
  return a;
end $$;

/** For the senders: every teacher and staff member with their answer ('help', 'none' or 'safe'), most urgent first. */
create function public.critical_alert_status(p_alert uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform app.require_permission('alerts.send');
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', p.id, 'name', trim(p.first_name || ' ' || p.last_name), 'role', p.school_role,
      'status', coalesce(r.status, 'none'), 'note', r.note, 'updatedAt', r.updated_at)
      order by case coalesce(r.status, 'none') when 'help' then 0 when 'none' then 1 else 2 end, p.last_name, p.first_name)
    from profiles p
    left join critical_alert_responses r on r.alert_id = p_alert and r.user_id = p.id
    where p.id in (select * from app.alert_staff())), '[]'::jsonb);
end $$;

