-- ===== 20261027000039_carline_board_birthdays.sql =====
-- Car line board: birthdays.
--
-- The big-screen board (app/carline-board.tsx) puts a crown on a child's name on their
-- birthday and celebrates when they're announced. The board gets only `birthday`
-- true/false for today, never the date itself (birthdays stay in student_details).

/** Whether `b` is a birthday on `on_day` (the school's today by default); Feb 29 birthdays count on Feb 28 in other years. */
create function app.is_birthday(b date, on_day date default app.school_today()) returns boolean
language sql stable as $$
  select b is not null and (
    to_char(b, 'MM-DD') = to_char(on_day, 'MM-DD')
    or (to_char(b, 'MM-DD') = '02-29' and to_char(on_day, 'MM-DD') = '02-28'
        and extract(day from make_date(extract(year from on_day)::int, 3, 1) - 1) = 28))
$$;

create or replace function public.carline_board() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not app.is_staff() then raise exception 'The car line board is for school staff.' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', c.id, 'studentId', c.student_id, 'status', c.status, 'via', c.via,
      'arrivedAt', c.arrived_at, 'pickedUpAt', c.picked_up_at, 'distanceM', c.distance_m,
      'number', n.number, 'name', trim(s.first_name || ' ' || s.last_name), 'grade', s.grade,
      'parent', trim(g.first_name || ' ' || g.last_name),
      'vehicle', c.vehicle->>'label', 'vehicleColor', c.vehicle->>'color', 'vehicleKind', c.vehicle->>'kind',
      'birthday', app.is_birthday(d.birthday),
      'pickedUpBy', trim(coalesce(b.first_name, '') || ' ' || coalesce(b.last_name, '')))
      order by c.arrived_at)
    from carline_pickups c
    join profiles s on s.id = c.student_id
    left join student_details d on d.student_id = c.student_id
    left join pickup_numbers n on n.student_id = c.student_id
    left join profiles g on g.id = c.guardian_id
    left join profiles b on b.id = c.picked_up_by
    where c.day = app.school_today() and c.status in ('waiting', 'picked_up')), '[]'::jsonb);
end $$;

insert into app.applied_migrations (name) values ('20261027000039_carline_board_birthdays.sql') on conflict do nothing;

-- ===== 20261027000040_carline_festive.sql =====
-- Car line board: festive touches, on or off.
--
-- The big-screen board (app/carline-board.tsx) shows holiday scenes and birthday celebrations
-- (src/carline/festive.ts). Car line leads and the office (app.can_run_carline) turn them all off,
-- or one at a time, for every screen at once; carline_config() reports the choice. Everything is on
-- until switched off, so touches added later start on.

/** Every festive touch the board knows; the same list as FESTIVE in src/carline/festive.ts. */
create function app.festive_keys() returns text[]
language sql immutable as $$
  select array['birthdays', 'labor-day', 'fall-break', 'veterans-day', 'thanksgiving', 'christmas', 'mlk-day',
               'valentines', 'presidents-day', 'st-patricks', 'spring-break', 'easter', 'mothers-day', 'memorial-day']
$$;

insert into app.settings (key, value) values ('carline_festive', '{"enabled": true, "off": []}') on conflict (key) do nothing;

create or replace function public.carline_config() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'latitude', app.setting('carline_latitude')::float8,
    'longitude', app.setting('carline_longitude')::float8,
    'radius', app.setting('carline_radius_m')::float8,
    'start', app.setting('carline_start'),
    'end', app.setting('carline_end'),
    'line', app.carline_window(),
    'festive', coalesce(app.setting('carline_festive')::jsonb, '{"enabled": true, "off": []}'::jsonb),
    'canEdit', app.can_run_carline())
$$;

/** Car line leads and the office: turn the board's festive touches on or off (`p_off`: the ones switched off) for every screen. */
create function public.carline_set_festive(p_enabled boolean, p_off text[]) returns jsonb
language plpgsql security definer set search_path = public as $$
declare unknown text;
begin
  if not app.can_run_carline() then
    raise exception 'Only car line leads and the office can change car line settings.' using errcode = '42501';
  end if;
  select k into unknown from unnest(coalesce(p_off, '{}')) k where k <> all (app.festive_keys()) limit 1;
  if unknown is not null then raise exception 'Unknown festive touch: %', unknown; end if;
  insert into app.settings (key, value)
  values ('carline_festive', jsonb_build_object('enabled', coalesce(p_enabled, true),
          'off', coalesce((select jsonb_agg(distinct k order by k) from unnest(p_off) k), '[]'::jsonb))::text)
  on conflict (key) do update set value = excluded.value;
  perform app.audit(null, 'carline.festive', null, jsonb_build_object('enabled', p_enabled, 'off', p_off));
  return public.carline_config();
end $$;

revoke all on function public.carline_set_festive(boolean, text[]) from public, anon;
grant execute on function public.carline_set_festive(boolean, text[]) to authenticated, service_role;

insert into app.applied_migrations (name) values ('20261027000040_carline_festive.sql') on conflict do nothing;

-- ===== 20261028000041_teacher_calendar.sql =====
-- Teachers: their students' activities, and a calendar of their own.
--
-- My students' events: a teacher sees the schedule of the activities that students in the
-- class sections they lead are registered for (games, performances, meets), with which of
-- their students take part, so they can go and cheer them on. They only learn this for
-- students they already teach, and never see "Are you going?" answers.
--
-- My calendar: anyone on staff (teachers, staff, admins) keeps their own events: meetings,
-- duties, a game they'll go to. Private to them. An entry added from an activity's schedule
-- follows it: its time, place and cancellation come from the schedule, so a moved game moves
-- on their calendar too. When they add one, they can tell their students in it and the
-- students' parents that they're coming.

create table public.personal_events (
  id             uuid primary key default gen_random_uuid(),
  owner_id       uuid not null references public.profiles (id) on delete cascade,
  sport_event_id uuid references public.sport_events (id) on delete cascade,   -- set: follows that schedule item
  title          text check (title is null or char_length(trim(title)) between 1 and 120),
  starts_on      date,
  start_time     time,
  end_time       time,
  location       text check (location is null or char_length(location) <= 200),
  notes          text not null default '' check (char_length(notes) <= 1000),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (owner_id, sport_event_id),
  check (sport_event_id is not null or (title is not null and starts_on is not null)),
  check (end_time is null or (start_time is not null and end_time > start_time))
);
create index on public.personal_events (owner_id, starts_on);

alter table public.personal_events enable row level security;
create policy "your own calendar" on public.personal_events for select to authenticated using (owner_id = auth.uid());
grant select on public.personal_events to authenticated;
revoke insert, update, delete on public.personal_events from anon, authenticated;
grant all on public.personal_events to service_role;

/** The students in class sections teacher `t` leads who are registered for this season. */
create function app.class_students_in(p_season uuid, t uuid default auth.uid()) returns setof uuid
language sql stable security definer set search_path = public as $$
  select distinct g.student_id
  from sport_registrations g
  join roster_members m on m.profile_id = g.student_id
  join rosters r on r.id = m.roster_id
  where g.season_id = p_season and g.status = 'registered'
    and r.kind = 'section' and r.lead_id = t and app.is_staff(t)
$$;

-- ======================================================================
-- My students' events
-- ======================================================================

/**
 * For a teacher: activity schedule items from `p_from` to `p_to` (school dates) that students
 * in their classes are registered for, soonest first, with those students and whether the
 * item is on the teacher's own calendar.
 */
create function public.student_events(p_from date default app.school_today(), p_to date default app.school_today() + 60)
returns table (
  id uuid, season_id uuid, sport_id uuid, sport_name text, sport_icon text, kind text, title text,
  starts_at timestamptz, ends_at timestamptz, location text, address text, home boolean, notes text, cancelled boolean,
  students jsonb, planned boolean
)
language sql stable security definer set search_path = public as $$
  with mine as (
    select distinct m.profile_id as sid
    from rosters r join roster_members m on m.roster_id = r.id join profiles p on p.id = m.profile_id
    where r.kind = 'section' and r.lead_id = auth.uid() and app.is_staff() and p.school_role = 'student'
  ), taking_part as (
    select e.id as event_id, p.id as sid, trim(p.first_name || ' ' || p.last_name) as name, p.first_name, p.last_name
    from sport_events e
    join sport_registrations g on g.season_id = e.season_id and g.status = 'registered'
    join mine on mine.sid = g.student_id
    join profiles p on p.id = g.student_id
    where (e.starts_at at time zone 'America/Chicago')::date between p_from and least(p_to, p_from + 400)
  )
  select e.id, e.season_id, se.sport_id, s.name, s.icon, e.kind, e.title, e.starts_at, e.ends_at, e.location, e.address,
         e.home, e.notes, e.cancelled,
         jsonb_agg(jsonb_build_object('id', k.sid, 'name', k.name) order by k.last_name, k.first_name),
         exists (select 1 from personal_events pe where pe.owner_id = auth.uid() and pe.sport_event_id = e.id)
  from taking_part k
  join sport_events e on e.id = k.event_id
  join sport_seasons se on se.id = e.season_id
  join sports s on s.id = se.sport_id
  group by e.id, se.sport_id, s.name, s.icon
  order by e.starts_at, s.name
$$;

-- ======================================================================
-- My calendar
-- ======================================================================

create function app.require_own_calendar() returns void
language plpgsql stable as $$
begin
  if not app.is_staff() then raise exception 'My calendar is for teachers and staff.' using errcode = '42501'; end if;
end $$;

/**
 * The signed-in person's calendar from `p_from` to `p_to`: what they added, and the activity
 * schedule items they plan to go to (as the schedule has them now). Times are 24-hour HH:MM
 * in school time; `end_time` is null for an item that ends on another day.
 */
create function public.my_calendar(p_from date default app.school_today(), p_to date default app.school_today() + 60)
returns table (
  id uuid, sport_event_id uuid, sport_id uuid, title text, starts_on date, start_time text, end_time text,
  location text, address text, notes text, cancelled boolean
)
language sql stable security definer set search_path = public as $$
  select * from (
    select pe.id, pe.sport_event_id, se.sport_id,
           case when e.id is null then pe.title else app.sport_label(se.sport_id) || ' · ' || e.title end as title,
           coalesce((e.starts_at at time zone 'America/Chicago')::date, pe.starts_on) as starts_on,
           to_char(coalesce((e.starts_at at time zone 'America/Chicago')::time, pe.start_time), 'HH24:MI') as start_time,
           to_char(case
             when e.id is null then pe.end_time
             when (e.ends_at at time zone 'America/Chicago')::date = (e.starts_at at time zone 'America/Chicago')::date
               then (e.ends_at at time zone 'America/Chicago')::time
           end, 'HH24:MI') as end_time,
           coalesce(e.location, pe.location) as location, e.address, pe.notes, coalesce(e.cancelled, false) as cancelled
    from personal_events pe
    left join sport_events e on e.id = pe.sport_event_id
    left join sport_seasons se on se.id = e.season_id
    where pe.owner_id = auth.uid() and app.is_staff()
  ) c
  where c.starts_on between p_from and least(p_to, p_from + 400)
  order by c.starts_on, c.start_time nulls first, c.title
$$;

/** Add (no `p_id`) or change one of your own events. Times are optional; an end time needs a start. */
create function public.personal_event_save(
  p_id uuid, p_title text, p_on date, p_start time default null, p_end time default null,
  p_location text default null, p_notes text default ''
) returns public.personal_events
language plpgsql security definer set search_path = public as $$
declare row personal_events%rowtype; t text := trim(coalesce(p_title, ''));
begin
  perform app.require_own_calendar();
  if t = '' then raise exception 'Give it a title.'; end if;
  if char_length(t) > 120 then raise exception 'Keep the title to 120 characters.'; end if;
  if p_on is null then raise exception 'Pick a date.'; end if;
  if p_end is not null and (p_start is null or p_end <= p_start) then raise exception 'The end time must be after the start time.'; end if;
  if char_length(coalesce(p_location, '')) > 200 then raise exception 'Keep the place to 200 characters.'; end if;
  if char_length(coalesce(p_notes, '')) > 1000 then raise exception 'Keep the notes to 1000 characters.'; end if;
  if p_id is null then
    insert into personal_events (owner_id, title, starts_on, start_time, end_time, location, notes)
    values (auth.uid(), t, p_on, p_start, p_end, nullif(trim(coalesce(p_location, '')), ''), trim(coalesce(p_notes, '')))
    returning * into row;
  else
    update personal_events set title = t, starts_on = p_on, start_time = p_start, end_time = p_end,
      location = nullif(trim(coalesce(p_location, '')), ''), notes = trim(coalesce(p_notes, '')), updated_at = now()
    where id = p_id and owner_id = auth.uid() and sport_event_id is null
    returning * into row;
    if not found then raise exception 'That isn''t one of your own events.'; end if;
  end if;
  return row;
end $$;

create function public.personal_event_delete(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform app.require_own_calendar();
  delete from personal_events where id = p_id and owner_id = auth.uid();
  if not found then raise exception 'That isn''t on your calendar.'; end if;
end $$;

/**
 * Put an activity schedule item on your calendar (`p_going`), or take it off. With `p_tell`,
 * the students in your classes who take part (those with a login) and their parents hear that
 * you're coming, once. Returns how many of your students were told.
 */
create function public.student_event_plan(p_event uuid, p_going boolean, p_tell boolean default false) returns int
language plpgsql security definer set search_path = public as $$
declare e sport_events%rowtype; sport uuid; added int; who text; told int := 0; r record;
begin
  perform app.require_own_calendar();
  select * into e from sport_events where id = p_event;
  if not found then raise exception 'That schedule item is gone.'; end if;
  if not coalesce(p_going, false) then
    delete from personal_events where owner_id = auth.uid() and sport_event_id = e.id;
    return 0;
  end if;
  if e.cancelled then raise exception 'This was cancelled.'; end if;
  if coalesce(e.ends_at, e.starts_at + interval '3 hours') < now() then raise exception 'This is already over.'; end if;
  insert into personal_events (owner_id, sport_event_id) values (auth.uid(), e.id) on conflict (owner_id, sport_event_id) do nothing;
  get diagnostics added = row_count;
  if added = 0 or not coalesce(p_tell, false) then return 0; end if;

  sport := app.season_sport(e.season_id);
  select coalesce(nullif(trim(first_name || ' ' || last_name), ''), 'Your teacher') into who from profiles where id = auth.uid();
  for r in
    select distinct g.uid, g.student from app.class_students_in(e.season_id) s(sid)
    cross join lateral (select s.sid, true union select guardian_id, false from guardians where student_id = s.sid) g(uid, student)
    join profiles p on p.id = g.uid
    where p.school_role is not null and not (g.student and p.managed)
  loop
    perform app.notify_user(r.uid, '📣 ' || who || ' is coming!',
      app.sport_label(sport) || ' · ' || e.title || ' · ' || app.sport_when(e.starts_at), jsonb_build_object('sportId', sport));
    if r.student then told := told + 1; end if;
  end loop;
  return told;
end $$;

revoke all on function public.student_events(date, date), public.my_calendar(date, date),
  public.personal_event_save(uuid, text, date, time, time, text, text), public.personal_event_delete(uuid),
  public.student_event_plan(uuid, boolean, boolean) from public, anon;
grant execute on function public.student_events(date, date), public.my_calendar(date, date),
  public.personal_event_save(uuid, text, date, time, time, text, text), public.personal_event_delete(uuid),
  public.student_event_plan(uuid, boolean, boolean) to authenticated, service_role;

insert into app.applied_migrations (name) values ('20261028000041_teacher_calendar.sql') on conflict do nothing;

-- ===== 20261028000042_feedback.sql =====
-- Feedback: anyone with an approved account reports a bug or suggests a feature from inside the
-- app (the Feedback app, or My profile → Send feedback), and sees their own reports, what became
-- of them and the team's reply. Triage (the new feedback.triage permission: the IT role, directors
-- and administrators) sees everything, sets each report's status and priority, replies to the
-- sender, and groups reports into workshops: sessions where students learn by working on the
-- app's real bugs and feature requests.
--
-- Kinds, areas and statuses are listed in both src/feedback/kinds.ts and the checks below.

create or replace function public.permission_catalog() returns table (key text, label text, description text)
language sql immutable as $$
  values
    ('admins.manage',    'Manage admins',         'Make or remove admins, set tiers and grant permissions (director only).'),
    ('people.view',      'View people',           'See everyone''s contact email in the admin portal.'),
    ('people.approve',   'Approve sign-ups',      'Approve new accounts as parents, students or family.'),
    ('people.roles',     'Change roles',          'Set anyone''s school role, including teachers and staff.'),
    ('people.family',    'Families & rosters',    'Link parents and family to students, set grades, manage classes, class/team rosters and car line duty.'),
    ('groups.manage',    'Manage all groups',     'Act as owner of every group: settings, members, moderation.'),
    ('calendar.school',  'School calendar',       'Add, change and remove school-wide calendar events.'),
    ('push.send',        'Send notifications',    'Send push notifications to everyone, a role or any group.'),
    ('alerts.send',      'Send critical alerts',  'Send critical alerts (severe weather, an active threat, a dangerous situation) to every teacher and staff member, see who''s safe, and give the all clear.'),
    ('questions.manage', 'Route questions',       'See every question sent to the school, assign it to faculty or staff, and answer it.'),
    ('messages.review',  'Student messages',      'Read every Ask the Teacher conversation between students and teachers, for safety.'),
    ('sports.manage',    'Manage activities',     'Add activities (sports, theater, music, art, clubs) and seasons, set schedules, assign coaches and directors, and approve sign-ups.'),
    ('forms.send',       'Send forms',            'Send forms (permission slips, releases, acknowledgments) to any class, activity, grade or the whole school, and see every form''s signatures.'),
    ('people.delete',    'Delete accounts',       'Permanently delete someone''s account, with their posts and comments. Deleting an admin also needs Manage admins.'),
    ('gallery.manage',   'Manage photo gallery',  'Change or remove any photo album or photo, not just your own.'),
    ('feedback.triage',  'Triage feedback',       'See every bug report and feature request sent from the app, set its status and priority, reply, and plan student workshops from them.'),
    ('audit.view',       'Activity log',          'Review the school-wide activity log.')
$$;

update public.admin_roles set permissions = permissions || 'feedback.triage'::text
where id in ('director', 'administrator') and not ('feedback.triage' = any (permissions));

-- A ready-made role for the school's IT people; directors give it to someone in the admin portal.
insert into public.admin_roles (id, name, description, permissions) values
  ('it', 'IT', 'Triages bug reports and feature requests sent from the app, and plans student workshops from them.',
   array['feedback.triage'])
on conflict (id) do nothing;

create table public.feedback_workshops (
  id          uuid primary key default gen_random_uuid(),
  title       text not null check (char_length(trim(title)) between 1 and 100),
  description text not null default '' check (char_length(description) <= 2000),
  held_on     date,
  created_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table public.feedback (
  id          uuid primary key default gen_random_uuid(),
  author_id   uuid not null references public.profiles (id) on delete cascade,
  kind        text not null check (kind in ('bug', 'idea')),
  area        text not null default 'other' check (area in (
                'planner', 'connect', 'carline', 'calendar', 'activities', 'volunteer', 'market', 'forms',
                'students', 'questions', 'photos', 'news', 'alerts', 'profile', 'admin', 'other')),
  title       text not null check (char_length(trim(title)) between 1 and 120),
  details     text not null default '' check (char_length(details) <= 4000),
  device      text not null default '' check (char_length(device) <= 200),   -- "ios 27.0 · app 0.1.0"
  status      text not null default 'new' check (status in ('new', 'reviewing', 'planned', 'in_progress', 'done', 'declined')),
  priority    text check (priority in ('low', 'medium', 'high')),
  reply       text not null default '' check (char_length(reply) <= 2000),   -- shown to the sender
  workshop_id uuid references public.feedback_workshops (id) on delete set null,
  triaged_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index on public.feedback (author_id, created_at desc);
create index on public.feedback (status, created_at desc);
create index on public.feedback (workshop_id);

alter table public.feedback enable row level security;
alter table public.feedback_workshops enable row level security;
create policy "your own, or triage" on public.feedback for select to authenticated
  using (author_id = auth.uid() or app.has_permission('feedback.triage'));
create policy "triage" on public.feedback_workshops for select to authenticated using (app.has_permission('feedback.triage'));
grant select on public.feedback, public.feedback_workshops to authenticated;
revoke insert, update, delete on public.feedback, public.feedback_workshops from anon, authenticated;
grant all on public.feedback, public.feedback_workshops to service_role;

/** Who triages feedback (for new-report notifications). */
create function app.feedback_team() returns setof uuid
language sql stable security definer set search_path = public as $$
  select id from profiles
  where school_role is not null and (admin_tier is not null or cardinality(permissions) > 0)
    and 'feedback.triage' = any (app.permissions(id))
$$;

create function app.feedback_status_label(s text) returns text
language sql immutable as $$
  select case s when 'new' then 'New' when 'reviewing' then 'Being reviewed' when 'planned' then 'Planned'
    when 'in_progress' then 'Being worked on' when 'done' then 'Done' when 'declined' then 'Not planned' else s end
$$;

/** Send a bug report or feature idea. The triage team is told. */
create function public.feedback_send(p_kind text, p_area text, p_title text, p_details text default '', p_device text default '')
returns public.feedback
language plpgsql security definer set search_path = public as $$
declare row feedback%rowtype; t text := trim(coalesce(p_title, '')); x uuid;
begin
  if app.school_role() is null then raise exception 'Sign in with an approved account to send feedback.' using errcode = '42501'; end if;
  if p_kind is null or p_kind not in ('bug', 'idea') then raise exception 'Choose a bug or an idea.'; end if;
  if t = '' then raise exception 'Give it a short title.'; end if;
  if char_length(t) > 120 then raise exception 'Keep the title to 120 characters.'; end if;
  if char_length(coalesce(p_details, '')) > 4000 then raise exception 'Keep the details to 4000 characters.'; end if;
  if (select count(*) from feedback where author_id = auth.uid() and created_at > now() - interval '1 day') >= 20 then
    raise exception 'That''s a lot of feedback for one day. Thank you! Send more tomorrow.';
  end if;
  insert into feedback (author_id, kind, area, title, details, device)
  values (auth.uid(), p_kind, coalesce(nullif(p_area, ''), 'other'), t, trim(coalesce(p_details, '')), left(trim(coalesce(p_device, '')), 200))
  returning * into row;
  for x in select app.feedback_team() loop
    if x <> auth.uid() then
      perform app.notify_user(x, case when p_kind = 'bug' then '🐞 Bug report: ' else '💡 Feature idea: ' end || t,
        app.short_name(auth.uid()) || coalesce(' · ' || nullif(left(row.details, 120), ''), ''), jsonb_build_object('feedbackId', row.id));
    end if;
  end loop;
  return row;
end $$;

/**
 * For triage: set a report's status, priority, reply to the sender and workshop (null clears
 * priority and workshop). The sender hears when the status or the reply changes.
 */
create function public.feedback_triage(p_id uuid, p_status text, p_priority text default null, p_reply text default '', p_workshop uuid default null)
returns public.feedback
language plpgsql security definer set search_path = public as $$
declare old feedback%rowtype; row feedback%rowtype; r text := trim(coalesce(p_reply, ''));
begin
  perform app.require_permission('feedback.triage');
  select * into old from feedback where id = p_id for update;
  if not found then raise exception 'That feedback is gone.'; end if;
  if p_status is null or p_status not in ('new', 'reviewing', 'planned', 'in_progress', 'done', 'declined') then raise exception 'Choose a status.'; end if;
  if p_priority is not null and p_priority not in ('low', 'medium', 'high') then raise exception 'Choose low, medium or high.'; end if;
  if char_length(r) > 2000 then raise exception 'Keep the reply to 2000 characters.'; end if;
  if p_workshop is not null and not exists (select 1 from feedback_workshops where id = p_workshop) then raise exception 'That workshop is gone.'; end if;
  update feedback set status = p_status, priority = p_priority, reply = r, workshop_id = p_workshop,
    triaged_by = auth.uid(), updated_at = now()
  where id = p_id returning * into row;
  if (row.status is distinct from old.status or row.reply is distinct from old.reply) and row.author_id <> auth.uid() then
    perform app.notify_user(row.author_id, '🛠️ ' || row.title,
      app.feedback_status_label(row.status) || coalesce(' · ' || nullif(left(row.reply, 140), ''), ''), jsonb_build_object('feedbackId', row.id));
  end if;
  return row;
end $$;

/**
 * Feedback this person may see, newest first: their own, or (triage) everyone's, with the
 * sender's name and role and the workshop's title.
 */
create function public.feedback_list()
returns table (
  id uuid, author_id uuid, author_name text, author_role text, kind text, area text, title text, details text, device text,
  status text, priority text, reply text, workshop_id uuid, workshop_title text, created_at timestamptz, updated_at timestamptz
)
language sql stable security definer set search_path = public as $$
  select f.id, f.author_id, trim(p.first_name || ' ' || p.last_name), p.school_role, f.kind, f.area, f.title, f.details, f.device,
         f.status, f.priority, f.reply, f.workshop_id, w.title, f.created_at, f.updated_at
  from feedback f
  join profiles p on p.id = f.author_id
  left join feedback_workshops w on w.id = f.workshop_id
  where f.author_id = auth.uid() or app.has_permission('feedback.triage')
  order by f.created_at desc
$$;

/** Triage: add (no `p_id`) or change a workshop. */
create function public.feedback_workshop_save(p_id uuid, p_title text, p_description text default '', p_held_on date default null)
returns public.feedback_workshops
language plpgsql security definer set search_path = public as $$
declare row feedback_workshops%rowtype; t text := trim(coalesce(p_title, ''));
begin
  perform app.require_permission('feedback.triage');
  if t = '' then raise exception 'Give the workshop a title.'; end if;
  if char_length(t) > 100 then raise exception 'Keep the title to 100 characters.'; end if;
  if char_length(coalesce(p_description, '')) > 2000 then raise exception 'Keep the description to 2000 characters.'; end if;
  if p_id is null then
    insert into feedback_workshops (title, description, held_on, created_by)
    values (t, trim(coalesce(p_description, '')), p_held_on, auth.uid()) returning * into row;
  else
    update feedback_workshops set title = t, description = trim(coalesce(p_description, '')), held_on = p_held_on, updated_at = now()
    where id = p_id returning * into row;
    if not found then raise exception 'That workshop is gone.'; end if;
  end if;
  return row;
end $$;

/** Triage: remove a workshop; its feedback stays, no longer in a workshop. */
create function public.feedback_workshop_delete(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform app.require_permission('feedback.triage');
  delete from feedback_workshops where id = p_id;
  if not found then raise exception 'That workshop is gone.'; end if;
end $$;

revoke all on function public.feedback_send(text, text, text, text, text), public.feedback_triage(uuid, text, text, text, uuid),
  public.feedback_list(), public.feedback_workshop_save(uuid, text, text, date), public.feedback_workshop_delete(uuid) from public, anon;
grant execute on function public.feedback_send(text, text, text, text, text), public.feedback_triage(uuid, text, text, text, uuid),
  public.feedback_list(), public.feedback_workshop_save(uuid, text, text, date), public.feedback_workshop_delete(uuid)
  to authenticated, service_role;

