-- ----------------------------------------------------------------------
-- Helpers
-- ----------------------------------------------------------------------

/** "Ava Reyes", or "Someone" for a deleted account. */
create function app.checkin_name(u uuid) returns text
language sql stable security definer set search_path = public as $$
  select coalesce((select nullif(trim(first_name || ' ' || last_name), '') from profiles where id = u), 'Someone')
$$;

/** "1:15 PM" on the school's clock. */
create function app.checkin_time(t timestamptz) returns text
language sql stable as $$ select to_char(t at time zone 'America/Chicago', 'FMHH12:MI AM') $$;

create function app.checkin_reason(r text) returns text
language sql immutable as $$
  select case r when 'late' then 'Late arrival' when 'appointment' then 'Appointment' when 'illness' then 'Sick'
                when 'family' then 'Family' else 'Other' end
$$;

/** Everyone who may take this child today: parents, linked family, and approved pickup people (their relationship). */
create function app.pickup_people(s uuid) returns table (person_id uuid, relation text)
language sql stable security definer set search_path = public as $$
  select g.guardian_id, coalesce(g.relation, 'parent') from guardians g where g.student_id = s and not app.is_family(g.guardian_id)
  union
  select f.family_id, 'family' from family_pickups f where f.student_id = s
  union
  select a.person_id, a.relationship from pickup_authorizations a
  where a.student_id = s and app.school_today() between a.starts_on and coalesce(a.ends_on, app.school_today())
    and coalesce(app.school_role(a.person_id), 'student') <> 'student'
$$;

/** The child's parents (never Family accounts) hear about every check-in and check-out. */
create function app.notify_parents(s uuid, title text, body text, data jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare g uuid;
begin
  for g in select guardian_id from guardians where student_id = s and not app.is_family(guardian_id) loop
    perform app.notify_user(g, title, body, data);
  end loop;
end $$;

-- ----------------------------------------------------------------------
-- School: late arrivals and early check-outs (the front office)
-- ----------------------------------------------------------------------

create table public.school_checks (
  id          uuid primary key default gen_random_uuid(),
  student_id  uuid not null references public.profiles (id) on delete cascade,
  day         date not null default app.school_today(),
  kind        text not null check (kind in ('in', 'out')),
  person_id   uuid references public.profiles (id) on delete set null,   -- who took them (out); who brought them, if given (in)
  reason      text not null default 'other' check (reason in ('late', 'appointment', 'illness', 'family', 'other')),
  note        text not null default '' check (char_length(note) <= 300),
  recorded_by uuid references public.profiles (id) on delete set null,
  at          timestamptz not null default now()
);
create index on public.school_checks (day, at);
create index on public.school_checks (student_id, at desc);

alter table public.school_checks enable row level security;
create policy "the office, and the child's parents and the child" on public.school_checks for select to authenticated
  using (app.has_permission('checkin.manage') or app.is_guardian_of(student_id) or student_id = auth.uid());

/** checkin.manage: check a student in (arriving late) or out (leaving early, only to someone on their pickup list). */
create function public.school_check(p_student uuid, p_kind text, p_person uuid default null, p_reason text default 'other', p_note text default '')
returns uuid
language plpgsql security definer set search_path = public as $$
declare new_id uuid; kid text;
begin
  perform app.require_permission('checkin.manage');
  if p_kind is null or p_kind not in ('in', 'out') then raise exception 'Choose check in or check out.'; end if;
  if not exists (select 1 from profiles where id = p_student and school_role = 'student') then raise exception 'Choose a student.'; end if;
  if coalesce(p_reason, 'other') not in ('late', 'appointment', 'illness', 'family', 'other') then raise exception 'Choose a reason.'; end if;
  if char_length(coalesce(p_note, '')) > 300 then raise exception 'Keep the note under 300 characters.'; end if;
  kid := app.checkin_name(p_student);
  if p_kind = 'out' then
    if p_person is null then raise exception 'Choose who is taking %.', kid; end if;
    if not exists (select 1 from app.pickup_people(p_student) where person_id = p_person) then
      raise exception '% isn''t on %''s pickup list. Only their parents, linked family and approved pickup people can take them.',
        app.checkin_name(p_person), kid using errcode = '42501';
    end if;
  end if;

  insert into school_checks (student_id, kind, person_id, reason, note, recorded_by)
  values (p_student, p_kind, p_person, coalesce(p_reason, 'other'), trim(coalesce(p_note, '')), auth.uid())
  returning id into new_id;

  perform app.notify_parents(p_student,
    case p_kind when 'in' then '✅ ' || kid || ' checked in at school' else '👋 ' || kid || ' checked out of school' end,
    concat_ws(' · ', app.checkin_time(now()), case when p_person is not null then 'with ' || app.checkin_name(p_person) end,
              app.checkin_reason(coalesce(p_reason, 'other'))),
    jsonb_build_object('schoolCheckId', new_id, 'children', true));
  perform app.audit(null, 'checkin.' || p_kind, p_student::text, jsonb_build_object('person', p_person, 'reason', p_reason));
  return new_id;
end $$;

/** checkin.manage: take back today's check-in or check-out (a mis-tap). */
create function public.school_check_undo(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare c school_checks;
begin
  perform app.require_permission('checkin.manage');
  delete from school_checks where id = p_id and day = app.school_today() returning * into c;
  if not found then raise exception 'Only today''s check-ins and check-outs can be undone.'; end if;
  perform app.audit(null, 'checkin.undone', c.student_id::text, jsonb_build_object('kind', c.kind));
end $$;

/** checkin.manage: students by name (all of them when empty), with where they stand today. */
create function public.checkin_students(p_query text default '') returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform app.require_permission('checkin.manage');
  return coalesce((select jsonb_agg(x) from (
    select jsonb_build_object('id', p.id, 'name', trim(p.first_name || ' ' || p.last_name), 'grade', p.grade,
      'status', c.kind, 'at', c.at) as x
    from profiles p
    left join lateral (select kind, at from school_checks where student_id = p.id and day = app.school_today() order by at desc limit 1) c on true
    where p.school_role = 'student'
      and (coalesce(trim(p_query), '') = '' or (p.first_name || ' ' || p.last_name) ilike '%' || trim(p_query) || '%')
    order by p.last_name, p.first_name
    limit 40) q), '[]'::jsonb);
end $$;

/** checkin.manage: today's check-ins and check-outs, newest first. */
create function public.checkin_today() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform app.require_permission('checkin.manage');
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', c.id, 'studentId', c.student_id, 'studentName', app.checkin_name(c.student_id), 'kind', c.kind,
      'person', case when c.person_id is not null then app.checkin_name(c.person_id) end,
      'reason', c.reason, 'note', c.note, 'by', app.checkin_name(c.recorded_by), 'at', c.at) order by c.at desc)
    from school_checks c where c.day = app.school_today()), '[]'::jsonb);
end $$;

-- ----------------------------------------------------------------------
-- Events: check-out lists (teachers, coaches and directors)
-- ----------------------------------------------------------------------

create table public.checkout_lists (
  id             uuid primary key default gen_random_uuid(),
  title          text not null check (char_length(trim(title)) between 1 and 120),
  day            date not null default app.school_today(),
  sport_event_id uuid references public.sport_events (id) on delete cascade,   -- an Activities event; null for one a teacher made
  created_by     uuid references public.profiles (id) on delete set null,
  created_at     timestamptz not null default now()
);
create unique index on public.checkout_lists (sport_event_id) where sport_event_id is not null;
create index on public.checkout_lists (day);

create table public.checkout_list_students (
  list_id    uuid not null references public.checkout_lists (id) on delete cascade,
  student_id uuid not null references public.profiles (id) on delete cascade,
  primary key (list_id, student_id)
);

create table public.checkout_releases (
  list_id     uuid not null,
  student_id  uuid not null,
  released_to uuid references public.profiles (id) on delete set null,
  released_by uuid references public.profiles (id) on delete set null,
  at          timestamptz not null default now(),
  primary key (list_id, student_id),
  foreign key (list_id, student_id) references public.checkout_list_students (list_id, student_id) on delete cascade
);

/** Who runs a check-out list: its maker, the activity's coaches and directors (for an Activities event), and checkin.manage. Staff only. */
create function app.manages_checkout(l uuid, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.is_staff(u) and exists (
    select 1 from checkout_lists c
    left join sport_events e on e.id = c.sport_event_id
    left join sport_seasons ss on ss.id = e.season_id
    where c.id = l and (c.created_by = u or app.has_permission('checkin.manage', u)
                        or (ss.sport_id is not null and app.can_manage_sport(ss.sport_id, u))))
$$;

alter table public.checkout_lists enable row level security;
alter table public.checkout_list_students enable row level security;
alter table public.checkout_releases enable row level security;
create policy "the people running it" on public.checkout_lists for select to authenticated using (app.manages_checkout(id));
create policy "the people running it, and the child's parents" on public.checkout_list_students for select to authenticated
  using (app.manages_checkout(list_id) or app.is_guardian_of(student_id));
create policy "the people running it, and the child's parents" on public.checkout_releases for select to authenticated
  using (app.manages_checkout(list_id) or app.is_guardian_of(student_id));

/** Staff: a check-out list for a field trip, class party or the like, from students in the sections they lead (checkin.manage: any student). */
create function public.checkout_list_save(p_title text, p_day date, p_students uuid[]) returns uuid
language plpgsql security definer set search_path = public as $$
declare new_id uuid; s uuid;
begin
  if not app.is_staff() then raise exception 'Check-out lists are for teachers and staff.' using errcode = '42501'; end if;
  if coalesce(trim(p_title), '') = '' then raise exception 'Give the list a name, like "Zoo field trip".'; end if;
  if p_day is null or p_day < app.school_today() then raise exception 'Choose today or a day coming up.'; end if;
  if coalesce(cardinality(p_students), 0) = 0 then raise exception 'Choose the students going.'; end if;
  foreach s in array p_students loop
    if not exists (select 1 from profiles where id = s and school_role = 'student') then raise exception 'Choose students only.'; end if;
    if not app.has_permission('checkin.manage') and not exists (
      select 1 from rosters r join roster_members m on m.roster_id = r.id
      where r.kind = 'section' and r.lead_id = auth.uid() and m.profile_id = s) then
      raise exception '% isn''t in a class you lead.', app.checkin_name(s) using errcode = '42501';
    end if;
  end loop;
  insert into checkout_lists (title, day, created_by) values (trim(p_title), p_day, auth.uid()) returning id into new_id;
  insert into checkout_list_students (list_id, student_id) select new_id, x from unnest(p_students) x on conflict do nothing;
  return new_id;
end $$;

/** An Activities event's coaches and directors (or checkin.manage): its check-out list, with every registered student (added if new). */
create function public.checkout_list_for_event(p_event uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare e sport_events; sport uuid; sport_name text; list uuid;
begin
  select * into e from sport_events where id = p_event;
  if not found then raise exception 'That event is gone.'; end if;
  select ss.sport_id, sp.name into sport, sport_name from sport_seasons ss join sports sp on sp.id = ss.sport_id where ss.id = e.season_id;
  if not app.is_staff() or not (app.can_manage_sport(sport) or app.has_permission('checkin.manage')) then
    raise exception 'Only the activity''s coaches and directors can check students out of it.' using errcode = '42501';
  end if;
  insert into checkout_lists (title, day, sport_event_id, created_by)
  values (left(sport_name || ': ' || e.title, 120), (e.starts_at at time zone 'America/Chicago')::date, e.id, auth.uid())
  on conflict (sport_event_id) where sport_event_id is not null do nothing;
  select id into list from checkout_lists where sport_event_id = e.id;
  insert into checkout_list_students (list_id, student_id)
  select list, r.student_id from sport_registrations r where r.season_id = e.season_id and r.status = 'registered'
  on conflict do nothing;
  return list;
end $$;

/** The list's maker or checkin.manage: remove a list. */
create function public.checkout_list_delete(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from checkout_lists where id = p_id and (created_by = auth.uid() or app.has_permission('checkin.manage'))) then
    raise exception 'Only the person who made the list can remove it.' using errcode = '42501';
  end if;
  delete from checkout_lists where id = p_id;
end $$;

/** Release a child from a list, only to someone on their pickup list; their parents are told. */
create function public.checkout_release(p_list uuid, p_student uuid, p_person uuid) returns void
language plpgsql security definer set search_path = public as $$
declare title text; kid text;
begin
  if not app.manages_checkout(p_list) then raise exception 'Only the people running this list can check students out.' using errcode = '42501'; end if;
  if not exists (select 1 from checkout_list_students where list_id = p_list and student_id = p_student) then
    raise exception 'That student isn''t on this list.';
  end if;
  kid := app.checkin_name(p_student);
  if p_person is null or not exists (select 1 from app.pickup_people(p_student) where person_id = p_person) then
    raise exception '% isn''t on %''s pickup list. Only their parents, linked family and approved pickup people can take them.',
      app.checkin_name(p_person), kid using errcode = '42501';
  end if;
  insert into checkout_releases (list_id, student_id, released_to, released_by) values (p_list, p_student, p_person, auth.uid())
  on conflict (list_id, student_id) do update set released_to = excluded.released_to, released_by = excluded.released_by, at = now();
  select c.title into title from checkout_lists c where c.id = p_list;
  perform app.notify_parents(p_student, '👋 ' || kid || ' checked out of ' || title,
    app.checkin_time(now()) || ' · with ' || app.checkin_name(p_person),
    jsonb_build_object('checkoutListId', p_list, 'children', true));
  perform app.audit(null, 'checkout.released', p_student::text, jsonb_build_object('list', p_list, 'person', p_person));
end $$;

/** Take back a release (a mis-tap). */
create function public.checkout_unrelease(p_list uuid, p_student uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not app.manages_checkout(p_list) then raise exception 'Only the people running this list can change it.' using errcode = '42501'; end if;
  delete from checkout_releases where list_id = p_list and student_id = p_student;
end $$;

/** Lists the caller runs, from a week back on, with how many are still waiting. */
create function public.checkout_my_lists() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'title', c.title, 'day', c.day, 'sportEventId', c.sport_event_id,
      'students', (select count(*) from checkout_list_students s where s.list_id = c.id),
      'released', (select count(*) from checkout_releases r where r.list_id = c.id),
      'mine', c.created_by = auth.uid()) order by c.day, c.title), '[]'::jsonb)
  from checkout_lists c where c.day >= app.school_today() - 7 and app.manages_checkout(c.id)
$$;

/** One list: each student, and who took them and when. */
create function public.checkout_list(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not app.manages_checkout(p_id) then raise exception 'Only the people running this list can see it.' using errcode = '42501'; end if;
  return (select jsonb_build_object('id', c.id, 'title', c.title, 'day', c.day, 'sportEventId', c.sport_event_id,
      'canDelete', c.created_by = auth.uid() or app.has_permission('checkin.manage'),
      'students', coalesce((select jsonb_agg(jsonb_build_object(
          'id', p.id, 'name', trim(p.first_name || ' ' || p.last_name), 'grade', p.grade,
          'releasedTo', case when r.student_id is not null then app.checkin_name(r.released_to) end,
          'releasedAt', r.at, 'releasedBy', case when r.student_id is not null then app.checkin_name(r.released_by) end)
          order by (r.student_id is not null), p.last_name, p.first_name)
        from checkout_list_students s join profiles p on p.id = s.student_id
        left join checkout_releases r on r.list_id = s.list_id and r.student_id = s.student_id
        where s.list_id = c.id), '[]'::jsonb))
    from checkout_lists c where c.id = p_id);
end $$;

/** Who a child may go home with today, for the release sheet: their pickup list (the office, or a list the caller runs with the child on it). */
create function public.checkout_people(p_student uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not (app.has_permission('checkin.manage') or exists (
      select 1 from checkout_list_students s where s.student_id = p_student and app.manages_checkout(s.list_id))) then
    raise exception 'Only the office, or someone checking this student out, can see who may take them.' using errcode = '42501';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', x.person_id, 'name', app.checkin_name(x.person_id), 'relation', x.relation)
      order by x.rank, app.checkin_name(x.person_id))
    from (select distinct on (person_id) person_id, relation,
            case when relation in ('mother', 'father', 'parent') then 0 when relation = 'family' then 1 else 2 end as rank
          from app.pickup_people(p_student) order by person_id, case when relation in ('mother', 'father', 'parent') then 0 else 1 end) x), '[]'::jsonb);
end $$;

/** The caller's Activities events from today through the next two weeks (the ones they coach or direct), with any list already made. */
create function public.checkout_event_options() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'title', sp.name || ': ' || e.title, 'startsAt', e.starts_at,
      'listId', (select c.id from checkout_lists c where c.sport_event_id = e.id)) order by e.starts_at), '[]'::jsonb)
  from sport_events e join sport_seasons ss on ss.id = e.season_id join sports sp on sp.id = ss.sport_id
  where app.is_staff() and not e.cancelled and app.can_manage_sport(ss.sport_id)
    and (e.starts_at at time zone 'America/Chicago')::date between app.school_today() and app.school_today() + 14
$$;

/** Students in the sections the caller leads (children without a login too), for a teacher's list. */
create function public.checkout_my_students() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'grade', x.grade, 'sections', x.sections) order by x.last, x.first), '[]'::jsonb)
  from (select p.id, trim(p.first_name || ' ' || p.last_name) as name, p.grade, p.first_name as first, p.last_name as last,
          string_agg(distinct r.name, ', ') as sections
        from rosters r join roster_members m on m.roster_id = r.id join profiles p on p.id = m.profile_id
        where r.kind = 'section' and r.lead_id = auth.uid() and app.is_staff() and p.school_role = 'student'
        group by p.id, p.first_name, p.last_name, p.grade) x
$$;

revoke all on function app.pickup_people(uuid), app.notify_parents(uuid, text, text, jsonb) from public, anon, authenticated;
grant execute on function app.checkin_name(uuid), app.checkin_time(timestamptz), app.checkin_reason(text),
  app.manages_checkout(uuid, uuid) to authenticated, service_role;
revoke all on function public.school_check(uuid, text, uuid, text, text), public.school_check_undo(uuid), public.checkin_students(text),
  public.checkin_today(), public.checkout_list_save(text, date, uuid[]), public.checkout_list_for_event(uuid), public.checkout_list_delete(uuid),
  public.checkout_release(uuid, uuid, uuid), public.checkout_unrelease(uuid, uuid), public.checkout_my_lists(), public.checkout_list(uuid),
  public.checkout_people(uuid), public.checkout_event_options(), public.checkout_my_students() from public, anon;
grant execute on function public.school_check(uuid, text, uuid, text, text), public.school_check_undo(uuid), public.checkin_students(text),
  public.checkin_today(), public.checkout_list_save(text, date, uuid[]), public.checkout_list_for_event(uuid), public.checkout_list_delete(uuid),
  public.checkout_release(uuid, uuid, uuid), public.checkout_unrelease(uuid, uuid), public.checkout_my_lists(), public.checkout_list(uuid),
  public.checkout_people(uuid), public.checkout_event_options(), public.checkout_my_students() to authenticated, service_role;
grant select on public.school_checks, public.checkout_lists, public.checkout_list_students, public.checkout_releases to authenticated;
grant all on public.school_checks, public.checkout_lists, public.checkout_list_students, public.checkout_releases to service_role;

insert into app.applied_migrations (name) values ('20261030000045_checkin_checkout.sql') on conflict do nothing;

-- ===== 20261030000046_volunteer_events.sql =====
-- Volunteer events: opportunities grouped under an event. Harvest Fest is one card in the Volunteer app;
-- inside it are its opportunities, like bringing bottled water or setting up the day of.
--
-- Any Volunteer Leader starts an event and adds opportunities to any open one; the leader who started
-- an event changes or removes it (removing keeps its opportunities, on their own). An opportunity's
-- leader can also move it into or out of an event. Everyone who can volunteer sees open events.
-- The event's leader puts its opportunities in order, most important first (position); ones without
-- a position (added since) follow, by date.

create table public.volunteer_events (
  id          uuid primary key default gen_random_uuid(),
  lead_id     uuid not null references public.profiles (id) on delete cascade,
  title       text not null check (char_length(trim(title)) between 1 and 100),
  description text not null default '' check (char_length(description) <= 2000),
  starts_on   date not null,
  ends_on     date,
  location    text check (char_length(location) <= 120),
  status      text not null default 'open' check (status in ('open', 'deleted')),
  created_at  timestamptz not null default now(),
  check (ends_on is null or ends_on >= starts_on)
);
create index on public.volunteer_events (starts_on);

alter table public.volunteer_opportunities add column event_id uuid references public.volunteer_events (id) on delete set null;
alter table public.volunteer_opportunities add column position int;
create index on public.volunteer_opportunities (event_id);

alter table public.volunteer_events enable row level security;
create policy "open events, for everyone who can volunteer" on public.volunteer_events for select to authenticated
  using (app.can_volunteer() and status = 'open' or app.has_permission('groups.manage'));

/** Volunteer Leaders: start an event (p_id null) or change one you started. */
create function public.volunteer_event_save(p_id uuid, p_title text, p_description text, p_starts_on date,
                                            p_ends_on date default null, p_location text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare new_id uuid;
begin
  if not app.is_volunteer_lead() then raise exception 'Only Volunteer Leaders can start events.' using errcode = '42501'; end if;
  if coalesce(trim(p_title), '') = '' then raise exception 'Give the event a name, like "Harvest Fest".'; end if;
  if p_starts_on is null then raise exception 'Choose the day of the event.'; end if;
  if p_ends_on is not null and p_ends_on < p_starts_on then raise exception 'The event has to end on or after the day it starts.'; end if;
  if p_id is null then
    insert into volunteer_events (lead_id, title, description, starts_on, ends_on, location)
    values (auth.uid(), trim(p_title), coalesce(trim(p_description), ''), p_starts_on, p_ends_on, nullif(trim(p_location), ''))
    returning id into new_id;
    return new_id;
  end if;
  update volunteer_events set title = trim(p_title), description = coalesce(trim(p_description), ''), starts_on = p_starts_on,
    ends_on = p_ends_on, location = nullif(trim(p_location), '')
  where id = p_id and lead_id = auth.uid() and status = 'open';
  if not found then raise exception 'You can only change events you started.' using errcode = '42501'; end if;
  return p_id;
end $$;

/** The event's leader (or groups.manage): remove it. Its opportunities stay, on their own. */
create function public.volunteer_event_delete(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  update volunteer_events set status = 'deleted'
  where id = p_id and status = 'open' and (lead_id = auth.uid() or app.has_permission('groups.manage'));
  if not found then raise exception 'You can only remove events you started.' using errcode = '42501'; end if;
  update volunteer_opportunities set event_id = null, position = null where event_id = p_id;
end $$;

/** An opportunity's leader: put it under an open event, or (null) on its own. */
create function public.volunteer_set_event(p_opportunity uuid, p_event uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_event is not null and not exists (select 1 from volunteer_events where id = p_event and status = 'open') then
    raise exception 'That event isn''t open anymore.';
  end if;
  update volunteer_opportunities set event_id = p_event, position = null
  where id = p_opportunity and lead_id = auth.uid() and status = 'open';
  if not found then raise exception 'You can only move opportunities you lead.' using errcode = '42501'; end if;
end $$;

/** The event's leader (or groups.manage): its opportunities in this order, most important first. Ones left out follow, by date. */
create function public.volunteer_event_reorder(p_event uuid, p_order uuid[]) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from volunteer_events where id = p_event and status = 'open'
                 and (lead_id = auth.uid() or app.has_permission('groups.manage'))) then
    raise exception 'Only the event''s leader can change the order.' using errcode = '42501';
  end if;
  update volunteer_opportunities set position = array_position(p_order, id) where event_id = p_event;
end $$;

-- Posting an opportunity can put it under an event (p_event, last so older calls still work).
drop function public.volunteer_post(text, text, date, date, time, time, text, int, text, text, int);
create function public.volunteer_post(
  p_title text, p_description text, p_starts_on date, p_ends_on date default null,
  p_start_time time default null, p_end_time time default null, p_location text default null, p_spots int default null,
  p_kind text default 'help', p_item text default null, p_quantity int default null, p_event uuid default null
) returns public.volunteer_opportunities
language plpgsql security definer set search_path = public as $$
declare r volunteer_opportunities%rowtype; items boolean := coalesce(p_kind, 'help') = 'items';
begin
  if not app.is_volunteer_lead() then
    raise exception 'Only Volunteer Leaders can post opportunities.' using errcode = '42501';
  end if;
  if items and nullif(trim(p_item), '') is null then raise exception 'Say what you need, like "boxes of tissues".'; end if;
  if items and coalesce(p_quantity, 0) < 1 then raise exception 'Say how many you need.'; end if;
  if p_event is not null and not exists (select 1 from volunteer_events where id = p_event and status = 'open') then
    raise exception 'That event isn''t open anymore.';
  end if;
  insert into volunteer_opportunities (lead_id, title, description, starts_on, ends_on, start_time, end_time, location, spots,
                                       kind, item, quantity, event_id)
  values (auth.uid(), trim(p_title), coalesce(trim(p_description), ''), p_starts_on, p_ends_on, p_start_time, p_end_time,
          nullif(trim(p_location), ''), case when items then null else p_spots end,
          case when items then 'items' else 'help' end, case when items then trim(p_item) end, case when items then p_quantity end, p_event)
  returning * into r;
  return r;
end $$;

revoke all on function public.volunteer_event_save(uuid, text, text, date, date, text), public.volunteer_event_delete(uuid),
  public.volunteer_set_event(uuid, uuid), public.volunteer_event_reorder(uuid, uuid[]), public.volunteer_post(text, text, date, date, time, time, text, int, text, text, int, uuid)
  from public, anon;
grant execute on function public.volunteer_event_save(uuid, text, text, date, date, text), public.volunteer_event_delete(uuid),
  public.volunteer_set_event(uuid, uuid), public.volunteer_event_reorder(uuid, uuid[]), public.volunteer_post(text, text, date, date, time, time, text, int, text, text, int, uuid)
  to authenticated, service_role;
grant select on public.volunteer_events to authenticated;
grant all on public.volunteer_events to service_role;

insert into app.applied_migrations (name) values ('20261030000046_volunteer_events.sql') on conflict do nothing;

-- ===== 20261030000047_class_attendance.sql =====
-- Class attendance: teachers take roll for the class sections they lead, and see the office's late
-- arrivals and early check-outs (school_checks) on the same roster.
--
-- A section's lead teacher marks each student present, late or absent for a day (today, or up to
-- two weeks back to fix a mistake). checkin.manage holders (the office) can take any section's roll,
-- for a teacher who's out, and see every section's (attendance_overview). A student the office
-- checks in late counts as late whatever the teacher marked, and shows as gone once the office
-- checks them out. The teachers of a student's sections are notified of each office check-in and
-- check-out. Parents and the student can read their own marks; nobody else.

create table public.class_attendance (
  section_id text not null references public.rosters (id) on delete cascade,
  student_id uuid not null references public.profiles (id) on delete cascade,
  day        date not null default app.school_today(),
  status     text not null check (status in ('present', 'late', 'absent')),
  marked_by  uuid references public.profiles (id) on delete set null,
  at         timestamptz not null default now(),
  primary key (section_id, day, student_id)
);
create index on public.class_attendance (student_id, day);

/** Who takes a section's roll: its lead teacher, and checkin.manage holders (the office). Staff only. */
create function app.takes_roll(sec text, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.is_staff(u) and exists (select 1 from rosters r where r.id = sec and r.kind = 'section'
    and (r.lead_id = u or app.has_permission('checkin.manage', u)))
$$;

alter table public.class_attendance enable row level security;
create policy "the class's teacher, the office, and the child's parents and the child" on public.class_attendance for select to authenticated
  using (app.takes_roll(section_id) or app.is_guardian_of(student_id) or student_id = auth.uid());

/** The office checked them in late that day (their first check of the day was a check-in). */
create function app.arrived_late(s uuid, d date) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select kind = 'in' from school_checks where student_id = s and day = d order by at limit 1), false)
$$;

/** The office checked them out and they haven't been checked back in. */
create function app.left_school(s uuid, d date) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select kind = 'out' from school_checks where student_id = s and day = d order by at desc limit 1), false)
$$;

/** Where a student stands in a section on a day: the teacher's mark, but late when the office checked them in late; null before roll. */
create function app.attendance_state(sec text, s uuid, d date) returns text
language sql stable security definer set search_path = public as $$
  select case when app.arrived_late(s, d) then 'late'
    else (select status from class_attendance where section_id = sec and student_id = s and day = d) end
$$;

/** A section's students (not its teacher), for the roll. */
create function app.section_students(sec text) returns setof uuid
language sql stable security definer set search_path = public as $$
  select m.profile_id from roster_members m join profiles p on p.id = m.profile_id where m.roster_id = sec and p.school_role = 'student'
$$;

/** A section's roll at a glance: how many are present, late, absent, not marked yet and gone home, and when roll was first taken. */
create function app.attendance_counts(sec text, d date) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('students', count(*),
    'present', count(*) filter (where x.state = 'present'), 'late', count(*) filter (where x.state = 'late'),
    'absent', count(*) filter (where x.state = 'absent'), 'unmarked', count(*) filter (where x.state is null),
    'left', count(*) filter (where x.gone),
    'takenAt', (select min(at) from class_attendance where section_id = sec and day = d))
  from (select app.attendance_state(sec, s, d) as state, app.left_school(s, d) as gone from app.section_students(sec) s) x
$$;

/** The section's teacher or the office: mark students present, late or absent (null clears), today or up to two weeks back. */
create function public.class_attendance_mark(p_section text, p_day date, p_students uuid[], p_status text) returns void
language plpgsql security definer set search_path = public as $$
declare d date := coalesce(p_day, app.school_today()); s uuid;
begin
  if not app.takes_roll(p_section) then
    raise exception 'Only the class''s teacher and the office can take its roll.' using errcode = '42501';
  end if;
  if d > app.school_today() then raise exception 'Roll can''t be taken ahead of the day.'; end if;
  if d < app.school_today() - 14 then raise exception 'Roll can only be changed for the last two weeks.'; end if;
  if p_status is not null and p_status not in ('present', 'late', 'absent') then raise exception 'Choose present, late or absent.'; end if;
  foreach s in array coalesce(p_students, '{}') loop
    if s not in (select app.section_students(p_section)) then raise exception '% isn''t in this class.', app.checkin_name(s); end if;
  end loop;
  if p_status is null then
    delete from class_attendance where section_id = p_section and day = d and student_id = any (p_students);
  else
    insert into class_attendance (section_id, student_id, day, status, marked_by)
    select p_section, x, d, p_status, auth.uid() from (select distinct unnest(p_students) x) q
    on conflict (section_id, day, student_id) do update set status = excluded.status, marked_by = excluded.marked_by, at = now();
  end if;
end $$;

/** A section's roll for a day: each student with the teacher's mark, where they stand, and the office's check-ins and check-outs. */
create function public.class_attendance_roll(p_section text, p_day date default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare d date := coalesce(p_day, app.school_today());
begin
  if not app.takes_roll(p_section) then
    raise exception 'Only the class''s teacher and the office can see its attendance.' using errcode = '42501';
  end if;
  return (select jsonb_build_object('id', r.id, 'name', r.name, 'teacher', case when r.lead_id is not null then app.checkin_name(r.lead_id) end,
      'day', d, 'canMark', d between app.school_today() - 14 and app.school_today(),
      'students', coalesce((select jsonb_agg(jsonb_build_object(
          'id', p.id, 'name', trim(p.first_name || ' ' || p.last_name), 'grade', p.grade,
          'mark', a.status, 'markedBy', case when a.marked_by is not null then app.checkin_name(a.marked_by) end,
          'state', app.attendance_state(r.id, p.id, d), 'left', app.left_school(p.id, d),
          'checks', coalesce((select jsonb_agg(jsonb_build_object('kind', c.kind, 'at', c.at, 'reason', c.reason,
              'person', case when c.person_id is not null then app.checkin_name(c.person_id) end) order by c.at)
            from school_checks c where c.student_id = p.id and c.day = d), '[]'::jsonb))
          order by p.last_name, p.first_name)
        from app.section_students(r.id) s join profiles p on p.id = s
        left join class_attendance a on a.section_id = r.id and a.student_id = p.id and a.day = d), '[]'::jsonb))
    from rosters r where r.id = p_section);
end $$;

/** The sections the caller leads, each with its roll at a glance for the day. */
create function public.my_class_attendance(p_day date default null) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name, 'teacher', app.checkin_name(r.lead_id))
      || app.attendance_counts(r.id, coalesce(p_day, app.school_today())) order by r.name), '[]'::jsonb)
  from rosters r where r.kind = 'section' and r.lead_id = auth.uid() and app.is_staff()
$$;

/** checkin.manage (the office): every section's roll at a glance for the day. */
create function public.attendance_overview(p_day date default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform app.require_permission('checkin.manage');
  return coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name,
        'teacher', case when r.lead_id is not null then app.checkin_name(r.lead_id) end)
      || app.attendance_counts(r.id, coalesce(p_day, app.school_today())) order by r.name)
    from rosters r where r.kind = 'section'), '[]'::jsonb);
end $$;

/** The office checked a student in or out: tell the teachers of their sections (once each; not whoever recorded it). */
create function app.tell_teachers_of_check() returns trigger
language plpgsql security definer set search_path = public as $$
declare t record; kid text := app.checkin_name(new.student_id);
begin
  for t in select r.lead_id, min(r.id) as sec from rosters r join roster_members m on m.roster_id = r.id
           where r.kind = 'section' and m.profile_id = new.student_id and r.lead_id is not null
             and r.lead_id is distinct from new.recorded_by and app.is_staff(r.lead_id)
           group by r.lead_id loop
    perform app.notify_user(t.lead_id,
      case new.kind when 'in' then '🕘 ' || kid || ' arrived late' else '👋 ' || kid || ' left early' end,
      concat_ws(' · ', app.checkin_time(new.at),
                case when new.kind = 'out' and new.person_id is not null then 'with ' || app.checkin_name(new.person_id) end,
                app.checkin_reason(new.reason)),
      jsonb_build_object('classAttendance', t.sec));
  end loop;
  return null;
end $$;
create trigger tell_teachers after insert on public.school_checks for each row execute function app.tell_teachers_of_check();

revoke all on function app.arrived_late(uuid, date), app.left_school(uuid, date), app.attendance_state(text, uuid, date),
  app.section_students(text), app.attendance_counts(text, date), app.tell_teachers_of_check() from public, anon, authenticated;
grant execute on function app.takes_roll(text, uuid) to authenticated, service_role;
revoke all on function public.class_attendance_mark(text, date, uuid[], text), public.class_attendance_roll(text, date),
  public.my_class_attendance(date), public.attendance_overview(date) from public, anon;
grant execute on function public.class_attendance_mark(text, date, uuid[], text), public.class_attendance_roll(text, date),
  public.my_class_attendance(date), public.attendance_overview(date) to authenticated, service_role;
grant select on public.class_attendance to authenticated;
grant all on public.class_attendance to service_role;

insert into app.applied_migrations (name) values ('20261030000047_class_attendance.sql') on conflict do nothing;

-- ===== 20261030000048_substitutes.sql =====
-- Substitutes: a school role for people who cover a teacher's classes while the teacher is away.
--
-- A Substitute account is closed by default: no groups, rosters, photo gallery, Ask the School,
-- children, Marketplace or Volunteer (those either list the roles they're for or are closed below),
-- and never any admin powers. Everything else comes from the sub schedule (sub_assignments): a
-- teacher schedules a sub for the class sections they lead, and subs.manage holders (the office,
-- administrators and directors; an admin power) for any section, with the days, the hours and the
-- teacher's sub plans. Only while a duty window is running (app.duty_now: between its first and last
-- day, between its hours on the school's clock) does the sub take that class's roll (today's only),
-- see the office's check-ins and get their notifications, read the sub plans, run field trip check-out
-- lists from its students (today's), see the car line board, and get and answer critical alerts.
-- Outside it they see which classes they're due to cover and when, nothing more. A teacher or staff
-- member can also be scheduled to cover a class; they get the same class tools for its duty window.

alter table public.profiles drop constraint if exists profiles_school_role_check;
alter table public.profiles add constraint profiles_school_role_check
  check (school_role in ('admin', 'teacher', 'staff', 'parent', 'student', 'family', 'substitute'));

create function app.is_substitute(u uuid default auth.uid()) returns boolean
language sql stable as $$ select coalesce(app.school_role(u) = 'substitute', false) $$;

/** Substitutes hold no admin powers: becoming one drops them, and granting them is refused. */
create function app.substitute_profile() returns trigger
language plpgsql as $$
begin
  if new.school_role = 'substitute' then
    if tg_op = 'UPDATE' and old.school_role is distinct from 'substitute' then
      new.admin_tier := null;
      new.permissions := '{}';
    elsif new.admin_tier is not null or cardinality(coalesce(new.permissions, '{}')) > 0 then
      raise exception 'Substitutes can''t have admin powers.' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;
create trigger substitute_profile before insert or update of school_role, admin_tier, permissions on public.profiles
  for each row execute function app.substitute_profile();

/** Becoming a Substitute leaves every group. */
create function app.substitute_leaves_groups() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  delete from memberships where user_id = new.id;
  return null;
end $$;
create trigger substitute_leaves_groups after update of school_role on public.profiles
  for each row when (new.school_role = 'substitute' and old.school_role is distinct from 'substitute')
  execute function app.substitute_leaves_groups();

-- ----------------------------------------------------------------------
-- Closed by default: groups, rosters, the photo gallery, Ask the School, children
-- ----------------------------------------------------------------------

create or replace function app.effective_role(g uuid, u uuid default auth.uid()) returns text
language plpgsql stable security definer set search_path = public as $$
declare sr text; r text; vis text;
begin
  sr := app.school_role(u);
  if sr is null or sr in ('family', 'substitute') then return null; end if;  -- signed out, awaiting approval, Family or Substitute
  if app.has_permission('groups.manage', u) then return 'owner'; end if;
  select role into r from memberships where group_id = g and user_id = u;
  if r is not null then return r; end if;
  select settings->>'visibility' into vis from groups where id = g;
  if vis in ('public', 'school') then return 'subscriber'; end if;
  return null;
end $$;

drop policy "discoverable groups" on public.groups;
create policy "discoverable groups" on public.groups for select to authenticated
  using (app.is_admin()
         or (app.school_role() is not null and not app.is_family() and not app.is_substitute() and settings->>'visibility' <> 'hidden')
         or app.is_member(id));

drop policy "approved users" on public.rosters;
create policy "approved users" on public.rosters for select to authenticated
  using (app.school_role() is not null and not app.is_family() and not app.is_substitute());

create or replace function app.rule_targets(g uuid) returns table (user_id uuid, role text, rule_id uuid)
language sql stable security definer set search_path = public as $$
  with matched as (
    select r.id as rule_id, p.id as user_id, r.assign_as as role
    from assignment_rules r
    join profiles p on p.school_role is not null and p.school_role not in ('family', 'substitute')
    where r.group_id = g
      and (r.school_roles is null or p.school_role = any (r.school_roles))
      and (r.grades is null or p.grade = any (r.grades))
      and (r.roster_ids is null or exists (
            select 1 from roster_members rm where rm.profile_id = p.id and rm.roster_id = any (r.roster_ids)))
  ), everyone as (
    select rule_id, user_id, role from matched
    union all
    select m.rule_id, gd.guardian_id, r.include_guardians_as
    from matched m
    join assignment_rules r on r.id = m.rule_id and r.include_guardians_as is not null
    join guardians gd on gd.student_id = m.user_id
  )
  select distinct on (user_id) user_id, role, rule_id
  from everyone order by user_id, app.role_rank(role), rule_id
$$;

/** Whatever path adds a member (joining, an invite, an admin, a rule), Family and Substitute accounts are refused. */
create or replace function app.no_family_in_groups() returns trigger
language plpgsql as $$
begin
  if app.is_family(new.user_id) then raise exception 'Groups aren''t part of Family accounts.' using errcode = '42501'; end if;
  if app.is_substitute(new.user_id) then raise exception 'Groups aren''t part of Substitute accounts.' using errcode = '42501'; end if;
  return new;
end $$;

create or replace function public.ask_school(p_topic text, p_subject text, p_body text) returns public.school_questions
language plpgsql security definer set search_path = public as $$
declare q school_questions%rowtype; r uuid;
begin
  if app.school_role() is null then raise exception 'Sign in with an approved account to ask the school.' using errcode = '42501'; end if;
  if app.is_family() then raise exception 'Ask the School isn''t part of Family accounts.' using errcode = '42501'; end if;
  if app.is_substitute() then raise exception 'Ask the School isn''t part of Substitute accounts.' using errcode = '42501'; end if;
  insert into school_questions (asker_id, topic, subject) values (auth.uid(), coalesce(p_topic, 'Other'), trim(p_subject)) returning * into q;
  insert into school_question_messages (question_id, author_id, from_school, body) values (q.id, auth.uid(), false, trim(p_body));
  for r in select app.question_routers() loop
    perform app.question_note(r, '❓ New question: ' || q.subject, app.short_name(auth.uid()) || ' · ' || q.topic, q.id);
  end loop;
  return q;
end $$;

create or replace function public.request_child(p_first text, p_last text, p_grade int, p_birthday date default null, p_note text default null,
                                                p_relation text default null)
returns public.family_requests
language plpgsql security definer set search_path = public as $$
declare row family_requests%rowtype; mine text;
begin
  if coalesce(app.school_role(), 'student') in ('student', 'family', 'substitute') then
    raise exception 'Only approved parents and staff can add children.' using errcode = '42501';
  end if;
  perform app.check_child_fields(p_first, p_last, p_grade);
  if p_relation is null or p_relation not in ('mother', 'father') then raise exception 'Say whether you''re the mother or the father.'; end if;
  -- Already yours?
  select trim(p.first_name) into mine from guardians g join profiles p on p.id = g.student_id left join student_details d on d.student_id = p.id
  where g.guardian_id = auth.uid()
    and app.child_match_score(p.first_name, p.last_name, d.birthday, p.grade, p_first, p_last, p_birthday, p_grade) >= 6
  limit 1;
  if mine is not null then raise exception '% is already linked to your account.', mine; end if;
  -- Already asked?
  if exists (select 1 from family_requests where requested_by = auth.uid() and kind = 'add_child' and status = 'pending'
             and app.norm_name(details->>'firstName') = app.norm_name(p_first) and app.norm_name(details->>'lastName') = app.norm_name(p_last)) then
    raise exception 'You already asked to add %. The office will get back to you.', trim(p_first);
  end if;
  insert into family_requests (requested_by, kind, details)
  values (auth.uid(), 'add_child', jsonb_build_object('firstName', trim(p_first), 'lastName', trim(p_last), 'grade', p_grade,
                                                     'birthday', p_birthday, 'note', nullif(trim(p_note), ''), 'relation', p_relation))
  returning * into row;
  return row;
end $$;

/** Can this person see this album? Everyone approved (not Substitutes) for "everyone" albums; staff for all. */
create or replace function app.sees_album(a uuid, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.school_role(u) is not null and not app.is_substitute(u)
     and exists (select 1 from gallery_albums where id = a and (visibility = 'everyone' or app.is_staff(u)))
$$;

drop policy "approved accounts see the categories" on public.gallery_categories;
create policy "approved accounts see the categories" on public.gallery_categories for select to authenticated
  using (app.school_role() is not null and not app.is_substitute());
drop policy "everyone approved, or staff for staff-only albums" on public.gallery_albums;
create policy "everyone approved, or staff for staff-only albums" on public.gallery_albums for select to authenticated
  using (app.school_role() is not null and not app.is_substitute() and (visibility = 'everyone' or app.is_staff()));
drop policy "gallery: photos of albums you can see" on storage.objects;
create policy "gallery: photos of albums you can see" on storage.objects for select to authenticated
  using (bucket_id = 'gallery' and app.school_role() is not null and not app.is_substitute() and (app.is_staff() or exists (
    select 1 from public.gallery_photos p
    where p.path = regexp_replace(objects.name, '_t\.jpg$', '.jpg') and app.sees_album(p.album_id))));

-- ----------------------------------------------------------------------
-- The sub schedule
-- ----------------------------------------------------------------------

create or replace function public.permission_catalog() returns table (key text, label text, description text)
language sql immutable as $$
  values
    ('admins.manage',    'Manage admins',         'Make or remove admins, set tiers and grant permissions (director only).'),
    ('people.view',      'View people',           'See everyone''s contact email in the admin portal.'),
    ('people.approve',   'Approve sign-ups',      'Approve new accounts as parents, students or family.'),
    ('people.roles',     'Change roles',          'Set anyone''s school role, including teachers, staff and substitutes.'),
    ('people.family',    'Families & rosters',    'Link parents and family to students, set grades, manage classes, class/team rosters and car line duty.'),
    ('groups.manage',    'Manage all groups',     'Act as owner of every group: settings, members, moderation.'),
    ('calendar.school',  'School calendar',       'Add, change and remove school-wide calendar events.'),
    ('push.send',        'Send notifications',    'Send push notifications to everyone, a role or any group.'),
    ('checkin.manage',   'Check in & out',        'Check students in when they arrive late and out when they leave early (only to someone on their pickup list), see the day''s check-ins, and run any event check-out list.'),
    ('subs.manage',      'Schedule substitutes',  'Schedule a substitute for any class, with the days, hours and sub plans, and change or cancel any sub day.'),
    ('alerts.map',       'Alert map',             'Keep the map of the school''s Wi-Fi access points (which room or area each one is in) that shows critical alert senders where people answered from.'),
    ('alerts.send',      'Send critical alerts',  'Send critical alerts (severe weather, an active threat, a dangerous situation) to every teacher and staff member, see who''s safe, and give the all clear.'),
    ('questions.manage', 'Route questions',       'See every question sent to the school, assign it to faculty or staff, and answer it.'),
    ('messages.review',  'Student messages',      'Read every Ask the Teacher conversation between students and teachers, for safety.'),
    ('sports.manage',    'Manage activities',     'Add activities (sports, theater, music, art, clubs) and seasons, set schedules, assign coaches and directors, and approve sign-ups.'),
    ('forms.send',       'Send forms',            'Send forms (permission slips, releases, acknowledgments) to any class, activity, grade or the whole school, and see every form''s signatures.'),
    ('people.delete',    'Delete accounts',       'Permanently delete someone''s account, with their posts and comments. Deleting an admin also needs Manage admins.'),
    ('gallery.manage',   'Manage photo gallery',  'Change or remove any photo album or photo, not just your own.'),
    ('feedback.triage',  'Triage feedback',       'See every bug report and feature request sent from the app, set its status and priority, reply, and plan student workshops from them.'),
    ('audit.view',       'Activity log',          'Review the school-wide activity log.')
$$;

update public.admin_roles set permissions = permissions || 'subs.manage'::text
where id in ('director', 'administrator', 'office') and not ('subs.manage' = any (permissions));

create table public.sub_assignments (
  id            uuid primary key default gen_random_uuid(),
  substitute_id uuid not null references public.profiles (id) on delete cascade,
  starts_on     date not null,
  ends_on       date not null,
  start_time    time not null,
  end_time      time not null,
  plans         text not null default '' check (char_length(plans) <= 4000),
  created_by    uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  check (ends_on >= starts_on),
  check (end_time > start_time)
);
create index on public.sub_assignments (substitute_id, ends_on);

create table public.sub_assignment_sections (
  assignment_id uuid not null references public.sub_assignments (id) on delete cascade,
  section_id    text not null references public.rosters (id) on delete cascade,
  primary key (assignment_id, section_id)
);
create index on public.sub_assignment_sections (section_id);

/** Is a duty window running: between its first and last day, between its hours, on the school's clock (Central time). */
create function app.duty_now(d1 date, d2 date, t1 time, t2 time, p_at timestamptz default now()) returns boolean
language sql stable as $$
  select (p_at at time zone 'America/Chicago')::date between d1 and d2
     and (p_at at time zone 'America/Chicago')::time >= t1 and (p_at at time zone 'America/Chicago')::time < t2
$$;

/** Is this person covering this class section right now? Substitutes, teachers and staff only. */
create function app.on_duty_for(sec text, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(app.school_role(u) in ('substitute', 'teacher', 'staff', 'admin'), false) and exists (
    select 1 from sub_assignments a join sub_assignment_sections s on s.assignment_id = a.id
    where a.substitute_id = u and s.section_id = sec and app.duty_now(a.starts_on, a.ends_on, a.start_time, a.end_time))
$$;

/** Is this person covering any class right now? */
create function app.on_duty(u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(app.school_role(u) in ('substitute', 'teacher', 'staff', 'admin'), false) and exists (
    select 1 from sub_assignments a join sub_assignment_sections s on s.assignment_id = a.id
    where a.substitute_id = u and app.duty_now(a.starts_on, a.ends_on, a.start_time, a.end_time))
$$;

/** May this person schedule a sub for this section: its lead teacher, or subs.manage. */
create function app.schedules_for(sec text, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from rosters r where r.id = sec and r.kind = 'section'
    and ((r.lead_id = u and app.is_staff(u)) or app.has_permission('subs.manage', u)))
$$;

/** Who sees and changes a sub day: whoever scheduled it (staff), the teacher of one of its classes, and subs.manage. Not the sub. */
create function app.manages_sub(a uuid, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from sub_assignments x where x.id = a and (
    app.has_permission('subs.manage', u)
    or (app.is_staff(u) and (x.created_by = u or exists (
      select 1 from sub_assignment_sections s join rosters r on r.id = s.section_id where s.assignment_id = x.id and r.lead_id = u)))))
$$;

alter table public.sub_assignments enable row level security;
alter table public.sub_assignment_sections enable row level security;
create policy "whoever scheduled it, the class's teacher, and the office" on public.sub_assignments for select to authenticated
  using (app.manages_sub(id));
create policy "whoever scheduled it, the class's teacher, and the office" on public.sub_assignment_sections for select to authenticated
  using (app.manages_sub(assignment_id));

/** "Mon, Nov 2 · 7:30 AM–3:30 PM", or "Nov 2–4 · 7:30 AM–3:30 PM". */
create function app.sub_when(d1 date, d2 date, t1 time, t2 time) returns text
language sql stable as $$
  select case when d1 = d2 then to_char(d1, 'Dy, Mon FMDD') else to_char(d1, 'Mon FMDD') || '–' || to_char(d2, 'Mon FMDD') end
    || ' · ' || to_char(d1 + t1, 'FMHH12:MI AM') || '–' || to_char(d1 + t2, 'FMHH12:MI AM')
$$;

/** "English 10 – Period 3, Math 7". */
create function app.sub_classes(a uuid) returns text
language sql stable security definer set search_path = public as $$
  select coalesce(string_agg(r.name, ', ' order by r.name), 'a class')
  from sub_assignment_sections s join rosters r on r.id = s.section_id where s.assignment_id = a
$$;

/** A sub day as the app shows it; the sub plans only when `with_plans`. */
create function app.sub_json(a uuid, with_plans boolean) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', x.id, 'substituteId', x.substitute_id, 'substitute', app.checkin_name(x.substitute_id),
      'startsOn', x.starts_on, 'endsOn', x.ends_on, 'startTime', left(x.start_time::text, 5), 'endTime', left(x.end_time::text, 5),
      'onDuty', app.duty_now(x.starts_on, x.ends_on, x.start_time, x.end_time),
      'plans', case when with_plans then x.plans end,
      'scheduledBy', case when x.created_by is not null then app.checkin_name(x.created_by) end,
      'classes', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name,
          'teacher', case when r.lead_id is not null then app.checkin_name(r.lead_id) end) order by r.name)
        from sub_assignment_sections s join rosters r on r.id = s.section_id where s.assignment_id = x.id), '[]'::jsonb))
  from sub_assignments x where x.id = a
$$;

/**
 * A class's teacher (for the sections they lead) or subs.manage (any section): schedule a sub, or change a
 * sub day (p_id). The sub is told; so are the classes' teachers when someone else scheduled it.
 */
create function public.sub_schedule_save(p_id uuid, p_substitute uuid, p_sections text[], p_starts_on date, p_ends_on date,
  p_start_time time, p_end_time time, p_plans text default '') returns uuid
language plpgsql security definer set search_path = public as $$
declare a sub_assignments; new_id uuid; sec text; lead uuid; what text; at_when text;
begin
  if p_id is not null then
    select * into a from sub_assignments where id = p_id;
    if not found then raise exception 'That sub day is gone.'; end if;
    if not app.manages_sub(p_id) then
      raise exception 'Only the class''s teacher or the office can change this sub day.' using errcode = '42501';
    end if;
  end if;
  if coalesce(cardinality(p_sections), 0) = 0 then raise exception 'Choose the classes to cover.'; end if;
  foreach sec in array p_sections loop
    if not exists (select 1 from rosters where id = sec and kind = 'section') then raise exception 'Choose classes only.'; end if;
    if not app.schedules_for(sec) then perform app.require_permission('subs.manage'); end if;
  end loop;
  if p_substitute is null or coalesce(app.school_role(p_substitute), '') not in ('substitute', 'teacher', 'staff', 'admin') then
    raise exception 'Choose a substitute, or a teacher or staff member to cover.';
  end if;
  if exists (select 1 from rosters where id = any (p_sections) and lead_id = p_substitute) then
    raise exception '% already teaches one of these classes.', app.checkin_name(p_substitute);
  end if;
  if p_starts_on is null or p_ends_on is null then raise exception 'Choose the days.'; end if;
  if p_ends_on < p_starts_on then raise exception 'The last day can''t be before the first.'; end if;
  if p_ends_on < app.school_today() then raise exception 'Choose today or a day coming up.'; end if;
  if p_ends_on - p_starts_on > 60 then raise exception 'Schedule up to two months at a time.'; end if;
  if p_start_time is null or p_end_time is null or p_end_time <= p_start_time then raise exception 'The end time must be after the start time.'; end if;
  if char_length(coalesce(p_plans, '')) > 4000 then raise exception 'Keep the sub plans under 4,000 characters.'; end if;

  if p_id is null then
    insert into sub_assignments (substitute_id, starts_on, ends_on, start_time, end_time, plans, created_by)
    values (p_substitute, p_starts_on, p_ends_on, p_start_time, p_end_time, trim(coalesce(p_plans, '')), auth.uid())
    returning id into new_id;
  else
    new_id := p_id;
    update sub_assignments set substitute_id = p_substitute, starts_on = p_starts_on, ends_on = p_ends_on,
      start_time = p_start_time, end_time = p_end_time, plans = trim(coalesce(p_plans, '')) where id = p_id;
    delete from sub_assignment_sections where assignment_id = p_id;
  end if;
  insert into sub_assignment_sections (assignment_id, section_id) select new_id, x from (select distinct unnest(p_sections) x) q;

  what := app.sub_classes(new_id);
  at_when := app.sub_when(p_starts_on, p_ends_on, p_start_time, p_end_time);
  if p_id is not null and a.substitute_id <> p_substitute then
    perform app.notify_user(a.substitute_id, '📋 Sub day cancelled: ' || what,
      app.sub_when(a.starts_on, a.ends_on, a.start_time, a.end_time), jsonb_build_object('subDays', true));
  end if;
  perform app.notify_user(p_substitute,
    case when p_id is null or a.substitute_id <> p_substitute then '📋 You''re subbing: ' else '📋 Your sub day changed: ' end || what,
    at_when, jsonb_build_object('subDays', true));
  if p_id is null then
    for lead in select distinct r.lead_id from rosters r
                where r.id = any (p_sections) and r.lead_id is not null and r.lead_id <> auth.uid() loop
      perform app.notify_user(lead, '📋 Sub scheduled: ' || app.checkin_name(p_substitute), what || ' · ' || at_when,
        jsonb_build_object('subSchedule', true));
    end loop;
  end if;
  perform app.audit(null, case when p_id is null then 'sub.scheduled' else 'sub.changed' end, new_id::text,
    jsonb_build_object('substitute', p_substitute, 'sections', p_sections, 'from', p_starts_on, 'to', p_ends_on));
  return new_id;
end $$;

/** Cancel a sub day (whoever may change it); the sub is told if it hasn't ended. */
create function public.sub_schedule_delete(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare a sub_assignments;
begin
  select * into a from sub_assignments where id = p_id;
  if not found then raise exception 'That sub day is gone.'; end if;
  if not app.manages_sub(p_id) then
    raise exception 'Only the class''s teacher or the office can cancel this sub day.' using errcode = '42501';
  end if;
  if a.ends_on >= app.school_today() then
    perform app.notify_user(a.substitute_id, '📋 Sub day cancelled: ' || app.sub_classes(p_id),
      app.sub_when(a.starts_on, a.ends_on, a.start_time, a.end_time), jsonb_build_object('subDays', true));
  end if;
  delete from sub_assignments where id = p_id;
  perform app.audit(null, 'sub.cancelled', p_id::text, jsonb_build_object('substitute', a.substitute_id));
end $$;

/** The sub days the caller can see and change, from today on, with their sub plans. */
create function public.sub_schedule_list() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(app.sub_json(a.id, true) order by a.starts_on, a.start_time), '[]'::jsonb)
  from sub_assignments a where a.ends_on >= app.school_today() and app.manages_sub(a.id)
$$;

/** The caller's own sub days from today on: the classes and hours always, the sub plans only while on duty. */
create function public.my_sub_days() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(app.sub_json(a.id, app.duty_now(a.starts_on, a.ends_on, a.start_time, a.end_time))
      order by a.starts_on, a.start_time), '[]'::jsonb)
  from sub_assignments a where a.substitute_id = auth.uid() and a.ends_on >= app.school_today()
$$;

/** For the scheduling screen: the classes the caller can schedule for, and who can cover (substitutes first). */
create function public.sub_options() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not (app.is_staff() or app.has_permission('subs.manage')) then
    raise exception 'Scheduling substitutes is for teachers and the office.' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'classes', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name,
        'teacher', case when r.lead_id is not null then app.checkin_name(r.lead_id) end) order by r.name)
      from rosters r where r.kind = 'section' and app.schedules_for(r.id)), '[]'::jsonb),
    'people', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'name', trim(p.first_name || ' ' || p.last_name), 'role', p.school_role)
        order by p.school_role <> 'substitute', p.last_name, p.first_name)
      from profiles p where p.school_role in ('substitute', 'teacher', 'staff', 'admin') and not p.managed and p.id <> auth.uid()), '[]'::jsonb));
end $$;

-- ----------------------------------------------------------------------
-- Class tools while on duty: Attendance
-- ----------------------------------------------------------------------

/** Keeps a section's roll on any day: its lead teacher, and checkin.manage holders (the office). Staff only. */
create function app.keeps_roll(sec text, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.is_staff(u) and exists (select 1 from rosters r where r.id = sec and r.kind = 'section'
    and (r.lead_id = u or app.has_permission('checkin.manage', u)))
$$;

/** Takes a section's roll: whoever keeps it, and a sub covering the class right now. */
create or replace function app.takes_roll(sec text, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.keeps_roll(sec, u) or app.on_duty_for(sec, u)
$$;

create or replace function public.class_attendance_mark(p_section text, p_day date, p_students uuid[], p_status text) returns void
language plpgsql security definer set search_path = public as $$
declare d date := coalesce(p_day, app.school_today()); s uuid;
begin
  if not app.takes_roll(p_section) then
    raise exception 'Only the class''s teacher and the office can take its roll.' using errcode = '42501';
  end if;
  if d > app.school_today() then raise exception 'Roll can''t be taken ahead of the day.'; end if;
  if not app.keeps_roll(p_section) and d <> app.school_today() then raise exception 'Substitutes take today''s roll only.'; end if;
  if d < app.school_today() - 14 then raise exception 'Roll can only be changed for the last two weeks.'; end if;
  if p_status is not null and p_status not in ('present', 'late', 'absent') then raise exception 'Choose present, late or absent.'; end if;
  foreach s in array coalesce(p_students, '{}') loop
    if s not in (select app.section_students(p_section)) then raise exception '% isn''t in this class.', app.checkin_name(s); end if;
  end loop;
  if p_status is null then
    delete from class_attendance where section_id = p_section and day = d and student_id = any (p_students);
  else
    insert into class_attendance (section_id, student_id, day, status, marked_by)
    select p_section, x, d, p_status, auth.uid() from (select distinct unnest(p_students) x) q
    on conflict (section_id, day, student_id) do update set status = excluded.status, marked_by = excluded.marked_by, at = now();
  end if;
end $$;

create or replace function public.class_attendance_roll(p_section text, p_day date default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare d date := coalesce(p_day, app.school_today());
begin
  if not app.takes_roll(p_section) then
    raise exception 'Only the class''s teacher and the office can see its attendance.' using errcode = '42501';
  end if;
  if not app.keeps_roll(p_section) and d <> app.school_today() then raise exception 'Substitutes see today''s roll only.'; end if;
  return (select jsonb_build_object('id', r.id, 'name', r.name, 'teacher', case when r.lead_id is not null then app.checkin_name(r.lead_id) end,
      'day', d, 'canMark', d between app.school_today() - 14 and app.school_today(), 'otherDays', app.keeps_roll(r.id),
      'students', coalesce((select jsonb_agg(jsonb_build_object(
          'id', p.id, 'name', trim(p.first_name || ' ' || p.last_name), 'grade', p.grade,
          'mark', a.status, 'markedBy', case when a.marked_by is not null then app.checkin_name(a.marked_by) end,
          'state', app.attendance_state(r.id, p.id, d), 'left', app.left_school(p.id, d),
          'checks', coalesce((select jsonb_agg(jsonb_build_object('kind', c.kind, 'at', c.at, 'reason', c.reason,
              'person', case when c.person_id is not null then app.checkin_name(c.person_id) end) order by c.at)
            from school_checks c where c.student_id = p.id and c.day = d), '[]'::jsonb))
          order by p.last_name, p.first_name)
        from app.section_students(r.id) s join profiles p on p.id = s
        left join class_attendance a on a.section_id = r.id and a.student_id = p.id and a.day = d), '[]'::jsonb))
    from rosters r where r.id = p_section);
end $$;

-- A sub on duty reads the class's marks for today only.
drop policy "the class's teacher, the office, and the child's parents and the child" on public.class_attendance;
create policy "the class's teacher, the office, a sub on duty today, and the child's parents and the child" on public.class_attendance
  for select to authenticated
  using (app.keeps_roll(section_id) or (day = app.school_today() and app.on_duty_for(section_id))
         or app.is_guardian_of(student_id) or student_id = auth.uid());

/** The sections the caller leads, and the ones they're covering right now, each with its roll at a glance for the day. */
create or replace function public.my_class_attendance(p_day date default null) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name, 'teacher', app.checkin_name(r.lead_id))
      || app.attendance_counts(r.id, coalesce(p_day, app.school_today())) order by r.name), '[]'::jsonb)
  from rosters r where r.kind = 'section' and ((r.lead_id = auth.uid() and app.is_staff()) or app.on_duty_for(r.id))
$$;

/** The office checked a student in or out: tell their sections' teachers and anyone covering them now (once each; not whoever recorded it). */
create or replace function app.tell_teachers_of_check() returns trigger
language plpgsql security definer set search_path = public as $$
declare t record; kid text := app.checkin_name(new.student_id);
begin
  for t in select x.u, min(x.sec) as sec from (
             select r.lead_id as u, r.id as sec from rosters r join roster_members m on m.roster_id = r.id
             where r.kind = 'section' and m.profile_id = new.student_id and r.lead_id is not null and app.is_staff(r.lead_id)
             union all
             select a.substitute_id, s.section_id from sub_assignment_sections s
             join sub_assignments a on a.id = s.assignment_id
             join roster_members m on m.roster_id = s.section_id
             where m.profile_id = new.student_id and app.on_duty_for(s.section_id, a.substitute_id)) x
           where x.u is distinct from new.recorded_by
           group by x.u loop
    perform app.notify_user(t.u,
      case new.kind when 'in' then '🕘 ' || kid || ' arrived late' else '👋 ' || kid || ' left early' end,
      concat_ws(' · ', app.checkin_time(new.at),
                case when new.kind = 'out' and new.person_id is not null then 'with ' || app.checkin_name(new.person_id) end,
                app.checkin_reason(new.reason)),
      jsonb_build_object('classAttendance', t.sec));
  end loop;
  return null;
end $$;

-- ----------------------------------------------------------------------
-- Class tools while on duty: field trip check-out (today's lists, from the class's students)
-- ----------------------------------------------------------------------

/** Who runs a check-out list: staff as before; a sub runs the lists they made today while on duty. */
create or replace function app.manages_checkout(l uuid, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from checkout_lists c
    left join sport_events e on e.id = c.sport_event_id
    left join sport_seasons ss on ss.id = e.season_id
    where c.id = l and (
      (app.is_staff(u) and (c.created_by = u or app.has_permission('checkin.manage', u)
                            or (ss.sport_id is not null and app.can_manage_sport(ss.sport_id, u))))
      or (c.created_by = u and c.day = app.school_today() and app.on_duty(u))))
$$;

create or replace function public.checkout_list_save(p_title text, p_day date, p_students uuid[]) returns uuid
language plpgsql security definer set search_path = public as $$
declare new_id uuid; s uuid;
begin
  if not (app.is_staff() or app.on_duty()) then raise exception 'Check-out lists are for teachers and staff.' using errcode = '42501'; end if;
  if coalesce(trim(p_title), '') = '' then raise exception 'Give the list a name, like "Zoo field trip".'; end if;
  if p_day is null or p_day < app.school_today() then raise exception 'Choose today or a day coming up.'; end if;
  if not app.is_staff() and p_day <> app.school_today() then raise exception 'Substitutes make check-out lists for today only.'; end if;
  if coalesce(cardinality(p_students), 0) = 0 then raise exception 'Choose the students going.'; end if;
  foreach s in array p_students loop
    if not exists (select 1 from profiles where id = s and school_role = 'student') then raise exception 'Choose students only.'; end if;
    if not app.has_permission('checkin.manage') and not exists (
      select 1 from rosters r join roster_members m on m.roster_id = r.id
      where r.kind = 'section' and m.profile_id = s and ((r.lead_id = auth.uid() and app.is_staff()) or app.on_duty_for(r.id))) then
      raise exception '% isn''t in a class you lead.', app.checkin_name(s) using errcode = '42501';
    end if;
  end loop;
  insert into checkout_lists (title, day, created_by) values (trim(p_title), p_day, auth.uid()) returning id into new_id;
  insert into checkout_list_students (list_id, student_id) select new_id, x from unnest(p_students) x on conflict do nothing;
  return new_id;
end $$;

/** Students in the sections the caller leads or is covering right now (children without a login too), for a check-out list. */
create or replace function public.checkout_my_students() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'grade', x.grade, 'sections', x.sections) order by x.last, x.first), '[]'::jsonb)
  from (select p.id, trim(p.first_name || ' ' || p.last_name) as name, p.grade, p.first_name as first, p.last_name as last,
          string_agg(distinct r.name, ', ') as sections
        from rosters r join roster_members m on m.roster_id = r.id join profiles p on p.id = m.profile_id
        where r.kind = 'section' and ((r.lead_id = auth.uid() and app.is_staff()) or app.on_duty_for(r.id)) and p.school_role = 'student'
        group by p.id, p.first_name, p.last_name, p.grade) x
$$;

-- ----------------------------------------------------------------------
-- School-wide while on duty: critical alerts and the car line board
-- ----------------------------------------------------------------------

/** Who gets critical alerts: teachers, staff and admins, and substitutes on duty. */
create function app.alert_reader(u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.is_staff(u) or app.on_duty(u)
$$;

/** Everyone a critical alert goes to (and its roll call lists): staff with a login, and substitutes on duty. */
create or replace function app.alert_staff() returns setof uuid
language sql stable security definer set search_path = public as $$
  select id from profiles where school_role in ('admin', 'teacher', 'staff') and not managed
  union
  select id from profiles where school_role = 'substitute' and app.on_duty(id)
$$;

drop policy "teachers and staff" on public.critical_alerts;
create policy "teachers, staff and substitutes on duty" on public.critical_alerts for select to authenticated using (app.alert_reader());

/** Alerts go to the staff roles; substitutes on duty get their own copy of each (data.alertId always pushes). */
create function app.alerts_reach_subs() returns trigger
language plpgsql security definer set search_path = public as $$
declare u uuid;
begin
  if new.audience = 'roles' and new.data ? 'alertId' then
    for u in select id from profiles where school_role = 'substitute' and app.on_duty(id) loop
      insert into notifications (audience, user_id, title, body, data, urgent, created_by)
      values ('user', u, new.title, new.body, new.data, new.urgent, new.created_by);
    end loop;
  end if;
  return null;
end $$;
create trigger alerts_reach_subs after insert on public.notifications for each row execute function app.alerts_reach_subs();

/** A teacher, staff member or substitute on duty answers: safe, or needs help (the senders are told at once). */
create or replace function public.critical_alert_respond(p_alert uuid, p_status text, p_note text default null)
returns public.critical_alert_responses
language plpgsql security definer set search_path = public as $$
declare a critical_alerts%rowtype; r critical_alert_responses%rowtype; u uuid;
begin
  if not app.alert_reader() then raise exception 'Critical alerts are for teachers and staff.' using errcode = '42501'; end if;
  select * into a from critical_alerts where id = p_alert;
  if not found then raise exception 'No such alert.'; end if;
  if a.ended_at is not null then raise exception 'This alert has ended.'; end if;
  if p_status is null or p_status not in ('safe', 'help') then raise exception 'Choose I''m safe or I need help.'; end if;
  if char_length(coalesce(p_note, '')) > 300 then raise exception 'Keep the note to 300 characters.'; end if;
  insert into critical_alert_responses (alert_id, user_id, status, note)
  values (a.id, auth.uid(), p_status, nullif(trim(p_note), ''))
  on conflict (alert_id, user_id) do update set status = excluded.status, note = excluded.note, updated_at = now()
  returning * into r;
  if p_status = 'help' then
    for u in select id from profiles
             where school_role is not null and id <> auth.uid() and ('alerts.send' = any (app.permissions(id)) or id = a.created_by) loop
      perform app.notify_user(u, '🆘 ' || app.short_name(auth.uid()) || ' needs help', coalesce(r.note, a.title),
        jsonb_build_object('alertId', a.id, 'kind', a.kind, 'critical', true, 'level', app.alert_level()));
    end loop;
  end if;
  return r;
end $$;

/** Yes or no to sending your location with critical alert answers (staff and substitutes on duty). */
create or replace function public.alert_location_consent(p_allowed boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not app.alert_reader() then raise exception 'Critical alerts are for teachers and staff.' using errcode = '42501'; end if;
  if p_allowed is null then raise exception 'Choose yes or no.'; end if;
  insert into location_consents (user_id, allowed) values (auth.uid(), p_allowed)
  on conflict (user_id) do update set allowed = excluded.allowed, answered_at = now();
end $$;

create or replace function public.critical_alert_share_location(p_alert uuid, p_lat double precision default null, p_lng double precision default null,
  p_accuracy real default null, p_located_at timestamptz default null, p_bssid text default null, p_ssid text default null,
  p_error text default null) returns void
language plpgsql security definer set search_path = public as $$
declare a critical_alerts%rowtype; ok boolean;
begin
  if not app.alert_reader() then raise exception 'Critical alerts are for teachers and staff.' using errcode = '42501'; end if;
  select * into a from critical_alerts where id = p_alert;
  if not found then raise exception 'No such alert.'; end if;
  if a.ended_at is not null and a.ended_at < now() - interval '10 minutes' then raise exception 'This alert has ended.'; end if;
  if not exists (select 1 from critical_alert_responses where alert_id = a.id and user_id = auth.uid()) then
    raise exception 'Answer the alert first.';
  end if;
  ok := coalesce((select allowed from location_consents where user_id = auth.uid()), false);
  if p_error is not null and p_error not in ('denied', 'unavailable') then raise exception 'Unknown location error.'; end if;
  if (p_lat is null) <> (p_lng is null) then raise exception 'Send both latitude and longitude.'; end if;
  update critical_alert_responses set
    lat = case when ok then p_lat end, lng = case when ok then p_lng end,
    accuracy_m = case when ok and p_lat is not null then greatest(p_accuracy, 0) end,
    located_at = case when ok and (p_lat is not null or p_bssid is not null) then least(coalesce(p_located_at, now()), now()) end,
    bssid = case when ok then app.normalize_mac(p_bssid) end,
    ssid = case when ok then nullif(left(trim(coalesce(p_ssid, '')), 64), '') end,
    location_error = case when not ok then 'no_consent'
                          when p_lat is null and app.normalize_mac(p_bssid) is null then coalesce(p_error, 'unavailable') end
  where alert_id = a.id and user_id = auth.uid();
end $$;

create or replace function public.carline_board() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not (app.is_staff() or app.on_duty()) then raise exception 'The car line board is for school staff.' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', c.id, 'studentId', c.student_id, 'status', c.status, 'via', c.via,
      'arrivedAt', c.arrived_at, 'pickedUpAt', c.picked_up_at, 'distanceM', c.distance_m,
      'number', n.number, 'name', trim(s.first_name || ' ' || s.last_name), 'grade', s.grade,
      'parent', trim(g.first_name || ' ' || g.last_name),
      'vehicle', c.vehicle->>'label', 'vehicleColor', c.vehicle->>'color', 'vehicleKind', c.vehicle->>'kind',
      'birthday', app.is_birthday(d.birthday),
      'pickedUpBy', trim(coalesce(b.first_name, '') || ' ' || coalesce(b.last_name, '')))
      order by c.arrived_at)
    from carline_pickups c
    join profiles s on s.id = c.student_id
    left join student_details d on d.student_id = c.student_id
    left join pickup_numbers n on n.student_id = c.student_id
    left join profiles g on g.id = c.guardian_id
    left join profiles b on b.id = c.picked_up_by
    where c.day = app.school_today() and c.status in ('waiting', 'picked_up')), '[]'::jsonb);
end $$;

-- The board updates live for substitutes on duty too.
drop policy "car line: children you pick up, or staff" on public.carline_pickups;
create policy "car line: children you pick up, staff, or a sub on duty" on public.carline_pickups for select to authenticated
  using (app.can_pick_up(student_id) or app.is_staff() or app.on_duty());

revoke all on function app.substitute_leaves_groups(), app.sub_when(date, date, time, time), app.sub_classes(uuid),
  app.sub_json(uuid, boolean), app.alerts_reach_subs() from public, anon, authenticated;
grant execute on function app.is_substitute(uuid), app.duty_now(date, date, time, time, timestamptz), app.on_duty_for(text, uuid),
  app.on_duty(uuid), app.schedules_for(text, uuid), app.manages_sub(uuid, uuid), app.keeps_roll(text, uuid), app.alert_reader(uuid)
  to authenticated, service_role;
revoke all on function public.sub_schedule_save(uuid, uuid, text[], date, date, time, time, text), public.sub_schedule_delete(uuid),
  public.sub_schedule_list(), public.my_sub_days(), public.sub_options() from public, anon;
grant execute on function public.sub_schedule_save(uuid, uuid, text[], date, date, time, time, text), public.sub_schedule_delete(uuid),
  public.sub_schedule_list(), public.my_sub_days(), public.sub_options() to authenticated, service_role;
grant select on public.sub_assignments, public.sub_assignment_sections to authenticated;
grant all on public.sub_assignments, public.sub_assignment_sections to service_role;

insert into app.applied_migrations (name) values ('20261030000048_substitutes.sql') on conflict do nothing;

-- ===== 20261030000049_event_tickets.sql =====
-- Ticketed events: an Activities event (a play, a game, a concert) can sell tickets.
--
-- The activity's coaches and directors, and sports.manage holders (app.runs_tickets), set it up: kinds of
-- ticket with a price and an optional limit (Adult $10, Student $5), whether it's on sale, when sales close
-- and how many one order may hold (ticket_event_save). Parents, staff and Family accounts buy
-- (app.can_buy_tickets): the tickets Edge Function holds them as the buyer (ticket_order_start; a hold lasts
-- 30 minutes) and sends them to Stripe Checkout, and Stripe's webhook (the same function) marks the order
-- paid (ticket_order_paid, service role only); the buyer is told. Free tickets are issued straight away.
-- Paid tickets show in My Tickets with a QR code (my_tickets) and can be added to Apple or Google Wallet
-- (ticket_for_wallet as the buyer, ticket_pass for the pass download link). At the door the same leaders scan
-- them (ticket_admit): each admits once. An order keeps the event's title and time, so deleting an event
-- never loses a payment record. Refunds are made in Stripe's dashboard for now.

create table public.ticketed_events (
  event_id      uuid primary key references public.sport_events (id) on delete cascade,
  on_sale       boolean not null default false,
  closes_at     timestamptz,                 -- null: sales close when the event starts
  max_per_order int not null default 10 check (max_per_order between 1 and 50),
  updated_by    uuid references public.profiles (id) on delete set null,
  updated_at    timestamptz not null default now()
);

create table public.ticket_types (
  id          uuid primary key default gen_random_uuid(),
  event_id    uuid not null references public.sport_events (id) on delete cascade,
  name        text not null check (char_length(trim(name)) between 1 and 60),
  price_cents int not null check (price_cents between 0 and 100000),
  capacity    int check (capacity is null or capacity between 1 and 10000),   -- null: no limit
  position    int not null default 0
);
create index on public.ticket_types (event_id, position);

create table public.ticket_orders (
  id              uuid primary key default gen_random_uuid(),
  event_id        uuid references public.sport_events (id) on delete set null,
  event_title     text not null,
  event_starts_at timestamptz not null,
  buyer_id        uuid references public.profiles (id) on delete set null,
  status          text not null default 'pending' check (status in ('pending', 'paid', 'cancelled')),
  total_cents     int not null default 0 check (total_cents >= 0),
  stripe_session  text unique,
  stripe_payment  text,
  expires_at      timestamptz not null default now() + interval '30 minutes',
  paid_at         timestamptz,
  created_at      timestamptz not null default now()
);
create index on public.ticket_orders (event_id, status);
create index on public.ticket_orders (buyer_id, created_at desc);

create table public.tickets (
  id          uuid primary key default gen_random_uuid(),
  order_id    uuid not null references public.ticket_orders (id) on delete cascade,
  type_id     uuid references public.ticket_types (id) on delete set null,
  type_name   text not null,
  price_cents int not null,
  code        text not null unique default replace(gen_random_uuid()::text, '-', ''),   -- the QR code: 122 random bits
  admitted_at timestamptz,
  admitted_by uuid references public.profiles (id) on delete set null
);
create index on public.tickets (order_id);
create index on public.tickets (type_id);

-- ----------------------------------------------------------------------
-- Helpers
-- ----------------------------------------------------------------------

/** Runs an event's tickets: the activity's coaches and directors, and sports.manage holders. */
create function app.runs_tickets(e uuid, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(app.can_manage_sport(app.event_sport(e), u), false)
$$;

/** Who buys tickets: approved parents, teachers, staff and Family accounts (not students or substitutes). */
create function app.can_buy_tickets(u uuid default auth.uid()) returns boolean
language sql stable as $$ select coalesce(app.school_role(u) in ('parent', 'teacher', 'staff', 'admin', 'family'), false) $$;

/** Tickets of a kind that are sold, or held by someone checking out right now. */
create function app.tickets_taken(t uuid) returns int
language sql stable security definer set search_path = public as $$
  select count(*)::int from tickets k join ticket_orders o on o.id = k.order_id
  where k.type_id = t and (o.status = 'paid' or (o.status = 'pending' and o.expires_at > now()))
$$;

/** On sale, not cancelled, and before sales close (when the event starts, unless the leaders set a time). */
create function app.ticket_sales_open(e uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select t.on_sale and not ev.cancelled and now() < coalesce(t.closes_at, ev.starts_at)
                   from ticketed_events t join sport_events ev on ev.id = t.event_id where t.event_id = e), false)
$$;

/** "Fall Play: Opening night". */
create function app.ticket_event_title(e uuid) returns text
language sql stable security definer set search_path = public as $$
  select coalesce(sp.name || ': ', '') || ev.title
  from sport_events ev left join sport_seasons ss on ss.id = ev.season_id left join sports sp on sp.id = ss.sport_id where ev.id = e
$$;

/** An order is paid (or free): its tickets count, and the buyer is told. A payment always wins, even for an order that had expired. Safe to call twice. */
create function app.ticket_order_complete(o uuid, p_session text, p_payment text) returns void
language plpgsql security definer set search_path = public as $$
declare r ticket_orders; n int;
begin
  update ticket_orders set status = 'paid', paid_at = now(),
    stripe_session = coalesce(p_session, stripe_session), stripe_payment = coalesce(p_payment, stripe_payment)
  where id = o and status <> 'paid' returning * into r;
  if not found then return; end if;
  select count(*) into n from tickets where order_id = o;
  if r.buyer_id is not null then
    perform app.notify_user(r.buyer_id, '🎟️ Your tickets: ' || r.event_title,
      n || case when n = 1 then ' ticket' else ' tickets' end || ' · ' || app.sport_when(r.event_starts_at) || '. They''re in My Tickets.',
      jsonb_build_object('ticketOrderId', o));
  end if;
  perform app.audit(null, 'tickets.paid', o::text, jsonb_build_object('event', r.event_id, 'tickets', n, 'total', r.total_cents));
end $$;

-- ----------------------------------------------------------------------
-- Read policies (writes go through the functions below)
-- ----------------------------------------------------------------------

alter table public.ticketed_events enable row level security;
alter table public.ticket_types enable row level security;
alter table public.ticket_orders enable row level security;
alter table public.tickets enable row level security;
create policy "approved accounts" on public.ticketed_events for select to authenticated using (app.school_role() is not null);
create policy "approved accounts" on public.ticket_types for select to authenticated using (app.school_role() is not null);
create policy "the buyer, and the event's leaders" on public.ticket_orders for select to authenticated
  using (buyer_id = auth.uid() or (event_id is not null and app.runs_tickets(event_id)));
create policy "the buyer, and the event's leaders" on public.tickets for select to authenticated
  using (exists (select 1 from ticket_orders o where o.id = order_id
                 and (o.buyer_id = auth.uid() or (o.event_id is not null and app.runs_tickets(o.event_id)))));

-- ----------------------------------------------------------------------
-- Leaders: set up an event's tickets, see the sales, check tickets at the door
-- ----------------------------------------------------------------------

/**
 * The event's leaders: sell tickets for it (or stop). p_types is the whole list, in order:
 * [{ id?, name, priceCents, capacity? }]; kinds left out are removed, unless they have tickets sold.
 */
create function public.ticket_event_save(p_event uuid, p_on_sale boolean, p_closes_at timestamptz, p_types jsonb, p_max_per_order int default 10)
returns void
language plpgsql security definer set search_path = public as $$
declare e sport_events; t jsonb; keep uuid[] := '{}'; tid uuid; n int := 0; price int; cap int; gone text;
begin
  select * into e from sport_events where id = p_event;
  if not found then raise exception 'That event is gone.'; end if;
  if not app.runs_tickets(p_event) then
    raise exception 'Only the activity''s coaches and directors can sell tickets for it.' using errcode = '42501';
  end if;
  if jsonb_typeof(coalesce(p_types, '[]'::jsonb)) <> 'array' then raise exception 'List the kinds of ticket.'; end if;
  if coalesce(p_on_sale, false) and jsonb_array_length(coalesce(p_types, '[]'::jsonb)) = 0 then
    raise exception 'Add at least one kind of ticket, like Adult or Student.';
  end if;
  if coalesce(p_max_per_order, 10) not between 1 and 50 then raise exception 'One order can hold 1 to 50 tickets.'; end if;
  if p_closes_at is not null and p_closes_at > coalesce(e.ends_at, e.starts_at + interval '6 hours') then
    raise exception 'Sales have to close by the time the event ends.';
  end if;

  insert into ticketed_events (event_id, on_sale, closes_at, max_per_order, updated_by)
  values (p_event, coalesce(p_on_sale, false), p_closes_at, coalesce(p_max_per_order, 10), auth.uid())
  on conflict (event_id) do update set on_sale = excluded.on_sale, closes_at = excluded.closes_at,
    max_per_order = excluded.max_per_order, updated_by = excluded.updated_by, updated_at = now();

  for t in select * from jsonb_array_elements(coalesce(p_types, '[]'::jsonb)) loop
    n := n + 1;
    if coalesce(trim(t->>'name'), '') = '' then raise exception 'Give each kind of ticket a name, like Adult or Student.'; end if;
    price := (t->>'priceCents')::int;
    if price is null or price not between 0 and 100000 then raise exception 'Ticket prices go from free to $1,000.'; end if;
    cap := nullif(t->>'capacity', '')::int;
    if cap is not null and cap not between 1 and 10000 then raise exception 'A limit goes from 1 to 10,000 tickets.'; end if;
    tid := nullif(t->>'id', '')::uuid;
    if tid is not null and exists (select 1 from ticket_types where id = tid and event_id = p_event) then
      if cap is not null and cap < app.tickets_taken(tid) then
        raise exception '% has % sold already; the limit can''t go below that.', trim(t->>'name'), app.tickets_taken(tid);
      end if;
      update ticket_types set name = trim(t->>'name'), price_cents = price, capacity = cap, position = n where id = tid;
    else
      insert into ticket_types (event_id, name, price_cents, capacity, position) values (p_event, trim(t->>'name'), price, cap, n)
      returning id into tid;
    end if;
    keep := keep || tid;
  end loop;
  select x.name into gone from ticket_types x where x.event_id = p_event and not (x.id = any (keep))
    and exists (select 1 from tickets k join ticket_orders o on o.id = k.order_id where k.type_id = x.id and o.status = 'paid') limit 1;
  if gone is not null then
    raise exception '% has tickets sold, so it can''t be removed. Set its limit to what''s sold to stop selling it.', gone;
  end if;
  delete from ticket_types where event_id = p_event and not (id = any (keep));
  perform app.audit(null, 'tickets.setup', p_event::text, jsonb_build_object('onSale', p_on_sale, 'types', jsonb_array_length(coalesce(p_types, '[]'::jsonb))));
end $$;

/** An event's tickets: the kinds for sale with what's left, whether they're on sale, and how many the caller holds; its leaders also get sold, admitted and the takings. */
create function public.ticket_event(p_event uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare e sport_events; te ticketed_events; leader boolean := app.runs_tickets(p_event);
begin
  select * into e from sport_events where id = p_event;
  if not found then raise exception 'That event is gone.'; end if;
  if not (leader or app.can_buy_tickets()) then raise exception 'Tickets are for parents, staff and family.' using errcode = '42501'; end if;
  select * into te from ticketed_events where event_id = p_event;
  return jsonb_build_object(
    'eventId', e.id, 'title', app.ticket_event_title(e.id), 'startsAt', e.starts_at, 'endsAt', e.ends_at,
    'location', e.location, 'address', e.address, 'cancelled', e.cancelled,
    'onSale', coalesce(te.on_sale, false), 'closesAt', te.closes_at, 'maxPerOrder', coalesce(te.max_per_order, 10),
    'open', app.ticket_sales_open(e.id), 'canBuy', app.can_buy_tickets(), 'leader', leader,
    'types', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'priceCents', t.price_cents, 'capacity', t.capacity,
        'left', case when t.capacity is null then null else greatest(t.capacity - app.tickets_taken(t.id), 0) end,
        'sold', case when leader then (select count(*) from tickets k join ticket_orders o on o.id = k.order_id where k.type_id = t.id and o.status = 'paid') end,
        'admitted', case when leader then (select count(*) from tickets k where k.type_id = t.id and k.admitted_at is not null) end)
        order by t.position) from ticket_types t where t.event_id = e.id), '[]'::jsonb),
    'mine', (select count(*) from tickets k join ticket_orders o on o.id = k.order_id
             where o.event_id = e.id and o.buyer_id = auth.uid() and o.status = 'paid'),
    'takingsCents', case when leader then (select coalesce(sum(total_cents), 0) from ticket_orders where event_id = e.id and status = 'paid') end);
end $$;

/** The event's leaders: who bought tickets (paid orders, newest first). */
create function public.ticket_sales(p_event uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not app.runs_tickets(p_event) then
    raise exception 'Only the activity''s coaches and directors can see its ticket sales.' using errcode = '42501';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'buyer', app.checkin_name(o.buyer_id), 'totalCents', o.total_cents,
      'paidAt', o.paid_at, 'tickets', (select string_agg(x.n || ' ' || x.type_name, ', ' order by x.type_name)
        from (select type_name, count(*) as n from tickets where order_id = o.id group by type_name) x),
      'admitted', (select count(*) from tickets where order_id = o.id and admitted_at is not null),
      'count', (select count(*) from tickets where order_id = o.id)) order by o.paid_at desc)
    from ticket_orders o where o.event_id = p_event and o.status = 'paid'), '[]'::jsonb);
end $$;

/** The event's leaders at the door: admit a ticket by its scanned code (or the short code typed). Each ticket admits once. */
create function public.ticket_admit(p_event uuid, p_code text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c text := lower(regexp_replace(coalesce(p_code, ''), '[^0-9a-fA-F]', '', 'g')); k tickets; o ticket_orders; counts jsonb;
begin
  if not app.runs_tickets(p_event) then
    raise exception 'Only the activity''s coaches and directors can check its tickets.' using errcode = '42501';
  end if;
  if char_length(c) = 32 then
    select * into k from tickets where code = c;
  elsif char_length(c) >= 8 then   -- typed: the short code under the QR code, for this event's tickets
    select x.* into k from tickets x join ticket_orders xo on xo.id = x.order_id where xo.event_id = p_event and x.code like c || '%' limit 1;
  end if;
  if k.id is null then return jsonb_build_object('ok', false, 'message', 'Not a KH Royals ticket.'); end if;
  select * into o from ticket_orders where id = k.order_id;
  if o.event_id is distinct from p_event then
    return jsonb_build_object('ok', false, 'message', 'This ticket is for ' || o.event_title || '.', 'holder', app.checkin_name(o.buyer_id), 'type', k.type_name);
  end if;
  if o.status <> 'paid' then return jsonb_build_object('ok', false, 'message', 'This ticket wasn''t paid for.'); end if;
  if k.admitted_at is not null then
    return jsonb_build_object('ok', false, 'message', 'Already used at ' || app.checkin_time(k.admitted_at) || '.',
      'holder', app.checkin_name(o.buyer_id), 'type', k.type_name);
  end if;
  update tickets set admitted_at = now(), admitted_by = auth.uid() where id = k.id;
  select jsonb_build_object('admitted', count(*) filter (where t.admitted_at is not null), 'sold', count(*)) into counts
  from tickets t join ticket_orders x on x.id = t.order_id where x.event_id = p_event and x.status = 'paid';
  return jsonb_build_object('ok', true, 'holder', app.checkin_name(o.buyer_id), 'type', k.type_name) || counts;
end $$;

-- ----------------------------------------------------------------------
-- Buyers
-- ----------------------------------------------------------------------

/** Upcoming events with tickets on sale, with the lowest price (for the Tickets buttons in Activities). */
create function public.tickets_on_sale() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('eventId', t.event_id,
      'fromCents', (select min(price_cents) from ticket_types where event_id = t.event_id))), '[]'::jsonb)
  from ticketed_events t where app.school_role() is not null and app.ticket_sales_open(t.event_id)
$$;

/**
 * Hold tickets for the caller (the tickets Edge Function, as the buyer): p_items is
 * [{ typeId, quantity }]. Returns the order for Stripe Checkout; a free order is issued at once.
 * Starting again drops the caller's earlier hold for the event.
 */
create function public.ticket_order_start(p_event uuid, p_items jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare e sport_events; te ticketed_events; it jsonb; ty ticket_types; q int; total int := 0; n int := 0; o uuid; lines jsonb := '[]'::jsonb;
  title text; taken int;
begin
  if not app.can_buy_tickets() then raise exception 'Tickets are for parents, staff and family.' using errcode = '42501'; end if;
  select * into e from sport_events where id = p_event;
  if not found then raise exception 'That event is gone.'; end if;
  if not app.ticket_sales_open(p_event) then raise exception 'Tickets for this event aren''t on sale.'; end if;
  select * into te from ticketed_events where event_id = p_event;
  update ticket_orders set status = 'cancelled' where event_id = p_event and buyer_id = auth.uid() and status = 'pending';
  title := app.ticket_event_title(p_event);
  insert into ticket_orders (event_id, event_title, event_starts_at, buyer_id) values (p_event, title, e.starts_at, auth.uid()) returning id into o;
  for it in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    q := coalesce((it->>'quantity')::int, 0);
    if q = 0 then continue; end if;
    if q < 0 then raise exception 'Choose how many tickets.'; end if;
    select * into ty from ticket_types where id = (it->>'typeId')::uuid and event_id = p_event for update;   -- one buyer at a time per kind
    if not found then raise exception 'That kind of ticket isn''t sold anymore.'; end if;
    taken := app.tickets_taken(ty.id);
    if ty.capacity is not null and taken + q > ty.capacity then
      raise exception 'Only % % % left.', greatest(ty.capacity - taken, 0), ty.name, case when ty.capacity - taken = 1 then 'ticket' else 'tickets' end;
    end if;
    insert into tickets (order_id, type_id, type_name, price_cents) select o, ty.id, ty.name, ty.price_cents from generate_series(1, q);
    total := total + q * ty.price_cents;
    n := n + q;
    lines := lines || jsonb_build_object('name', ty.name, 'priceCents', ty.price_cents, 'quantity', q);
  end loop;
  if n = 0 then raise exception 'Choose how many tickets.'; end if;
  if n > coalesce(te.max_per_order, 10) then raise exception 'Up to % tickets at a time.', coalesce(te.max_per_order, 10); end if;
  update ticket_orders set total_cents = total where id = o;
  if total = 0 then perform app.ticket_order_complete(o, null, null); end if;
  return jsonb_build_object('orderId', o, 'title', title, 'startsAt', e.starts_at, 'totalCents', total, 'lines', lines, 'free', total = 0,
    'email', (select email from auth.users where id = auth.uid()));
end $$;

/** The buyer: how a checkout ended (paid, still waiting on Stripe, or cancelled). */
create function public.ticket_order_status(p_order uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('status', case when o.status = 'pending' and o.expires_at <= now() then 'cancelled' else o.status end,
    'tickets', (select count(*) from tickets where order_id = o.id), 'title', o.event_title)
  from ticket_orders o where o.id = p_order and o.buyer_id = auth.uid()
$$;

/** The buyer leaves checkout without paying: the hold is let go (a payment that still arrives wins). */
create function public.ticket_order_cancel(p_order uuid) returns void
language sql security definer set search_path = public as $$
  update ticket_orders set status = 'cancelled' where id = p_order and buyer_id = auth.uid() and status = 'pending'
$$;

/** The caller's paid tickets for events from yesterday on, soonest first. */
create function public.my_tickets() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'code', k.code, 'type', k.type_name, 'priceCents', k.price_cents,
      'admittedAt', k.admitted_at, 'orderId', o.id, 'eventId', o.event_id, 'title', o.event_title, 'startsAt', o.event_starts_at,
      'location', ev.location, 'address', ev.address, 'cancelled', coalesce(ev.cancelled, false), 'holder', app.checkin_name(o.buyer_id))
      order by o.event_starts_at, o.id, k.type_name, k.id), '[]'::jsonb)
  from tickets k join ticket_orders o on o.id = k.order_id left join sport_events ev on ev.id = o.event_id
  where o.buyer_id = auth.uid() and o.status = 'paid' and o.event_starts_at > now() - interval '1 day'
$$;

/** What a Wallet pass shows for a paid ticket (null if it isn't paid). */
create function app.ticket_pass_data(p_ticket uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', k.id, 'code', k.code, 'type', k.type_name, 'priceCents', k.price_cents, 'eventId', o.event_id,
      'title', o.event_title, 'startsAt', o.event_starts_at, 'endsAt', ev.ends_at, 'location', ev.location, 'address', ev.address,
      'holder', app.checkin_name(o.buyer_id))
  from tickets k join ticket_orders o on o.id = k.order_id left join sport_events ev on ev.id = o.event_id
  where k.id = p_ticket and o.status = 'paid'
$$;

/** One of the caller's paid tickets, for a Wallet pass (the tickets Edge Function, as the caller). */
create function public.ticket_for_wallet(p_ticket uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not exists (select 1 from tickets k join ticket_orders o on o.id = k.order_id where k.id = p_ticket and o.buyer_id = auth.uid() and o.status = 'paid') then
    raise exception 'That ticket isn''t yours.' using errcode = '42501';
  end if;
  return app.ticket_pass_data(p_ticket);
end $$;

/** A paid ticket's Wallet pass details, for the pass download link (the Edge Function checked the link's signature). */
create function public.ticket_pass(p_ticket uuid) returns jsonb
language sql stable security definer set search_path = public as $$ select app.ticket_pass_data(p_ticket) $$;

-- ----------------------------------------------------------------------
-- Stripe (the Edge Functions, with the service role only)
-- ----------------------------------------------------------------------

/** The checkout page was made: remember it, and hold the tickets as long as it lasts. */
create function public.ticket_order_checkout(p_order uuid, p_session text, p_expires_at timestamptz) returns void
language sql security definer set search_path = public as $$
  update ticket_orders set stripe_session = p_session, expires_at = greatest(expires_at, p_expires_at) where id = p_order
$$;

create function public.ticket_order_paid(p_order uuid, p_session text, p_payment text) returns void
language sql security definer set search_path = public as $$ select app.ticket_order_complete(p_order, p_session, p_payment) $$;

/** Stripe let the checkout page expire unpaid. */
create function public.ticket_order_expired(p_order uuid) returns void
language sql security definer set search_path = public as $$
  update ticket_orders set status = 'cancelled' where id = p_order and status = 'pending'
$$;

revoke all on function app.tickets_taken(uuid), app.ticket_sales_open(uuid), app.ticket_event_title(uuid),
  app.ticket_order_complete(uuid, text, text), app.ticket_pass_data(uuid) from public, anon, authenticated;
grant execute on function app.runs_tickets(uuid, uuid), app.can_buy_tickets(uuid) to authenticated, service_role;
revoke all on function public.ticket_event_save(uuid, boolean, timestamptz, jsonb, int), public.ticket_event(uuid), public.ticket_sales(uuid),
  public.ticket_admit(uuid, text), public.tickets_on_sale(), public.ticket_order_start(uuid, jsonb), public.ticket_order_status(uuid),
  public.ticket_order_cancel(uuid), public.my_tickets(), public.ticket_for_wallet(uuid),
  public.ticket_order_checkout(uuid, text, timestamptz), public.ticket_order_paid(uuid, text, text), public.ticket_order_expired(uuid),
  public.ticket_pass(uuid) from public, anon, authenticated;
grant execute on function public.ticket_event_save(uuid, boolean, timestamptz, jsonb, int), public.ticket_event(uuid), public.ticket_sales(uuid),
  public.ticket_admit(uuid, text), public.tickets_on_sale(), public.ticket_order_start(uuid, jsonb), public.ticket_order_status(uuid),
  public.ticket_order_cancel(uuid), public.my_tickets(), public.ticket_for_wallet(uuid) to authenticated, service_role;
grant execute on function public.ticket_order_checkout(uuid, text, timestamptz), public.ticket_order_paid(uuid, text, text),
  public.ticket_order_expired(uuid), public.ticket_pass(uuid) to service_role;
grant select on public.ticketed_events, public.ticket_types, public.ticket_orders, public.tickets to authenticated;
grant all on public.ticketed_events, public.ticket_types, public.ticket_orders, public.tickets to service_role;

insert into app.applied_migrations (name) values ('20261030000049_event_tickets.sql') on conflict do nothing;

-- ===== 20261031000050_vehicle_for_today.sql =====
-- Today's vehicle: the button under Check In (and My vehicles → Use for next pickup) picks the vehicle you're
-- using. It becomes your default, as before, and if you're already in line staff see the new one on the board
-- straight away; you keep your place.

/** Make one of your vehicles today's: the default for the next pickup, and what staff look for if you're in line. */
create or replace function public.vehicle_use(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v vehicles%rowtype;
begin
  update vehicles set last_used_at = now() where id = p_id and owner_id = auth.uid() returning * into v;
  if not found then raise exception 'That vehicle isn''t one of yours.' using errcode = '42501'; end if;
  update carline_pickups set vehicle = app.vehicle_snapshot(v)
   where guardian_id = auth.uid() and day = app.school_today() and status = 'waiting';
end $$;

insert into app.applied_migrations (name) values ('20261031000050_vehicle_for_today.sql') on conflict do nothing;

-- ===== 20261031000051_pickup_transfers.sql =====
-- Pickup transfers: from the Car Line, a parent hands their children's pickup to another approved account for a
-- day (today or a day ahead). They find the person by name (pickup_transfer_people: approved adults, never
-- students or substitutes, names only) and ask (pickup_transfer); the person accepts or declines
-- (pickup_transfer_answer). Until they accept, the parents keep pickup, and a parent checking in calls the ask off.
-- Once accepted, on that day the child is in the person's car line (app.pickup_children) and nobody else can check
-- the child in (trigger on carline_pickups), until a parent cancels it or the person says they can't make it
-- (pickup_transfer_cancel). Everyone involved hears about each step.

create table public.pickup_transfers (
  id          uuid primary key default gen_random_uuid(),
  request_id  uuid not null,                    -- one ask can cover several children
  student_id  uuid not null references public.profiles (id) on delete cascade,
  from_id     uuid references public.profiles (id) on delete set null,
  to_id       uuid not null references public.profiles (id) on delete cascade,
  day         date not null,
  status      text not null default 'pending' check (status in ('pending', 'accepted', 'declined', 'cancelled')),
  created_at  timestamptz not null default now(),
  answered_at timestamptz
);
-- One live handoff per child and day.
create unique index pickup_transfers_one_a_day on public.pickup_transfers (student_id, day) where status in ('pending', 'accepted');
create index pickup_transfers_to on public.pickup_transfers (to_id, day);
create index pickup_transfers_request on public.pickup_transfers (request_id);
alter table public.pickup_transfers enable row level security;
create policy "the person, the child's parents, or staff" on public.pickup_transfers for select to authenticated
  using (to_id = auth.uid() or from_id = auth.uid() or app.is_guardian_of(student_id) or app.is_staff());
grant select on public.pickup_transfers to authenticated;
revoke insert, update, delete on public.pickup_transfers from anon, authenticated;
grant all on public.pickup_transfers to service_role;
alter publication supabase_realtime add table public.pickup_transfers;

/** "Priya Shah" */
create function app.person_name(u uuid) returns text
language sql stable security definer set search_path = public as $$
  select coalesce(nullif(trim(coalesce(first_name, '') || ' ' || coalesce(last_name, '')), ''), 'Someone') from profiles where id = u
$$;

/** "Ava", "Ava and Leo", "Ava, Leo and Mia" */
create function app.and_list(t text[]) returns text
language sql immutable as $$
  select case coalesce(cardinality(t), 0) when 0 then '' when 1 then t[1]
         else array_to_string(t[1:cardinality(t) - 1], ', ') || ' and ' || t[cardinality(t)] end
$$;

/** "today", "tomorrow", "on Tue, Nov 3" */
create function app.transfer_day(d date) returns text
language sql stable as $$
  select case d - app.school_today() when 0 then 'today' when 1 then 'tomorrow' else 'on ' || to_char(d, 'FMDy, FMMon FMDD') end
$$;

/** Someone pickup can be handed to: an approved adult account, never a student, a substitute or a child without a login. */
create function app.can_take_pickup(u uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from profiles where id = u and school_role is not null and school_role not in ('student', 'substitute')
                   and not managed)
$$;

/** Children someone may pick up today: as before, plus children whose pickup was handed to them for today. */
create or replace function app.pickup_children(u uuid default auth.uid()) returns setof uuid
language sql stable security definer set search_path = public as $$
  select student_id from guardians where guardian_id = u and not app.is_family(u)
  union
  select student_id from family_pickups where family_id = u and app.is_family(u)
  union
  select student_id from pickup_authorizations
  where person_id = u and app.school_today() between starts_on and coalesce(ends_on, app.school_today())
    and coalesce(app.school_role(u), 'student') <> 'student'
  union
  select student_id from pickup_transfers
  where to_id = u and day = app.school_today() and status = 'accepted' and app.can_take_pickup(u)
$$;

/**
 * Check-ins follow handoffs: once a child's pickup is handed to someone for the day, only they check the child in
 * (anyone else's check-in skips that child, so a parent's "check in everyone" still covers the rest). A check-in
 * while an ask is waiting for an answer calls the ask off.
 */
create function app.pickup_transfer_check_in() returns trigger
language plpgsql security definer set search_path = public as $$
declare t pickup_transfers%rowtype; kid text;
begin
  if new.guardian_id is null then return new; end if;
  if exists (select 1 from pickup_transfers where student_id = new.student_id and day = new.day and status = 'accepted'
               and to_id <> new.guardian_id) then
    return null;
  end if;
  for t in select * from pickup_transfers where student_id = new.student_id and day = new.day and status = 'pending'
             and to_id <> new.guardian_id loop
    update pickup_transfers set status = 'cancelled', answered_at = now() where id = t.id;
    select trim(first_name) into kid from profiles where id = t.student_id;
    perform app.notify_user(t.to_id, 'Pickup of ' || kid || ' called off',
      app.person_name(new.guardian_id) || ' is picking up ' || kid || ' after all, so you don''t need to.',
      jsonb_build_object('carline', 'transfer'));
  end loop;
  return new;
end $$;
create trigger pickup_transfer_check_in before insert on public.carline_pickups
  for each row execute function app.pickup_transfer_check_in();

/** Parents: who they can hand pickup to, by name. Approved adults only, and only their names. */
create function public.pickup_transfer_people(p_query text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare q text := lower(trim(coalesce(p_query, '')));
begin
  if app.is_family() or not exists (select 1 from guardians where guardian_id = auth.uid()) then
    raise exception 'Only parents can hand pickup to someone else.' using errcode = '42501';
  end if;
  if length(q) < 2 then return '[]'::jsonb; end if;
  q := replace(replace(replace(q, '\', '\\'), '%', '\%'), '_', '\_');
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name) order by x.last_name, x.first_name)
    from (select p.id, trim(p.first_name || ' ' || p.last_name) as name, p.first_name, p.last_name
          from profiles p
          where p.id <> auth.uid() and app.can_take_pickup(p.id)
            and (lower(trim(p.first_name || ' ' || p.last_name)) like '%' || q || '%' or lower(p.last_name) like q || '%')
          order by p.last_name, p.first_name limit 20) x), '[]'::jsonb);
end $$;

/** A parent asks someone to pick these children up on a day (today or ahead). Returns the ask's id. */
create function public.pickup_transfer(p_students uuid[], p_to uuid, p_day date default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare d date := coalesce(p_day, app.school_today()); req uuid := gen_random_uuid(); s uuid; kid text; names text[] := '{}';
begin
  if coalesce(cardinality(p_students), 0) = 0 then raise exception 'Choose who they''re picking up.'; end if;
  if exists (select 1 from unnest(p_students) x where not app.is_guardian_of(x)) then
    raise exception 'Only a child''s parents can hand their pickup to someone else.' using errcode = '42501';
  end if;
  if p_to is null or p_to = auth.uid() or not app.can_take_pickup(p_to) then
    raise exception 'Choose someone else with an approved Royals Connect account.';
  end if;
  if d < app.school_today() then raise exception 'Choose today or a day ahead.'; end if;
  if d > app.school_today() + 60 then raise exception 'Choose a day in the next two months.'; end if;
  if (select count(distinct request_id) from pickup_transfers
       where from_id = auth.uid() and created_at > now() - interval '1 day') >= 20 then
    raise exception 'That''s a lot of pickup requests for one day. Try again tomorrow.';
  end if;
  for s in select distinct x from unnest(p_students) x loop
    select trim(first_name) into kid from profiles where id = s;
    if exists (select 1 from pickup_transfers where student_id = s and day = d and status in ('pending', 'accepted')) then
      raise exception '%''s pickup % is already handed to someone. Cancel that first.', kid, app.transfer_day(d);
    end if;
    if d = app.school_today() and exists (select 1 from carline_pickups where student_id = s and day = d
                                            and status in ('waiting', 'picked_up')) then
      raise exception '% is already in the car line or picked up today.', kid;
    end if;
    insert into pickup_transfers (request_id, student_id, from_id, to_id, day) values (req, s, auth.uid(), p_to, d);
    names := names || kid;
  end loop;
  select array_agg(n order by n) into names from unnest(names) n;
  perform app.notify_user(p_to, '🚗 Can you pick up ' || app.and_list(names) || '?',
    app.person_name(auth.uid()) || ' asks you to pick up ' || app.and_list(names) || ' from the car line '
      || app.transfer_day(d) || '. Open the Car Line to accept or decline.',
    jsonb_build_object('carline', 'transfer', 'request', req));
  perform app.audit(null, 'pickup.transfer_asked', req::text,
    jsonb_build_object('to', p_to, 'day', d, 'students', to_jsonb(p_students)));
  return req;
end $$;

/** The person asked accepts or declines (every child in the ask); the parents hear the answer. */
create function public.pickup_transfer_answer(p_request uuid, p_accept boolean) returns void
language plpgsql security definer set search_path = public as $$
declare d date; who text := app.person_name(auth.uid()); fname text; r record;
begin
  select min(day) into d from pickup_transfers
   where request_id = p_request and to_id = auth.uid() and status = 'pending' and day >= app.school_today();
  if d is null then raise exception 'That pickup request isn''t waiting for your answer anymore.'; end if;
  update pickup_transfers set status = case when p_accept then 'accepted' else 'declined' end, answered_at = now()
   where request_id = p_request and to_id = auth.uid() and status = 'pending';
  select trim(first_name) into fname from profiles where id = auth.uid();
  for r in select g.guardian_id, array_agg(trim(p.first_name) order by p.first_name) as kids
             from pickup_transfers x join guardians g on g.student_id = x.student_id join profiles p on p.id = x.student_id
            where x.request_id = p_request and not app.is_family(g.guardian_id)
            group by g.guardian_id loop
    if p_accept then
      perform app.notify_user(r.guardian_id, '✅ ' || who || ' will pick up ' || app.and_list(r.kids),
        fname || ' will pick up ' || app.and_list(r.kids) || ' from the car line ' || app.transfer_day(d)
          || '. Cancel it in the Car Line if plans change.',
        jsonb_build_object('carline', 'transfer'));
    else
      perform app.notify_user(r.guardian_id, who || ' can''t pick up ' || app.and_list(r.kids),
        fname || ' declined picking up ' || app.and_list(r.kids) || ' ' || app.transfer_day(d) || ', so pickup stays with you.',
        jsonb_build_object('carline', 'transfer'));
    end if;
  end loop;
  perform app.audit(null, case when p_accept then 'pickup.transfer_accepted' else 'pickup.transfer_declined' end, p_request::text, null);
end $$;

/**
 * Call a handoff off: a parent of the child, or the person it was handed to ("can't make it"). Pending or accepted,
 * never once the child is picked up; the person's check-in for the child, if any, is cancelled with it.
 */
create function public.pickup_transfer_cancel(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare t pickup_transfers%rowtype; kid text; who text := app.person_name(auth.uid()); g uuid;
begin
  select * into t from pickup_transfers where id = p_id and status in ('pending', 'accepted') for update;
  if not found or not (app.is_guardian_of(t.student_id) or t.to_id = auth.uid()) then
    raise exception 'That pickup handoff can''t be changed.' using errcode = '42501';
  end if;
  select trim(first_name) into kid from profiles where id = t.student_id;
  if exists (select 1 from carline_pickups where student_id = t.student_id and day = t.day and status = 'picked_up') then
    raise exception '% was already picked up.', kid;
  end if;
  update pickup_transfers set status = 'cancelled', answered_at = now() where id = p_id;
  update carline_pickups set status = 'cancelled'
   where student_id = t.student_id and day = t.day and status = 'waiting' and guardian_id = t.to_id;
  if auth.uid() = t.to_id then
    for g in select guardian_id from guardians where student_id = t.student_id and not app.is_family(guardian_id) loop
      perform app.notify_user(g, who || ' can''t pick up ' || kid,
        who || ' can''t pick up ' || kid || ' ' || app.transfer_day(t.day) || ' after all, so pickup is back with you.',
        jsonb_build_object('carline', 'transfer'));
    end loop;
  else
    perform app.notify_user(t.to_id, 'Pickup of ' || kid || ' called off',
      who || ' called off your pickup of ' || kid || ' ' || app.transfer_day(t.day) || '. You don''t need to pick ' || kid || ' up.',
      jsonb_build_object('carline', 'transfer'));
    if t.status = 'accepted' then
      for g in select guardian_id from guardians where student_id = t.student_id and guardian_id <> auth.uid()
                 and not app.is_family(guardian_id) loop
        perform app.notify_user(g, 'Pickup of ' || kid || ' is back with you',
          who || ' cancelled ' || app.person_name(t.to_id) || '''s pickup of ' || kid || ' ' || app.transfer_day(t.day) || '.',
          jsonb_build_object('carline', 'transfer'));
      end loop;
    end if;
  end if;
  perform app.audit(null, 'pickup.transfer_cancelled', t.request_id::text, jsonb_build_object('student', t.student_id));
end $$;

/** Handoffs from today on: your children's (whichever parent asked), and the asks made of you. */
create function public.my_pickup_transfers() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'children', coalesce((
      select jsonb_agg(jsonb_build_object('id', x.id, 'requestId', x.request_id, 'studentId', x.student_id, 'child', trim(s.first_name),
                                          'toId', x.to_id, 'to', app.person_name(x.to_id), 'from', app.person_name(x.from_id),
                                          'day', x.day, 'status', x.status)
                       order by x.day, s.first_name, x.created_at)
      from pickup_transfers x join profiles s on s.id = x.student_id
      where app.is_guardian_of(x.student_id) and x.day >= app.school_today() and x.status in ('pending', 'accepted', 'declined')),
      '[]'::jsonb),
    'asked', coalesce((
      select jsonb_agg(q.r order by q.day, q.created)
      from (select x.day, min(x.created_at) as created,
                   jsonb_build_object('requestId', x.request_id, 'from', app.person_name(x.from_id), 'day', x.day, 'status', x.status,
                     'children', jsonb_agg(jsonb_build_object('id', x.id, 'studentId', x.student_id,
                                                              'name', trim(s.first_name || ' ' || s.last_name)) order by s.first_name)) as r
            from pickup_transfers x join profiles s on s.id = x.student_id
            where x.to_id = auth.uid() and x.day >= app.school_today() and x.status in ('pending', 'accepted')
            group by x.request_id, x.from_id, x.day, x.status) q),
      '[]'::jsonb))
$$;

revoke all on function app.pickup_transfer_check_in() from public, anon, authenticated;
revoke all on function public.pickup_transfer_people(text), public.pickup_transfer(uuid[], uuid, date),
  public.pickup_transfer_answer(uuid, boolean), public.pickup_transfer_cancel(uuid), public.my_pickup_transfers() from public, anon;
grant execute on function public.pickup_transfer_people(text), public.pickup_transfer(uuid[], uuid, date),
  public.pickup_transfer_answer(uuid, boolean), public.pickup_transfer_cancel(uuid), public.my_pickup_transfers()
  to authenticated, service_role;

