-- ===== 20261102000057_group_archive_delete.sql =====
-- Connect groups: archive, delete, and hide from your own list.
--
-- Archive (a group's owners, or groups.manage): the group disappears for everyone else (lists,
-- More groups, its posts, events and members) and takes no new posts, comments or events. Its
-- owners and groups.manage holders still find it under Archived groups, where they restore it or
-- delete it for good. Nothing is lost until it's deleted.
--
-- Delete (the same people, only once it's archived, typing the group's name to confirm): the
-- group goes with its posts, comments, events and memberships. The school's activity log keeps
-- who deleted which group.
--
-- Hide (any member): takes a group out of your own list (groups you were put in by the school
-- can't be left); Hidden groups brings it back. Nobody else sees the difference.

alter table public.groups
  add column archived_at timestamptz,
  add column archived_by uuid references public.profiles (id) on delete set null;

alter table public.memberships add column hidden_at timestamptz;

/** A group's owner, or groups.manage: the people who archive, restore and delete it. */
create function app.owns_group(g uuid, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.school_role(u) is not null and app.school_role(u) not in ('family', 'substitute')
     and (app.has_permission('groups.manage', u)
          or exists (select 1 from memberships where group_id = g and user_id = u and role = 'owner'))
$$;

/** Refuse someone who doesn't own the group: an admin who hasn't verified is told to, anyone else that only owners may. */
create function app.require_group_owner(what text) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  perform app.require_permission('groups.manage');
exception when insufficient_privilege then
  if sqlerrm like 'MFA_REQUIRED%' then raise; end if;
  raise exception 'Only the group''s owners can % it.', what using errcode = '42501';
end $$;

-- An archived group is only there for its owners (and groups.manage); for everyone else it's gone.
create or replace function app.effective_role(g uuid, u uuid default auth.uid()) returns text
language plpgsql stable security definer set search_path = public as $$
declare sr text; r text; vis text; archived boolean;
begin
  sr := app.school_role(u);
  if sr is null or sr in ('family', 'substitute') then return null; end if;  -- signed out, awaiting approval, Family or Substitute
  if app.has_permission('groups.manage', u) then return 'owner'; end if;
  select role into r from memberships where group_id = g and user_id = u;
  select settings->>'visibility', archived_at is not null into vis, archived from groups where id = g;
  if archived then return case when r = 'owner' then r end; end if;
  if r is not null then return r; end if;
  if vis in ('public', 'school') then return 'subscriber'; end if;
  return null;
end $$;

drop policy "discoverable groups" on public.groups;
create policy "discoverable groups" on public.groups for select to authenticated
  using (case when archived_at is not null then app.owns_group(id)
              else app.is_admin()
                   or (app.school_role() is not null and not app.is_family() and not app.is_substitute() and settings->>'visibility' <> 'hidden')
                   or app.is_member(id) end);

/** Nothing new goes into an archived group: no posts, comments or calendar events. */
create function app.refuse_archived() returns trigger
language plpgsql security definer set search_path = public as $$
declare g uuid;
begin
  if tg_table_name = 'comments' then select group_id into g from posts where id = new.post_id;
  else g := new.group_id;
  end if;
  if exists (select 1 from groups where id = g and archived_at is not null) then
    raise exception 'This group is archived. Restore it to post again.' using errcode = '42501';
  end if;
  return new;
end $$;
create trigger refuse_archived before insert on public.posts for each row execute function app.refuse_archived();
create trigger refuse_archived before insert on public.comments for each row execute function app.refuse_archived();
create trigger refuse_archived before insert on public.events for each row when (new.group_id is not null) execute function app.refuse_archived();

/** Your groups, minus archived ones and the ones you've hidden. */
create or replace function public.my_groups() returns setof public.groups
language sql stable security definer set search_path = public as $$
  select g.* from groups g
  where g.archived_at is null
    and (exists (select 1 from memberships m where m.group_id = g.id and m.user_id = auth.uid() and m.hidden_at is null)
         or (app.is_admin() and not exists (select 1 from memberships m where m.group_id = g.id and m.user_id = auth.uid() and m.hidden_at is not null)))
  order by g.name
$$;

/** Groups you've hidden from your list. */
create function public.my_hidden_groups() returns setof public.groups
language sql stable security definer set search_path = public as $$
  select g.* from groups g join memberships m on m.group_id = g.id and m.user_id = auth.uid()
  where m.hidden_at is not null and g.archived_at is null
  order by g.name
$$;

/** Archived groups you can restore or delete. */
create function public.archived_groups() returns setof public.groups
language sql stable security definer set search_path = public as $$
  select g.* from groups g where g.archived_at is not null and app.owns_group(g.id) order by g.archived_at desc
$$;

/** Hide a group from your own list, or bring it back. */
create function public.group_hide(p_group uuid, p_hidden boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  update memberships set hidden_at = case when p_hidden then now() end
  where group_id = p_group and user_id = auth.uid();
  if not found then raise exception 'You''re not in this group.'; end if;
end $$;

/** Archive a group (it disappears for everyone but its owners) or restore it. */
create function public.group_archive(p_group uuid, p_archived boolean) returns public.groups
language plpgsql security definer set search_path = public as $$
declare row groups%rowtype;
begin
  if not app.owns_group(p_group) then perform app.require_group_owner('archive'); end if;
  update groups set archived_at = case when p_archived then coalesce(archived_at, now()) end,
                    archived_by = case when p_archived then coalesce(archived_by, auth.uid()) end
  where id = p_group returning * into row;
  if not found then raise exception 'That group is gone.'; end if;
  perform app.audit(p_group, case when p_archived then 'group.archived' else 'group.restored' end, null, jsonb_build_object('name', row.name));
  return row;
end $$;

/** Delete an archived group for good, with everything in it; `p_name` must be its name, to confirm. */
create function public.group_delete(p_group uuid, p_name text) returns void
language plpgsql security definer set search_path = public as $$
declare g groups%rowtype; n int;
begin
  select * into g from groups where id = p_group;
  if not found then raise exception 'That group is gone.'; end if;
  if not app.owns_group(p_group) then perform app.require_group_owner('delete'); end if;
  if g.archived_at is null then raise exception 'Archive the group first; then it can be deleted.'; end if;
  if lower(trim(coalesce(p_name, ''))) is distinct from lower(trim(g.name)) then
    raise exception 'Type the group''s name, %, to delete it.', g.name;
  end if;
  select count(*) into n from posts where group_id = p_group;
  delete from groups where id = p_group;
  -- The group's own log goes with it; the school's log keeps that it was deleted.
  perform app.audit(null, 'group.deleted', p_group::text, jsonb_build_object('name', g.name, 'posts', n));
end $$;

revoke all on function public.my_hidden_groups(), public.archived_groups(), public.group_hide(uuid, boolean),
  public.group_archive(uuid, boolean), public.group_delete(uuid, text) from public, anon;
grant execute on function public.my_hidden_groups(), public.archived_groups(), public.group_hide(uuid, boolean),
  public.group_archive(uuid, boolean), public.group_delete(uuid, text) to authenticated, service_role;

insert into app.applied_migrations (name) values ('20261102000057_group_archive_delete.sql') on conflict do nothing;

-- ===== 20261102000058_calendar_feeds.sql =====
-- Calendar subscriptions: each person gets one private link that Google Calendar, Outlook, Yahoo
-- and Apple Calendar subscribe to, and that keeps itself up to date (a moved or cancelled game
-- changes there too). The calendar-feed Edge Function turns calendar_feed_events() into the
-- standard calendar format; the link is the only key, so a new link turns the old one off.
--
-- What's in it, for the person the link belongs to:
--   - the school calendar (everyone);
--   - their own events and the activity items they plan to go to (teachers and staff, My calendar);
--   - the activities of their children, or their own as a student (registered seasons).
-- Names stay in the app: the feed carries what, when and where, never a student's name.

create table public.calendar_feeds (
  user_id      uuid primary key references public.profiles (id) on delete cascade,
  token        text not null unique check (token ~ '^[0-9a-f]{64}$'),
  created_at   timestamptz not null default now(),
  last_used_at timestamptz
);
alter table public.calendar_feeds enable row level security;
create policy "your own link" on public.calendar_feeds for select to authenticated using (user_id = auth.uid());
grant select on public.calendar_feeds to authenticated;
revoke insert, update, delete on public.calendar_feeds from anon, authenticated;
grant all on public.calendar_feeds to service_role;

create function app.new_feed_token() returns text
language sql volatile as $$
  select replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '')
$$;

/** Your calendar link's key (made the first time); `p_new` makes a new one, which turns the old link off. */
create function public.calendar_feed_token(p_new boolean default false) returns text
language plpgsql security definer set search_path = public as $$
declare t text;
begin
  if app.school_role() is null then raise exception 'Sign in with an approved account first.' using errcode = '42501'; end if;
  if p_new then
    insert into calendar_feeds (user_id, token) values (auth.uid(), app.new_feed_token())
    on conflict (user_id) do update set token = excluded.token, created_at = now(), last_used_at = null
    returning token into t;
  else
    insert into calendar_feeds (user_id, token) values (auth.uid(), app.new_feed_token()) on conflict (user_id) do nothing;
    select token into t from calendar_feeds where user_id = auth.uid();
  end if;
  return t;
end $$;

/**
 * The events behind a calendar link, from 60 days ago to a year ahead. Times are exact moments;
 * all-day events have dates instead (`end_date` is the last day). No student names.
 */
create function public.calendar_feed_events(p_token text)
returns table (uid text, title text, starts_at timestamptz, ends_at timestamptz, start_date date, end_date date,
               location text, details text, cancelled boolean, updated_at timestamptz)
language plpgsql security definer set search_path = public as $$
declare u uuid; tz constant text := 'America/Chicago'; since date := app.school_today() - 60; until date := app.school_today() + 366;
begin
  update calendar_feeds set last_used_at = now() where token = p_token returning user_id into u;
  if u is null or app.school_role(u) is null then return; end if;   -- a link turned off, or an account no longer approved

  return query
  -- The school calendar.
  select 'school-' || e.id, e.title,
         case when e.all_day or e.start_time is null then null else (e.starts_on + e.start_time) at time zone tz end,
         case when e.all_day or e.start_time is null or e.end_time is null then null
              else (coalesce(e.ends_on, e.starts_on) + e.end_time) at time zone tz end,
         case when e.all_day or e.start_time is null then e.starts_on end,
         case when e.all_day or e.start_time is null then coalesce(e.ends_on, e.starts_on) end,
         e.location, e.category, false, e.created_at
  from events e
  where e.group_id is null and coalesce(e.ends_on, e.starts_on) >= since and e.starts_on <= until

  union all
  -- My calendar: their own events (teachers and staff).
  select 'mine-' || pe.id, pe.title,
         case when pe.start_time is null then null else (pe.starts_on + pe.start_time) at time zone tz end,
         case when pe.end_time is null then null else (pe.starts_on + pe.end_time) at time zone tz end,
         case when pe.start_time is null then pe.starts_on end,
         case when pe.start_time is null then pe.starts_on end,
         pe.location, nullif(pe.notes, ''), false, pe.updated_at
  from personal_events pe
  where pe.owner_id = u and pe.sport_event_id is null and app.is_staff(u) and pe.starts_on between since and until

  union all
  -- Activity items: the ones they plan to go to (staff), and their children's or their own (registered).
  select 'activity-' || e.id, app.sport_label(se.sport_id) || ' · ' || e.title,
         e.starts_at, coalesce(e.ends_at, e.starts_at + interval '2 hours'), null::date, null::date,
         concat_ws(', ', nullif(e.location, ''), nullif(e.address, '')), nullif(e.notes, ''), e.cancelled, e.updated_at
  from sport_events e
  join sport_seasons se on se.id = e.season_id
  where (e.starts_at at time zone tz)::date between since and until
    and (exists (select 1 from personal_events pe where pe.owner_id = u and pe.sport_event_id = e.id and app.is_staff(u))
         or exists (select 1 from sport_registrations r where r.season_id = e.season_id and r.status = 'registered'
                    and r.student_id in (select app.my_students(u))));
end $$;

revoke all on function public.calendar_feed_token(boolean), public.calendar_feed_events(text) from public, anon;
grant execute on function public.calendar_feed_token(boolean) to authenticated, service_role;
-- The link works without signing in: calendar apps can't sign in. The key in it is the only way in.
grant execute on function public.calendar_feed_events(text) to anon, authenticated, service_role;

/** The app's name, for naming the subscribed calendar ("KH Royals"). Public. */
create function public.school_app_name() returns text
language sql stable security definer set search_path = app as $$ select app.brand('app_name') $$;
grant execute on function public.school_app_name() to anon, authenticated, service_role;

/**
 * One school-calendar or activity event, for "Add to calendar" ('school-<id>' or 'activity-<id>').
 * Both are public already (anyone can read the school calendar and activity schedules).
 */
create function public.calendar_event(p_uid text)
returns table (uid text, title text, starts_at timestamptz, ends_at timestamptz, start_date date, end_date date,
               location text, details text, cancelled boolean, updated_at timestamptz)
language sql stable security definer set search_path = public as $$
  select 'school-' || e.id, e.title,
         case when e.all_day or e.start_time is null then null else (e.starts_on + e.start_time) at time zone 'America/Chicago' end,
         case when e.all_day or e.start_time is null or e.end_time is null then null
              else (coalesce(e.ends_on, e.starts_on) + e.end_time) at time zone 'America/Chicago' end,
         case when e.all_day or e.start_time is null then e.starts_on end,
         case when e.all_day or e.start_time is null then coalesce(e.ends_on, e.starts_on) end,
         e.location, e.category, false, e.created_at
  from events e where p_uid = 'school-' || e.id and e.group_id is null
  union all
  select 'activity-' || e.id, app.sport_label(se.sport_id) || ' · ' || e.title, e.starts_at, coalesce(e.ends_at, e.starts_at + interval '2 hours'),
         null::date, null::date, concat_ws(', ', nullif(e.location, ''), nullif(e.address, '')), nullif(e.notes, ''), e.cancelled, e.updated_at
  from sport_events e join sport_seasons se on se.id = e.season_id where p_uid = 'activity-' || e.id
$$;
grant execute on function public.calendar_event(text) to anon, authenticated, service_role;

insert into app.applied_migrations (name) values ('20261102000058_calendar_feeds.sql') on conflict do nothing;

-- ===== 20261102000059_newsletter_write.sql =====
-- Newsletter issues written in the app, not only imported from Smore: whoever can add an issue
-- (push.send) pastes or types it (the app shapes it into the same blocks, src/news/compose.ts),
-- and can change or delete it later. A written issue has no Smore page: its source_url is
-- 'app:<its id>', and the app shows no "Open the original" link for it.

alter table public.newsletters drop constraint newsletters_source_url_check;
alter table public.newsletters add constraint newsletters_source_url_check
  check (source_url ~ '^https://app\.smore\.com/n/' or source_url ~ '^app:[0-9a-f-]{36}$');

/** push.send: add an issue written in the app (no `p_id`), or change one. Returns its id. */
create function public.newsletter_write(p_id uuid, p_title text, p_sent_on date, p_blocks jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare nid uuid := coalesce(p_id, gen_random_uuid());
begin
  perform app.require_permission('push.send');
  if coalesce(trim(p_title), '') = '' then raise exception 'Give the issue a title.'; end if;
  if char_length(trim(p_title)) > 120 then raise exception 'Keep the title to 120 characters.'; end if;
  if p_sent_on is null then raise exception 'The issue needs its date.'; end if;
  if p_blocks is null or jsonb_typeof(p_blocks) <> 'array' or jsonb_array_length(p_blocks) = 0 then
    raise exception 'Write something in the issue first.';
  end if;
  if length(p_blocks::text) > 300000 then raise exception 'That issue is too long to add.'; end if;
  if exists (select 1 from jsonb_array_elements(p_blocks) b where b->>'kind' not in ('heading', 'text', 'image')) then
    raise exception 'That issue has something the app can''t show.';
  end if;
  if p_id is not null and not exists (select 1 from newsletters where id = p_id and source_url = 'app:' || p_id) then
    raise exception 'Only issues written in the app can be changed here.';
  end if;
  insert into newsletters (id, title, sent_on, source_url, blocks, created_by)
  values (nid, trim(p_title), p_sent_on, 'app:' || nid, p_blocks, auth.uid())
  on conflict (id) do update set title = excluded.title, sent_on = excluded.sent_on, blocks = excluded.blocks;
  perform app.audit(null, 'newsletter.saved', nid::text, jsonb_build_object('sentOn', p_sent_on, 'written', true));
  return nid;
end $$;

revoke all on function public.newsletter_write(uuid, text, date, jsonb) from public, anon;
grant execute on function public.newsletter_write(uuid, text, date, jsonb) to authenticated, service_role;

insert into app.applied_migrations (name) values ('20261102000059_newsletter_write.sql') on conflict do nothing;

-- ===== 20261102000060_absence_reports.sql =====
-- Report an absence: a child's parent tells the school, from the app, that the child is out
-- (for a day or several), will be late, or leaves early, and why. The office (checkin.manage)
-- and the teachers of the child's class sections are told, and see it on the day's list and
-- on the class roll; the office marks it seen, and the parents hear back. Parents change their
-- mind with Cancel. Only parents (guardians, never Family accounts) report; dates from today on.
-- Reasons are listed in both src/absences/labels.ts and the check below.

create table public.absence_reports (
  id          uuid primary key default gen_random_uuid(),
  student_id  uuid not null references public.profiles (id) on delete cascade,
  kind        text not null check (kind in ('absent', 'late', 'early')),
  starts_on   date not null,
  ends_on     date not null,
  at_time     time,            -- late: when they'll arrive; early: when they'll be picked up
  reason      text not null check (reason in ('sick', 'appointment', 'family', 'travel', 'other')),
  note        text not null default '' check (char_length(note) <= 500),
  reported_by uuid references public.profiles (id) on delete set null,
  status      text not null default 'reported' check (status in ('reported', 'cancelled')),
  seen_by     uuid references public.profiles (id) on delete set null,
  seen_at     timestamptz,
  created_at  timestamptz not null default now(),
  check (ends_on >= starts_on),
  check (kind = 'absent' or (ends_on = starts_on and at_time is not null))
);
create index on public.absence_reports (starts_on, ends_on);
create index on public.absence_reports (student_id, starts_on);

/** The office: who sees every report and marks it seen. */
create function app.office_team() returns setof uuid
language sql stable security definer set search_path = public as $$
  select id from profiles
  where school_role is not null and (admin_tier is not null or cardinality(permissions) > 0)
    and 'checkin.manage' = any (app.permissions(id))
$$;

/** Who reads a child's reports: their parents, the teachers of their sections, and the office. */
create function app.reads_absences(s uuid, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.is_guardian_of(s, u) or app.teaches(u, s) or app.has_permission('checkin.manage', u)
$$;

alter table public.absence_reports enable row level security;
create policy "the child's parents, teachers and the office" on public.absence_reports for select to authenticated
  using (app.reads_absences(student_id));
grant select on public.absence_reports to authenticated;
revoke insert, update, delete on public.absence_reports from anon, authenticated;
grant all on public.absence_reports to service_role;

create function app.absence_line(r public.absence_reports) returns text
language sql stable security definer set search_path = public as $$
  select trim((select first_name from profiles where id = r.student_id)) || ' · '
    || case r.kind when 'absent' then 'absent' when 'late' then 'arriving late' else 'leaving early' end
    || ' ' || case when r.ends_on > r.starts_on then to_char(r.starts_on, 'Dy Mon FMDD') || '–' || to_char(r.ends_on, 'Dy Mon FMDD')
                   when r.starts_on = app.school_today() then 'today'
                   when r.starts_on = app.school_today() + 1 then 'tomorrow'
                   else to_char(r.starts_on, 'Dy Mon FMDD') end
    || coalesce(case r.kind when 'late' then ', at ' when 'early' then ', at ' end || to_char(r.at_time, 'FMHH12:MI AM'), '')
    || ' (' || case r.reason when 'sick' then 'sick' when 'appointment' then 'appointment' when 'family' then 'family'
                             when 'travel' then 'travel' else 'other' end || ')'
$$;

/** A parent reports an absence, a late arrival or an early pickup. The office and the child's teachers are told. */
create function public.absence_report(p_student uuid, p_kind text, p_starts_on date, p_ends_on date default null,
  p_at time default null, p_reason text default 'sick', p_note text default '') returns public.absence_reports
language plpgsql security definer set search_path = public as $$
declare r absence_reports%rowtype; u uuid; line text;
begin
  if not app.is_guardian_of(p_student) or app.is_family() then
    raise exception 'Only a child''s parents report an absence.' using errcode = '42501';
  end if;
  if p_kind is null or p_kind not in ('absent', 'late', 'early') then raise exception 'Choose absent, late or leaving early.'; end if;
  if p_reason is null or p_reason not in ('sick', 'appointment', 'family', 'travel', 'other') then raise exception 'Choose a reason.'; end if;
  if p_starts_on is null or p_starts_on < app.school_today() then raise exception 'Pick today or a day ahead.'; end if;
  if p_starts_on > app.school_today() + 90 then raise exception 'Report up to 90 days ahead.'; end if;
  if p_kind <> 'absent' and p_at is null then raise exception 'What time?'; end if;
  if coalesce(p_ends_on, p_starts_on) < p_starts_on then raise exception 'The last day can''t be before the first.'; end if;
  if coalesce(p_ends_on, p_starts_on) > p_starts_on + 30 then raise exception 'Report up to 30 days at once.'; end if;
  if char_length(coalesce(p_note, '')) > 500 then raise exception 'Keep the note to 500 characters.'; end if;
  insert into absence_reports (student_id, kind, starts_on, ends_on, at_time, reason, note, reported_by)
  values (p_student, p_kind, p_starts_on, case when p_kind = 'absent' then coalesce(p_ends_on, p_starts_on) else p_starts_on end,
          case when p_kind = 'absent' then null else p_at end, p_reason, trim(coalesce(p_note, '')), auth.uid())
  returning * into r;
  line := app.absence_line(r);
  for u in select app.office_team() union select app.teachers_of(p_student) loop
    if u <> auth.uid() then
      perform app.notify_user(u, '📝 ' || line, coalesce(nullif(r.note, ''), 'Reported by ' || app.checkin_name(auth.uid())),
        jsonb_build_object('absenceId', r.id));
    end if;
  end loop;
  return r;
end $$;

/** The parent who reported (or the child's other parent) calls it off; the office and teachers are told. */
create function public.absence_cancel(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare r absence_reports%rowtype; u uuid;
begin
  select * into r from absence_reports where id = p_id;
  if not found or not app.is_guardian_of(r.student_id) or app.is_family() then raise exception 'That report isn''t yours to change.' using errcode = '42501'; end if;
  if r.status = 'cancelled' then return; end if;
  update absence_reports set status = 'cancelled' where id = p_id;
  for u in select app.office_team() union select app.teachers_of(r.student_id) loop
    if u <> auth.uid() then
      perform app.notify_user(u, '↩️ Called off: ' || app.absence_line(r), 'Reported by mistake, or plans changed.', jsonb_build_object('absenceId', r.id));
    end if;
  end loop;
end $$;

/** The office marks a report seen; the parents hear the school has it. */
create function public.absence_seen(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare r absence_reports%rowtype;
begin
  perform app.require_permission('checkin.manage');
  update absence_reports set seen_by = auth.uid(), seen_at = now() where id = p_id and seen_at is null returning * into r;
  if not found then return; end if;
  perform app.notify_parents(r.student_id, '✅ The office got it', app.absence_line(r), jsonb_build_object('absenceId', r.id));
end $$;

/**
 * Reports the caller may see covering a day (or from it for `p_days`): the office sees all; teachers
 * their students'; parents their children's. Newest days first within each day by child name.
 */
create function public.absence_list(p_from date default null, p_days int default 1)
returns table (id uuid, student_id uuid, student text, grade int, kind text, starts_on date, ends_on date, at_time text,
               reason text, note text, status text, reported_by text, created_at timestamptz, seen_by text, seen_at timestamptz, classes text)
language sql stable security definer set search_path = public as $$
  select r.id, r.student_id, trim(p.first_name || ' ' || p.last_name), p.grade, r.kind, r.starts_on, r.ends_on, to_char(r.at_time, 'HH24:MI'),
         r.reason, r.note, r.status, app.checkin_name(r.reported_by), r.created_at,
         case when r.seen_by is not null then app.checkin_name(r.seen_by) end, r.seen_at,
         (select string_agg(ro.name, ', ' order by ro.name) from rosters ro join roster_members m on m.roster_id = ro.id
           where ro.kind = 'section' and m.profile_id = r.student_id)
  from absence_reports r join profiles p on p.id = r.student_id
  where app.reads_absences(r.student_id)
    and r.ends_on >= coalesce(p_from, app.school_today())
    and r.starts_on <= coalesce(p_from, app.school_today()) + greatest(coalesce(p_days, 1), 1) - 1
  order by r.starts_on, p.last_name, p.first_name, r.created_at
$$;

revoke all on function public.absence_report(uuid, text, date, date, time, text, text), public.absence_cancel(uuid),
  public.absence_seen(uuid), public.absence_list(date, int) from public, anon;
grant execute on function public.absence_report(uuid, text, date, date, time, text, text), public.absence_cancel(uuid),
  public.absence_seen(uuid), public.absence_list(date, int) to authenticated, service_role;

-- The class roll shows what the parents reported for the day.
create or replace function public.class_attendance_roll(p_section text, p_day date default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare d date := coalesce(p_day, app.school_today());
begin
  if not app.takes_roll(p_section) then
    raise exception 'Only the class''s teacher and the office can see its attendance.' using errcode = '42501';
  end if;
  if not app.keeps_roll(p_section) and d <> app.school_today() then raise exception 'Substitutes see today''s roll only.'; end if;
  return (select jsonb_build_object('id', r.id, 'name', r.name, 'teacher', case when r.lead_id is not null then app.checkin_name(r.lead_id) end,
      'day', d, 'canMark', d between app.school_today() - 14 and app.school_today(), 'otherDays', app.keeps_roll(r.id),
      'students', coalesce((select jsonb_agg(jsonb_build_object(
          'id', p.id, 'name', trim(p.first_name || ' ' || p.last_name), 'grade', p.grade,
          'mark', a.status, 'markedBy', case when a.marked_by is not null then app.checkin_name(a.marked_by) end,
          'state', app.attendance_state(r.id, p.id, d), 'left', app.left_school(p.id, d),
          'reported', (select jsonb_build_object('kind', ar.kind, 'reason', ar.reason, 'at', to_char(ar.at_time, 'HH24:MI'), 'note', ar.note,
              'by', app.checkin_name(ar.reported_by))
            from absence_reports ar where ar.student_id = p.id and ar.status = 'reported' and d between ar.starts_on and ar.ends_on
            order by ar.created_at desc limit 1),
          'checks', coalesce((select jsonb_agg(jsonb_build_object('kind', c.kind, 'at', c.at, 'reason', c.reason,
              'person', case when c.person_id is not null then app.checkin_name(c.person_id) end) order by c.at)
            from school_checks c where c.student_id = p.id and c.day = d), '[]'::jsonb))
          order by p.last_name, p.first_name)
        from app.section_students(r.id) s join profiles p on p.id = s
        left join class_attendance a on a.section_id = r.id and a.student_id = p.id and a.day = d), '[]'::jsonb))
    from rosters r where r.id = p_section);
end $$;

insert into app.applied_migrations (name) values ('20261102000060_absence_reports.sql') on conflict do nothing;

-- ===== 20261102000061_lunch_visits.sql =====
-- Lunch visits: parents and approved family (grandparents too) ask to come eat lunch with their
-- child. The office (lunch.manage: directors, administrators, office) sets when visits are open:
-- lunch windows by weekday, time and grades, each with how many visitors it takes a day, plus
-- closed days and the lunch rules. A visit is booked if there's room on a day the school is open;
-- before booking, the visitor reads the allergy notes for that lunch (the child's own, and the
-- allergies in those grades, never with names) and the rules, and says so. Teachers and staff see
-- the day's visitors with each child's allergies; the child's teachers are told when one is booked.

create or replace function public.permission_catalog() returns table (key text, label text, description text)
language sql immutable as $$
  values
    ('admins.manage',    'Manage admins',         'Make or remove admins, set tiers and grant permissions (director only).'),
    ('people.view',      'View people',           'See everyone''s contact email in the admin portal.'),
    ('people.approve',   'Approve sign-ups',      'Approve new accounts as parents, students or family.'),
    ('people.roles',     'Change roles',          'Set anyone''s school role, including teachers, staff and substitutes.'),
    ('people.family',    'Families & rosters',    'Link parents and family to students, set grades, manage classes, class/team rosters and car line duty.'),
    ('groups.manage',    'Manage all groups',     'Act as owner of every group: settings, members, moderation.'),
    ('calendar.school',  'School calendar',       'Add, change and remove school-wide calendar events.'),
    ('push.send',        'Send notifications',    'Send push notifications to everyone, a role or any group.'),
    ('checkin.manage',   'Check in & out',        'Check students in when they arrive late and out when they leave early (only to someone on their pickup list), see the day''s check-ins, and run any event check-out list.'),
    ('lunch.manage',     'Lunch visits',          'Set when families may come eat lunch with their children (days, times, grades, how many), close days, write the lunch rules, and cancel a visit.'),
    ('subs.manage',      'Schedule substitutes',  'Schedule a substitute for any class, with the days, hours and sub plans, and change or cancel any sub day.'),
    ('alerts.map',       'Alert map',             'Keep the map of the school''s Wi-Fi access points (which room or area each one is in) that shows critical alert senders where people answered from.'),
    ('alerts.send',      'Send critical alerts',  'Send critical alerts (severe weather, an active threat, a dangerous situation) to every teacher and staff member, see who''s safe, and give the all clear.'),
    ('questions.manage', 'Route questions',       'See every question sent to the school, assign it to faculty or staff, and answer it.'),
    ('messages.review',  'Student messages',      'Read every Ask the Teacher conversation between students and teachers, for safety.'),
    ('sports.manage',    'Manage activities',     'Add activities (sports, theater, music, art, clubs) and seasons, set schedules, assign coaches and directors, and approve sign-ups.'),
    ('forms.send',       'Send forms',            'Send forms (permission slips, releases, acknowledgments) to any class, activity, grade or the whole school, and see every form''s signatures.'),
    ('people.delete',    'Delete accounts',       'Permanently delete someone''s account, with their posts and comments. Deleting an admin also needs Manage admins.'),
    ('gallery.manage',   'Manage photo gallery',  'Change or remove any photo album or photo, not just your own.'),
    ('feedback.triage',  'Triage feedback',       'See every bug report and feature request sent from the app, set its status and priority, reply, and plan student workshops from them.'),
    ('audit.view',       'Activity log',          'Review the school-wide activity log.')
$$;

update public.admin_roles set permissions = permissions || 'lunch.manage'::text
where id in ('director', 'administrator', 'office') and not ('lunch.manage' = any (permissions));

insert into app.settings values ('lunch_rules',
  'Check in at the front office when you arrive, with your ID. Bring lunch for your child and you only, and please no nuts: some students have serious food allergies. Visits are about 30 minutes.')
on conflict (key) do nothing;

create table public.lunch_windows (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (char_length(trim(name)) between 1 and 60),   -- "K–2nd lunch"
  weekdays   int[] not null check (cardinality(weekdays) between 1 and 5 and weekdays <@ array[1, 2, 3, 4, 5]),  -- 1 Monday … 5 Friday
  start_time time not null,
  end_time   time not null check (end_time > start_time),
  grade_from int not null check (grade_from between -3 and 12),
  grade_to   int not null check (grade_to between -3 and 12),
  capacity   int not null check (capacity between 1 and 200),   -- visitors a day, guests included
  active     boolean not null default true,
  created_at timestamptz not null default now(),
  check (grade_to >= grade_from)
);

create table public.lunch_closed_days (
  day    date primary key,
  reason text not null default '' check (char_length(reason) <= 120)
);

create table public.lunch_visits (
  id             uuid primary key default gen_random_uuid(),
  window_id      uuid not null references public.lunch_windows (id) on delete cascade,
  day            date not null,
  student_id     uuid not null references public.profiles (id) on delete cascade,
  visitor_id     uuid not null references public.profiles (id) on delete cascade,
  guests         int not null default 0 check (guests between 0 and 3),
  note           text not null default '' check (char_length(note) <= 300),
  allergy_ack_at timestamptz not null,
  status         text not null default 'booked' check (status in ('booked', 'cancelled')),
  cancelled_by   uuid references public.profiles (id) on delete set null,
  cancel_reason  text not null default '' check (char_length(cancel_reason) <= 200),
  created_at     timestamptz not null default now()
);
create unique index lunch_one_visit on public.lunch_visits (window_id, day, student_id, visitor_id) where status = 'booked';
create index on public.lunch_visits (day);

/** The children someone may visit at lunch: their own (parents) and the ones the office linked (family). */
create function app.lunch_kids(u uuid default auth.uid()) returns setof uuid
language sql stable security definer set search_path = public as $$
  select student_id from guardians where guardian_id = u and app.school_role(u) is not null
  union
  select student_id from family_pickups where family_id = u and app.school_role(u) is not null
$$;

/** No visits that day: a closed day, a weekend, or no school on the school calendar. */
create function app.lunch_closed(d date) returns boolean
language sql stable security definer set search_path = public as $$
  select extract(isodow from d) > 5
      or exists (select 1 from lunch_closed_days where day = d)
      or exists (select 1 from events where group_id is null and category in ('No School', 'Teacher In-Service', 'E-Learning')
                 and d between starts_on and coalesce(ends_on, starts_on))
$$;

/** Visitors already booked for a window on a day (each visit counts its visitor and guests). */
create function app.lunch_taken(w uuid, d date) returns int
language sql stable security definer set search_path = public as $$
  select coalesce(sum(1 + guests), 0)::int from lunch_visits where window_id = w and day = d and status = 'booked'
$$;

alter table public.lunch_windows enable row level security;
alter table public.lunch_closed_days enable row level security;
alter table public.lunch_visits enable row level security;
create policy "approved accounts" on public.lunch_windows for select to authenticated using (app.school_role() is not null);
create policy "approved accounts" on public.lunch_closed_days for select to authenticated using (app.school_role() is not null);
create policy "the visitor, staff, and the child's parents" on public.lunch_visits for select to authenticated
  using (visitor_id = auth.uid() or app.is_staff() or app.is_guardian_of(student_id));
grant select on public.lunch_windows, public.lunch_closed_days, public.lunch_visits to authenticated;
revoke insert, update, delete on public.lunch_windows, public.lunch_closed_days, public.lunch_visits from anon, authenticated;
grant all on public.lunch_windows, public.lunch_closed_days, public.lunch_visits to service_role;

-- ----------------------------------------------------------------------
-- The office sets it up
-- ----------------------------------------------------------------------

create function public.lunch_window_save(p_id uuid, p_name text, p_weekdays int[], p_start time, p_end time,
  p_grade_from int, p_grade_to int, p_capacity int, p_active boolean default true) returns public.lunch_windows
language plpgsql security definer set search_path = public as $$
declare row lunch_windows%rowtype;
begin
  perform app.require_permission('lunch.manage');
  if coalesce(trim(p_name), '') = '' then raise exception 'Name the lunch, like "K–2nd lunch".'; end if;
  if p_weekdays is null or cardinality(p_weekdays) = 0 or not (p_weekdays <@ array[1, 2, 3, 4, 5]) then raise exception 'Pick the weekdays.'; end if;
  if p_start is null or p_end is null or p_end <= p_start then raise exception 'The lunch ends after it starts.'; end if;
  if p_grade_from is null or p_grade_to is null or p_grade_to < p_grade_from then raise exception 'Pick the grades.'; end if;
  if p_capacity is null or p_capacity not between 1 and 200 then raise exception 'How many visitors a day (1–200)?'; end if;
  if p_id is null then
    insert into lunch_windows (name, weekdays, start_time, end_time, grade_from, grade_to, capacity, active)
    values (trim(p_name), (select array_agg(distinct x order by x) from unnest(p_weekdays) x), p_start, p_end, p_grade_from, p_grade_to, p_capacity, coalesce(p_active, true))
    returning * into row;
  else
    update lunch_windows set name = trim(p_name), weekdays = (select array_agg(distinct x order by x) from unnest(p_weekdays) x),
      start_time = p_start, end_time = p_end, grade_from = p_grade_from, grade_to = p_grade_to, capacity = p_capacity, active = coalesce(p_active, true)
    where id = p_id returning * into row;
    if not found then raise exception 'That lunch is gone.'; end if;
  end if;
  return row;
end $$;

/** Remove a lunch window; visits already booked in it are cancelled and their visitors told. */
create function public.lunch_window_delete(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v record;
begin
  perform app.require_permission('lunch.manage');
  for v in select lv.id from lunch_visits lv where lv.window_id = p_id and lv.status = 'booked' and lv.day >= app.school_today() loop
    perform public.lunch_visit_cancel(v.id, 'That lunch time is no longer offered.');
  end loop;
  delete from lunch_windows where id = p_id;
end $$;

/** Close a day to visits (or open it again, `p_closed` false); visits that day are cancelled and their visitors told. */
create function public.lunch_close_day(p_day date, p_closed boolean, p_reason text default '') returns void
language plpgsql security definer set search_path = public as $$
declare v record;
begin
  perform app.require_permission('lunch.manage');
  if not p_closed then delete from lunch_closed_days where day = p_day; return; end if;
  insert into lunch_closed_days (day, reason) values (p_day, left(trim(coalesce(p_reason, '')), 120))
  on conflict (day) do update set reason = excluded.reason;
  for v in select id from lunch_visits where day = p_day and status = 'booked' loop
    perform public.lunch_visit_cancel(v.id, coalesce(nullif(trim(p_reason), ''), 'Lunch visits are closed that day.'));
  end loop;
end $$;

create function public.lunch_set_rules(p_rules text) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform app.require_permission('lunch.manage');
  if char_length(coalesce(p_rules, '')) > 2000 then raise exception 'Keep the rules to 2000 characters.'; end if;
  update app.settings set value = trim(coalesce(p_rules, '')) where key = 'lunch_rules';
end $$;

/** The lunch rules everyone reads before booking. */
create function public.lunch_rules() returns text
language sql stable security definer set search_path = public as $$ select coalesce(app.setting('lunch_rules'), '') $$;

-- ----------------------------------------------------------------------
-- Families book
-- ----------------------------------------------------------------------

/**
 * Open lunch times for one of the caller's children, from `p_from` for `p_days` days: each day and
 * window for the child's grade, with spots left and the caller's visit if they have one.
 */
create function public.lunch_slots(p_student uuid, p_from date default null, p_days int default 21)
returns table (day date, window_id uuid, name text, start_time text, end_time text, spots_left int, my_visit uuid)
language sql stable security definer set search_path = public as $$
  select d::date, w.id, w.name, to_char(w.start_time, 'HH24:MI'), to_char(w.end_time, 'HH24:MI'),
         greatest(w.capacity - app.lunch_taken(w.id, d::date), 0),
         (select v.id from lunch_visits v where v.window_id = w.id and v.day = d::date and v.student_id = p_student
            and v.visitor_id = auth.uid() and v.status = 'booked')
  from generate_series(coalesce(p_from, app.school_today()), coalesce(p_from, app.school_today()) + least(greatest(coalesce(p_days, 21), 1), 60) - 1, interval '1 day') d
  join lunch_windows w on w.active and extract(isodow from d)::int = any (w.weekdays)
  join profiles p on p.id = p_student and p.grade between w.grade_from and w.grade_to
  where p_student in (select app.lunch_kids()) and not app.lunch_closed(d::date)
    and (d::date > app.school_today() or (d::date = app.school_today() and (now() at time zone 'America/Chicago')::time < w.start_time))
  order by 1, w.start_time
$$;

/**
 * What a visitor must know about allergies before a lunch: the child's own (parents only; it's
 * their child's record) and the allergies among students in that lunch's grades, without names.
 */
create function public.lunch_allergy_notes(p_window uuid, p_student uuid)
returns table (own text, others text[])
language sql stable security definer set search_path = public as $$
  select case when app.is_guardian_of(p_student) or app.is_staff() then nullif(trim((select allergies from student_details where student_id = p_student)), '') end,
         coalesce((select array_agg(distinct trim(d.allergies) order by trim(d.allergies))
           from student_details d join profiles p on p.id = d.student_id join lunch_windows w on w.id = p_window
           where p.school_role = 'student' and p.grade between w.grade_from and w.grade_to and trim(d.allergies) <> ''), '{}')
  where p_student in (select app.lunch_kids()) or app.is_staff()
$$;

/** Book a lunch visit (visitor plus up to 3 guests) after reading the allergy notes and rules (`p_read_allergies`). */
create function public.lunch_visit_book(p_window uuid, p_day date, p_student uuid, p_guests int default 0, p_note text default '',
  p_read_allergies boolean default false) returns public.lunch_visits
language plpgsql security definer set search_path = public as $$
declare w lunch_windows%rowtype; g int; r lunch_visits%rowtype; t uuid; kid text;
begin
  if p_student is null or p_student not in (select app.lunch_kids()) then
    raise exception 'Only a child''s parents and the family the school linked can visit at lunch.' using errcode = '42501';
  end if;
  if not coalesce(p_read_allergies, false) then raise exception 'Read the allergy notes and lunch rules first.'; end if;
  select * into w from lunch_windows where id = p_window and active for share;
  if not found then raise exception 'That lunch time isn''t offered.'; end if;
  select grade into g from profiles where id = p_student;
  if g is null or g not between w.grade_from and w.grade_to then raise exception 'That lunch isn''t for this child''s grade.'; end if;
  if p_day is null or p_day < app.school_today() or p_day > app.school_today() + 60 then raise exception 'Pick a day in the next two months.'; end if;
  if not (extract(isodow from p_day)::int = any (w.weekdays)) or app.lunch_closed(p_day) then raise exception 'Lunch visits aren''t open that day.'; end if;
  if p_day = app.school_today() and (now() at time zone 'America/Chicago')::time >= w.start_time then raise exception 'That lunch has already started.'; end if;
  if coalesce(p_guests, 0) not between 0 and 3 then raise exception 'Bring up to 3 guests.'; end if;
  if char_length(coalesce(p_note, '')) > 300 then raise exception 'Keep the note to 300 characters.'; end if;
  if exists (select 1 from lunch_visits where window_id = w.id and day = p_day and student_id = p_student and visitor_id = auth.uid() and status = 'booked') then
    raise exception 'You''re already coming that day.';
  end if;
  if app.lunch_taken(w.id, p_day) + 1 + coalesce(p_guests, 0) > w.capacity then raise exception 'That lunch is full. Try another day.'; end if;
  insert into lunch_visits (window_id, day, student_id, visitor_id, guests, note, allergy_ack_at)
  values (w.id, p_day, p_student, auth.uid(), coalesce(p_guests, 0), trim(coalesce(p_note, '')), now())
  returning * into r;
  select first_name into kid from profiles where id = p_student;
  for t in select app.teachers_of(p_student) loop
    perform app.notify_user(t, '🍎 ' || app.short_name(auth.uid()) || ' is coming to lunch with ' || kid,
      to_char(p_day, 'Dy Mon FMDD') || ', ' || w.name || ' (' || to_char(w.start_time, 'FMHH12:MI') || ')'
        || case when r.guests > 0 then ', with ' || r.guests || ' guest' || case when r.guests > 1 then 's' else '' end else '' end,
      jsonb_build_object('lunchVisitId', r.id));
  end loop;
  return r;
end $$;

/** The visitor calls it off, or lunch.manage cancels it with a reason (the visitor is told). */
create function public.lunch_visit_cancel(p_id uuid, p_reason text default '') returns void
language plpgsql security definer set search_path = public as $$
declare v lunch_visits%rowtype; w lunch_windows%rowtype; mine boolean; t uuid;
begin
  select * into v from lunch_visits where id = p_id;
  if not found or v.status = 'cancelled' then return; end if;
  mine := v.visitor_id = auth.uid();
  if not mine then perform app.require_permission('lunch.manage'); end if;
  update lunch_visits set status = 'cancelled', cancelled_by = auth.uid(), cancel_reason = left(trim(coalesce(p_reason, '')), 200) where id = p_id;
  select * into w from lunch_windows where id = v.window_id;
  if not mine then
    perform app.notify_user(v.visitor_id, '🍎 Lunch visit cancelled',
      to_char(v.day, 'Dy Mon FMDD') || ', ' || w.name || coalesce(': ' || nullif(trim(p_reason), ''), ''), jsonb_build_object('lunchVisitId', v.id));
  else
    for t in select app.teachers_of(v.student_id) loop
      perform app.notify_user(t, '🍎 Lunch visit called off', app.short_name(auth.uid()) || ' isn''t coming ' || to_char(v.day, 'Dy Mon FMDD') || ' after all.',
        jsonb_build_object('lunchVisitId', v.id));
    end loop;
  end if;
end $$;

-- ----------------------------------------------------------------------
-- Who's coming
-- ----------------------------------------------------------------------

/** Teachers and staff: the day's visitors, by lunch, with each child's allergies. */
create function public.lunch_visitors(p_day date default null)
returns table (id uuid, window_name text, start_time text, end_time text, visitor text, relation text, student text, grade int,
               classes text, guests int, note text, allergies text, status text, cancel_reason text, booked_at timestamptz)
language sql stable security definer set search_path = public as $$
  select v.id, w.name, to_char(w.start_time, 'HH24:MI'), to_char(w.end_time, 'HH24:MI'), app.checkin_name(v.visitor_id),
         case when exists (select 1 from guardians g where g.guardian_id = v.visitor_id and g.student_id = v.student_id)
              then coalesce((select relation from guardians g where g.guardian_id = v.visitor_id and g.student_id = v.student_id), 'parent')
              else 'family' end,
         trim(p.first_name || ' ' || p.last_name), p.grade,
         (select string_agg(ro.name, ', ' order by ro.name) from rosters ro join roster_members m on m.roster_id = ro.id
           where ro.kind = 'section' and m.profile_id = v.student_id),
         v.guests, v.note, nullif(trim((select allergies from student_details where student_id = v.student_id)), ''),
         v.status, v.cancel_reason, v.created_at
  from lunch_visits v join lunch_windows w on w.id = v.window_id join profiles p on p.id = v.student_id
  where app.is_staff() and v.day = coalesce(p_day, app.school_today())
  order by w.start_time, v.status, p.last_name, p.first_name
$$;

/** The caller's own visits from today on (and their children's, booked by family). */
create function public.my_lunch_visits()
returns table (id uuid, day date, window_name text, start_time text, end_time text, student text, visitor text, guests int,
               note text, status text, cancel_reason text, mine boolean)
language sql stable security definer set search_path = public as $$
  select v.id, v.day, w.name, to_char(w.start_time, 'HH24:MI'), to_char(w.end_time, 'HH24:MI'),
         (select first_name from profiles where id = v.student_id), app.checkin_name(v.visitor_id), v.guests, v.note, v.status,
         v.cancel_reason, v.visitor_id = auth.uid()
  from lunch_visits v join lunch_windows w on w.id = v.window_id
  where v.day >= app.school_today() and (v.visitor_id = auth.uid() or app.is_guardian_of(v.student_id))
  order by v.day, w.start_time
$$;

/** The children the caller may visit at lunch, with their grades. */
create function public.lunch_my_kids() returns table (id uuid, first_name text, last_name text, grade int)
language sql stable security definer set search_path = public as $$
  select p.id, p.first_name, p.last_name, p.grade from profiles p where p.id in (select app.lunch_kids()) order by p.grade, p.first_name
$$;
revoke all on function public.lunch_my_kids() from public, anon;
grant execute on function public.lunch_my_kids() to authenticated, service_role;

revoke all on function public.lunch_window_save(uuid, text, int[], time, time, int, int, int, boolean), public.lunch_window_delete(uuid),
  public.lunch_close_day(date, boolean, text), public.lunch_set_rules(text), public.lunch_rules(), public.lunch_slots(uuid, date, int),
  public.lunch_allergy_notes(uuid, uuid), public.lunch_visit_book(uuid, date, uuid, int, text, boolean), public.lunch_visit_cancel(uuid, text),
  public.lunch_visitors(date), public.my_lunch_visits() from public, anon;
grant execute on function public.lunch_window_save(uuid, text, int[], time, time, int, int, int, boolean), public.lunch_window_delete(uuid),
  public.lunch_close_day(date, boolean, text), public.lunch_set_rules(text), public.lunch_rules(), public.lunch_slots(uuid, date, int),
  public.lunch_allergy_notes(uuid, uuid), public.lunch_visit_book(uuid, date, uuid, int, text, boolean), public.lunch_visit_cancel(uuid, text),
  public.lunch_visitors(date), public.my_lunch_visits() to authenticated, service_role;

insert into app.applied_migrations (name) values ('20261102000061_lunch_visits.sql') on conflict do nothing;

-- ===== 20261102000062_volunteer_analytics_directors.sql =====
-- Volunteer analytics are for Volunteer Leaders and directors only.
--
-- Until now everyone with groups.manage (the office, administrators and directors) saw them too. Now only Volunteer
-- Leaders and directors see the analytics and anyone else's volunteer history, and only directors change how much is
-- a lot. Running check-in (marking who came, the QR codes) stays with the leaders and groups.manage. Being a director
-- counts only in an authenticator-verified session, like every admin power.

/** A director, in an authenticator-verified session (admin powers only count there). */
create function app.is_director() returns boolean
language sql stable security definer set search_path = public as $$
  select app.mfa_ok() and exists (select 1 from profiles where id = auth.uid() and admin_tier = 'director' and school_role is not null)
$$;

/** Volunteer Leaders and directors see everyone's volunteering. */
create or replace function app.sees_volunteer_stats() returns boolean
language sql stable security definer set search_path = public as $$
  select app.is_volunteer_lead() or app.is_director()
$$;

/** How much is a lot: hours and shifts in 30 days, and whether you can change them (directors). */
create or replace function public.volunteer_busy_limits() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'hours', coalesce(nullif(app.setting('volunteer_busy_hours'), '')::int, 12),
    'shifts', coalesce(nullif(app.setting('volunteer_busy_shifts'), '')::int, 6),
    'canEdit', app.is_director())
$$;

/** Directors: change how much is a lot. */
create or replace function public.volunteer_set_busy_limits(p_hours int, p_shifts int) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not app.is_director() then
    if exists (select 1 from profiles where id = auth.uid() and admin_tier = 'director') then
      raise exception 'MFA_REQUIRED: Verify with your authenticator app to use admin tools.' using errcode = '42501';
    end if;
    raise exception 'Only a director changes how much is a lot.' using errcode = '42501';
  end if;
  if p_hours is null or p_hours not between 1 and 200 then raise exception 'Hours go from 1 to 200.'; end if;
  if p_shifts is null or p_shifts not between 1 and 100 then raise exception 'Shifts go from 1 to 100.'; end if;
  insert into app.settings values ('volunteer_busy_hours', p_hours::text), ('volunteer_busy_shifts', p_shifts::text)
  on conflict (key) do update set value = excluded.value;
  perform app.audit(null, 'volunteer.busy_limits', null, jsonb_build_object('hours', p_hours, 'shifts', p_shifts));
end $$;

/**
 * Volunteer Leaders and directors: everyone who volunteered, led or said yes from p_from to p_to (null: from the
 * start; to today), with shifts done, hours, no-shows, past days nobody marked and days led; and, whatever the dates,
 * shifts and minutes (done or led) in the last 30 days, shifts coming in the next 30, and busy: either is over the
 * limits (volunteer_busy_limits).
 */
create or replace function public.volunteer_stats(p_from date default null, p_to date default null) returns table (
  user_id uuid, name text, school_role text, is_lead boolean,
  shifts int, minutes int, no_shows int, unmarked int, led int,
  recent_shifts int, recent_minutes int, upcoming int, last_day date, busy boolean
)
language plpgsql stable security definer set search_path = public as $$
declare today date := app.school_today(); upto date := least(coalesce(p_to, app.school_today()), app.school_today());
        lim jsonb := public.volunteer_busy_limits();
begin
  if not app.sees_volunteer_stats() then
    raise exception 'Volunteer analytics are for Volunteer Leaders and directors.' using errcode = '42501';
  end if;
  return query
    with d as (
      select v.*, (p_from is null or v.day >= p_from) and v.day <= upto as inside,
             v.day between today - 29 and today as recent, v.day between today + 1 and today + 30 as coming
      from app.volunteer_days() v
    ), per as (
      select d.user_id,
        (count(*) filter (where inside and d.status = 'done'))::int as shifts,
        coalesce(sum(d.minutes) filter (where inside and d.status = 'done'), 0)::int as minutes,
        (count(*) filter (where inside and d.status = 'no_show'))::int as no_shows,
        (count(*) filter (where inside and d.status is null and d.day < today))::int as unmarked,
        (count(*) filter (where inside and d.status = 'led'))::int as led,
        (count(*) filter (where recent and d.status in ('done', 'led')))::int as recent_shifts,
        coalesce(sum(d.minutes) filter (where recent and d.status in ('done', 'led')), 0)::int as recent_minutes,
        (count(*) filter (where coming and (d.status is null or d.status = 'led')))::int as upcoming,
        max(d.day) filter (where d.status = 'done') as last_day,
        bool_or(inside or coming) as shown
      from d group by d.user_id
    )
    select p.id, trim(p.first_name || ' ' || p.last_name), p.school_role, p.volunteer_lead,
           per.shifts, per.minutes, per.no_shows, per.unmarked, per.led,
           per.recent_shifts, per.recent_minutes, per.upcoming, per.last_day,
           per.recent_minutes >= (lim->>'hours')::int * 60 or per.recent_shifts >= (lim->>'shifts')::int
             or per.upcoming >= (lim->>'shifts')::int
    from per join profiles p on p.id = per.user_id
    where per.shown
    order by per.minutes desc, per.shifts desc, p.last_name, p.first_name;
end $$;

/**
 * One person's volunteering from p_from to p_to (null: no limit), newest first: each day they said yes to, were marked
 * on or led, and what happened ('done', 'no_show', 'here', 'missed': past and nobody marked it, 'coming', 'led').
 * Your own, or anyone's for Volunteer Leaders and directors.
 */
create or replace function public.volunteer_history(p_user uuid, p_from date default null, p_to date default null) returns table (
  opportunity_id uuid, title text, event_title text, day date, start_time time, end_time time, status text, minutes int
)
language plpgsql stable security definer set search_path = public as $$
begin
  if p_user is distinct from auth.uid() and not app.sees_volunteer_stats() then
    raise exception 'Volunteer analytics are for Volunteer Leaders and directors.' using errcode = '42501';
  end if;
  return query
    select o.id, o.title, e.title, v.day, o.start_time, o.end_time,
           coalesce(v.status, case when v.day < app.school_today() then 'missed' else 'coming' end), v.minutes
    from app.volunteer_days() v
    join volunteer_opportunities o on o.id = v.opportunity_id
    left join volunteer_events e on e.id = o.event_id and e.status = 'open'
    where v.user_id = p_user and (p_from is null or v.day >= p_from) and (p_to is null or v.day <= p_to)
    order by v.day desc, o.start_time desc nulls last, o.title;
end $$;

revoke all on function app.is_director() from public, anon;
grant execute on function app.is_director() to authenticated, service_role;

insert into app.applied_migrations (name) values ('20261102000062_volunteer_analytics_directors.sql') on conflict do nothing;

-- ===== 20261102000063_student_records.sql =====
-- The Student app's dashboard: each student's record from the school's student information system (FACTS,
-- Blackbaud and the like): general information, attendance, and each class's grade with every graded assignment.
--
-- The app keeps a read-only copy. A connector for the school's system (an Edge Function holding its API keys) maps what
-- it reads into one shape and hands it to sis_import (service role only), which matches each student to their profile
-- (the link made before, a profile id, or a unique name and birthday) and replaces that student's attendance, classes
-- and grades for the school year. Students it can't match are handed back, not guessed. Nothing is edited in the app.
--
-- Only the student and their parents read a record (app.reads_student_record; never Family accounts, substitutes or
-- other staff). student_record() gives the dashboard in one call: the students you can see, oldest first, and the
-- chosen one's (or the oldest's) information, attendance and classes; student_course() gives one class with all its
-- grades.

create table public.sis_students (
  student_id  uuid primary key references public.profiles (id) on delete cascade,
  sis_id      text not null unique check (char_length(sis_id) between 1 and 64),   -- the student's id in that system
  source      text not null check (source ~ '^[a-z][a-z0-9_]{0,31}$'),             -- 'facts', 'blackbaud', 'sample'
  school_year int not null,                                                         -- 2027 = 2026–27 (app.school_year_end)
  homeroom    text check (char_length(homeroom) <= 100),
  advisor     text check (char_length(advisor) <= 100),
  enrolled_on date,
  school_days int check (school_days between 0 and 366),   -- days the school has been in session this school year
  details     jsonb not null default '[]' check (jsonb_typeof(details) = 'array'),   -- anything else: [{label, value}]
  synced_at   timestamptz not null default now()
);

-- The school's grading terms (semesters or quarters), for each school year.
create table public.sis_terms (
  school_year int not null,
  name        text not null check (char_length(name) between 1 and 40),
  starts_on   date not null,
  ends_on     date not null,
  source      text not null,
  primary key (school_year, name),
  check (ends_on >= starts_on)
);

-- Days that weren't a plain day at school: absent, a half day, late, or left early.
create table public.sis_attendance (
  student_id uuid not null references public.sis_students (student_id) on delete cascade,
  day        date not null,
  kind       text not null check (kind in ('absent', 'half_day', 'tardy', 'left_early')),
  excused    boolean not null default false,
  note       text check (char_length(note) <= 200),
  primary key (student_id, day, kind)
);

create table public.sis_courses (
  id          uuid primary key default gen_random_uuid(),
  student_id  uuid not null references public.sis_students (student_id) on delete cascade,
  sis_id      text not null check (char_length(sis_id) between 1 and 64),
  school_year int not null,
  name        text not null check (char_length(name) between 1 and 100),
  subject     text check (char_length(subject) <= 40),         -- 'math', 'english'… (for its icon)
  teacher     text check (char_length(teacher) <= 100),
  average     numeric(5, 2) check (average between 0 and 200),  -- the system's current average, in percent
  letter      text check (char_length(letter) <= 4),
  categories  jsonb not null default '[]' check (jsonb_typeof(categories) = 'array'),   -- [{name, weight}], weights in percent
  position    int,
  unique (student_id, sis_id, school_year)
);

-- Each graded (or still to be graded) piece of work. Missing counts as zero; excused and not yet graded don't count.
create table public.sis_assignments (
  course_id uuid not null references public.sis_courses (id) on delete cascade,
  sis_id    text not null check (char_length(sis_id) between 1 and 64),
  title     text not null check (char_length(title) between 1 and 200),
  category  text check (char_length(category) <= 60),
  due_on    date not null,
  score     numeric(7, 2) check (score >= 0),
  max_score numeric(7, 2) check (max_score > 0),
  status    text not null default 'graded' check (status in ('graded', 'missing', 'excused', 'pending')),
  comment   text check (char_length(comment) <= 500),
  primary key (course_id, sis_id)
);

-- Letters for an average (the overall one; each class's comes from the system): the lowest percent for each.
insert into app.settings values ('grade_scale', '[{"letter":"A","min":90},{"letter":"B","min":80},{"letter":"C","min":70},{"letter":"D","min":60},{"letter":"F","min":0}]')
on conflict (key) do nothing;

-- ----------------------------------------------------------------------
-- Who reads a record
-- ----------------------------------------------------------------------

/** The student themself, or one of their parents (app.is_guardian_of: never Family accounts). */
create function app.reads_student_record(s uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select s = auth.uid() or app.is_guardian_of(s)
$$;

alter table public.sis_students enable row level security;
alter table public.sis_terms enable row level security;
alter table public.sis_attendance enable row level security;
alter table public.sis_courses enable row level security;
alter table public.sis_assignments enable row level security;
create policy "the student and their parents" on public.sis_students for select to authenticated using (app.reads_student_record(student_id));
create policy "everyone signed in" on public.sis_terms for select to authenticated using (true);
create policy "the student and their parents" on public.sis_attendance for select to authenticated using (app.reads_student_record(student_id));
create policy "the student and their parents" on public.sis_courses for select to authenticated using (app.reads_student_record(student_id));
create policy "the student and their parents" on public.sis_assignments for select to authenticated
  using (exists (select 1 from public.sis_courses c where c.id = course_id and app.reads_student_record(c.student_id)));

revoke all on public.sis_students, public.sis_terms, public.sis_attendance, public.sis_courses, public.sis_assignments from anon;
revoke insert, update, delete on public.sis_students, public.sis_terms, public.sis_attendance, public.sis_courses, public.sis_assignments from authenticated;
grant select on public.sis_students, public.sis_terms, public.sis_attendance, public.sis_courses, public.sis_assignments to authenticated;
grant all on public.sis_students, public.sis_terms, public.sis_attendance, public.sis_courses, public.sis_assignments to service_role;

-- ----------------------------------------------------------------------
-- Reads
-- ----------------------------------------------------------------------

/**
 * The dashboard: the students you can see (yourself, or your children), oldest first (by birthday, else by class),
 * and for p_student (or the oldest) the record from the school's system, if there is one: information, this school
 * year's attendance, the grading terms, each class with its average, letter and missing work, and the grade scale.
 */
create function public.student_record(p_student uuid default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare who jsonb; pick uuid; st sis_students;
begin
  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'firstName', p.first_name, 'lastName', p.last_name, 'grade', p.grade,
           'gradeLabel', app.grade_label(p.grade), 'photoPath', p.avatar_url, 'birthday', d.birthday)
           order by coalesce(d.birthday, make_date(p.class_of - 18, 9, 1)) nulls last, p.first_name, p.id), '[]'::jsonb)
    into who
  from profiles p left join student_details d on d.student_id = p.id
  where p.school_role = 'student'
    and (p.id = auth.uid() or p.id in (select g.student_id from guardians g where g.guardian_id = auth.uid()))
    and app.reads_student_record(p.id);

  if p_student is not null and not app.reads_student_record(p_student) then
    raise exception 'You can only see your own or your children''s records.' using errcode = '42501';
  end if;
  pick := coalesce(p_student, (who->0->>'id')::uuid);
  select * into st from sis_students where student_id = pick;

  return jsonb_build_object(
    'students', who,
    'studentId', pick,
    'scale', coalesce(nullif(app.setting('grade_scale'), '')::jsonb, '[]'::jsonb),
    'record', case when st.student_id is null then null else jsonb_build_object(
      'sisId', st.sis_id, 'source', st.source, 'schoolYear', st.school_year, 'homeroom', st.homeroom, 'advisor', st.advisor,
      'enrolledOn', st.enrolled_on, 'schoolDays', st.school_days, 'details', st.details, 'syncedAt', st.synced_at,
      'birthday', (select birthday from student_details where student_id = pick),
      'terms', (select coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'startsOn', t.starts_on, 'endsOn', t.ends_on) order by t.starts_on), '[]'::jsonb)
                from sis_terms t where t.school_year = st.school_year),
      'attendance', (select coalesce(jsonb_agg(jsonb_build_object('day', a.day, 'kind', a.kind, 'excused', a.excused, 'note', a.note)
                       order by a.day desc, a.kind), '[]'::jsonb)
                     from sis_attendance a where a.student_id = pick
                       and a.day between make_date(st.school_year - 1, 7, 1) and make_date(st.school_year, 6, 30)),
      'courses', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'subject', c.subject, 'teacher', c.teacher,
                    'average', c.average, 'letter', c.letter,
                    'missing', (select count(*) from sis_assignments x where x.course_id = c.id and x.status = 'missing'))
                    order by c.position nulls last, c.name), '[]'::jsonb)
                  from sis_courses c where c.student_id = pick and c.school_year = st.school_year)
    ) end);
end $$;

/** One class: its average, categories and every assignment, oldest first, with the year's grading terms. */
create function public.student_course(p_course uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare c sis_courses;
begin
  select * into c from sis_courses where id = p_course;
  if c.id is null or not app.reads_student_record(c.student_id) then
    raise exception 'That class isn''t on your or your children''s records.' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'id', c.id, 'studentId', c.student_id, 'name', c.name, 'subject', c.subject, 'teacher', c.teacher,
    'average', c.average, 'letter', c.letter, 'categories', c.categories, 'schoolYear', c.school_year,
    'scale', coalesce(nullif(app.setting('grade_scale'), '')::jsonb, '[]'::jsonb),
    'terms', (select coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'startsOn', t.starts_on, 'endsOn', t.ends_on) order by t.starts_on), '[]'::jsonb)
              from sis_terms t where t.school_year = c.school_year),
    'assignments', (select coalesce(jsonb_agg(jsonb_build_object('id', a.sis_id, 'title', a.title, 'category', a.category, 'dueOn', a.due_on,
                      'score', a.score, 'maxScore', a.max_score, 'status', a.status, 'comment', a.comment) order by a.due_on, a.title), '[]'::jsonb)
                    from sis_assignments a where a.course_id = c.id));
end $$;

-- ----------------------------------------------------------------------
-- Import (the connector, with the service role)
-- ----------------------------------------------------------------------

/** The profile a student from the school's system is: linked before, the profile id given, or a unique name and birthday. */
create function app.sis_match(s jsonb) returns uuid
language plpgsql stable security definer set search_path = public as $$
declare hit uuid; n int;
begin
  select student_id into hit from sis_students where sis_id = s->>'sisId';
  if hit is not null then return hit; end if;
  if s->>'profileId' is not null then
    select id into hit from profiles where id = (s->>'profileId')::uuid and school_role = 'student';
    if hit is not null then return hit; end if;
  end if;
  if s->>'birthday' is null then return null; end if;
  select count(*), min(p.id::text)::uuid into n, hit
  from profiles p join student_details d on d.student_id = p.id
  where p.school_role = 'student' and d.birthday = (s->>'birthday')::date
    and app.norm_name(p.first_name) = app.norm_name(s->>'firstName') and app.norm_name(p.last_name) = app.norm_name(s->>'lastName');
  return case when n = 1 then hit end;
end $$;

/**
 * Service role only: a school year from the school's system, in one shape whatever the system:
 *   { source, schoolYear?, scale?: [{letter, min}], terms?: [{name, startsOn, endsOn}],
 *     students: [{ sisId, profileId?, firstName, lastName, birthday?, homeroom?, advisor?, enrolledOn?, schoolDays?,
 *                  details?: [{label, value}], attendance?: [{day, kind, excused?, note?}],
 *                  courses?: [{ sisId, name, subject?, teacher?, average?, letter?, categories?: [{name, weight}],
 *                               grades?: [{sisId, title, category?, dueOn, score?, maxScore?, status?, comment?}] }] }] }
 * Each matched student's attendance, classes and grades for that school year are replaced; the ones it can't match
 * come back in "unmatched".
 */
create function public.sis_import(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare src text := p->>'source'; yr int := coalesce((p->>'schoolYear')::int, app.school_year_end());
        s jsonb; c jsonb; who uuid; course uuid; done int := 0; missed jsonb := '[]'::jsonb; i int;
begin
  if src is null or src !~ '^[a-z][a-z0-9_]{0,31}$' then raise exception 'Say which system it comes from (source).'; end if;
  if p ? 'scale' then
    insert into app.settings values ('grade_scale', (p->'scale')::text) on conflict (key) do update set value = excluded.value;
  end if;
  if p ? 'terms' then
    delete from sis_terms where school_year = yr;
    insert into sis_terms (school_year, name, starts_on, ends_on, source)
      select yr, t->>'name', (t->>'startsOn')::date, (t->>'endsOn')::date, src from jsonb_array_elements(p->'terms') t;
  end if;

  for s in select * from jsonb_array_elements(coalesce(p->'students', '[]'::jsonb)) loop
    who := app.sis_match(s);
    if who is null then
      missed := missed || jsonb_build_object('sisId', s->>'sisId', 'name', trim(concat_ws(' ', s->>'firstName', s->>'lastName')));
      continue;
    end if;
    insert into sis_students (student_id, sis_id, source, school_year, homeroom, advisor, enrolled_on, school_days, details, synced_at)
    values (who, s->>'sisId', src, yr, s->>'homeroom', s->>'advisor', (s->>'enrolledOn')::date, (s->>'schoolDays')::int,
            coalesce(s->'details', '[]'::jsonb), now())
    on conflict (student_id) do update set sis_id = excluded.sis_id, source = excluded.source, school_year = excluded.school_year,
      homeroom = excluded.homeroom, advisor = excluded.advisor, enrolled_on = excluded.enrolled_on,
      school_days = excluded.school_days, details = excluded.details, synced_at = excluded.synced_at;

    delete from sis_attendance where student_id = who and day between make_date(yr - 1, 7, 1) and make_date(yr, 6, 30);
    insert into sis_attendance (student_id, day, kind, excused, note)
      select who, (a->>'day')::date, a->>'kind', coalesce((a->>'excused')::boolean, false), nullif(a->>'note', '')
      from jsonb_array_elements(coalesce(s->'attendance', '[]'::jsonb)) a
    on conflict do nothing;

    delete from sis_courses where student_id = who and school_year = yr
      and sis_id not in (select x->>'sisId' from jsonb_array_elements(coalesce(s->'courses', '[]'::jsonb)) x);
    i := 0;
    for c in select * from jsonb_array_elements(coalesce(s->'courses', '[]'::jsonb)) loop
      i := i + 1;
      insert into sis_courses (student_id, sis_id, school_year, name, subject, teacher, average, letter, categories, position)
      values (who, c->>'sisId', yr, c->>'name', c->>'subject', c->>'teacher', (c->>'average')::numeric, c->>'letter',
              coalesce(c->'categories', '[]'::jsonb), i)
      on conflict (student_id, sis_id, school_year) do update set name = excluded.name, subject = excluded.subject,
        teacher = excluded.teacher, average = excluded.average, letter = excluded.letter, categories = excluded.categories,
        position = excluded.position
      returning id into course;
      delete from sis_assignments where course_id = course;
      insert into sis_assignments (course_id, sis_id, title, category, due_on, score, max_score, status, comment)
        select course, g->>'sisId', g->>'title', g->>'category', (g->>'dueOn')::date, (g->>'score')::numeric, (g->>'maxScore')::numeric,
               coalesce(g->>'status', 'graded'), nullif(g->>'comment', '')
        from jsonb_array_elements(coalesce(c->'grades', '[]'::jsonb)) g;
    end loop;
    done := done + 1;
  end loop;
  return jsonb_build_object('students', done, 'unmatched', missed);
end $$;

revoke all on function app.reads_student_record(uuid) from public, anon;
grant execute on function app.reads_student_record(uuid) to authenticated, service_role;
revoke all on function app.sis_match(jsonb), public.sis_import(jsonb) from public, anon, authenticated;
grant execute on function app.sis_match(jsonb), public.sis_import(jsonb) to service_role;
revoke all on function public.student_record(uuid), public.student_course(uuid) from public, anon;
grant execute on function public.student_record(uuid), public.student_course(uuid) to authenticated, service_role;

insert into app.applied_migrations (name) values ('20261102000063_student_records.sql') on conflict do nothing;

-- ===== 20261102000064_lunch_booking_lock.sql =====
-- Lunch visits: two families booking the last seats at the same moment could both get in. The
-- lunch time was read "for share", which lets both bookings go ahead together; "for update" makes the
-- second one wait for the first, then count it. Everything else is as before.

create or replace function public.lunch_visit_book(p_window uuid, p_day date, p_student uuid, p_guests int default 0, p_note text default '',
  p_read_allergies boolean default false) returns public.lunch_visits
language plpgsql security definer set search_path = public as $$
declare w lunch_windows%rowtype; g int; r lunch_visits%rowtype; t uuid; kid text;
begin
  if p_student is null or p_student not in (select app.lunch_kids()) then
    raise exception 'Only a child''s parents and the family the school linked can visit at lunch.' using errcode = '42501';
  end if;
  if not coalesce(p_read_allergies, false) then raise exception 'Read the allergy notes and lunch rules first.'; end if;
  select * into w from lunch_windows where id = p_window and active for update;  -- one booking at a time, so the seats hold
  if not found then raise exception 'That lunch time isn''t offered.'; end if;
  select grade into g from profiles where id = p_student;
  if g is null or g not between w.grade_from and w.grade_to then raise exception 'That lunch isn''t for this child''s grade.'; end if;
  if p_day is null or p_day < app.school_today() or p_day > app.school_today() + 60 then raise exception 'Pick a day in the next two months.'; end if;
  if not (extract(isodow from p_day)::int = any (w.weekdays)) or app.lunch_closed(p_day) then raise exception 'Lunch visits aren''t open that day.'; end if;
  if p_day = app.school_today() and (now() at time zone 'America/Chicago')::time >= w.start_time then raise exception 'That lunch has already started.'; end if;
  if coalesce(p_guests, 0) not between 0 and 3 then raise exception 'Bring up to 3 guests.'; end if;
  if char_length(coalesce(p_note, '')) > 300 then raise exception 'Keep the note to 300 characters.'; end if;
  if exists (select 1 from lunch_visits where window_id = w.id and day = p_day and student_id = p_student and visitor_id = auth.uid() and status = 'booked') then
    raise exception 'You''re already coming that day.';
  end if;
  if app.lunch_taken(w.id, p_day) + 1 + coalesce(p_guests, 0) > w.capacity then raise exception 'That lunch is full. Try another day.'; end if;
  insert into lunch_visits (window_id, day, student_id, visitor_id, guests, note, allergy_ack_at)
  values (w.id, p_day, p_student, auth.uid(), coalesce(p_guests, 0), trim(coalesce(p_note, '')), now())
  returning * into r;
  select first_name into kid from profiles where id = p_student;
  for t in select app.teachers_of(p_student) loop
    perform app.notify_user(t, '🍎 ' || app.short_name(auth.uid()) || ' is coming to lunch with ' || kid,
      to_char(p_day, 'Dy Mon FMDD') || ', ' || w.name || ' (' || to_char(w.start_time, 'FMHH12:MI') || ')'
        || case when r.guests > 0 then ', with ' || r.guests || ' guest' || case when r.guests > 1 then 's' else '' end else '' end,
      jsonb_build_object('lunchVisitId', r.id));
  end loop;
  return r;
end $$;

insert into app.applied_migrations (name) values ('20261102000064_lunch_booking_lock.sql') on conflict do nothing;

-- ===== 20261104000065_volunteer_invites.sql =====
-- Volunteer invites.
--
-- A Volunteer Leader asks particular people to help with an opportunity (help, not item requests). Each
-- invite is answered Say Yes! (they're signed up, and it's in their My sign-ups) or Deny; the leader is told
-- either way and follows each one (waiting, said yes, then their check-in). After a Deny the leader invites
-- someone else, or deletes the opportunity.
--
-- An opportunity posted "Only people I invite" (invite_only) is a draft nobody else sees: only its leaders, the
-- people with an open or accepted invite and its volunteers. It can't be deleted with a reason the volunteers see
-- until someone said yes, so a draft is deleted without one. On an opportunity everyone sees, an invite holds its
-- spot: others can't take the spots that open invites are waiting on.

alter table public.volunteer_opportunities add column invite_only boolean not null default false;
alter table public.volunteer_opportunities add constraint volunteer_invite_only_help check (not invite_only or kind = 'help');

create table public.volunteer_invites (
  opportunity_id uuid not null references public.volunteer_opportunities (id) on delete cascade,
  user_id        uuid not null references public.profiles (id) on delete cascade,
  invited_by     uuid references public.profiles (id) on delete set null,
  -- pending: waiting for an answer; accepted: said yes (declined again if they later remove themselves);
  -- declined: Deny; cancelled: the leader called it off, or the opportunity was deleted.
  status         text not null default 'pending' check (status in ('pending', 'accepted', 'declined', 'cancelled')),
  note           text check (char_length(note) <= 300),
  created_at     timestamptz not null default now(),
  answered_at    timestamptz,
  primary key (opportunity_id, user_id)
);
create index on public.volunteer_invites (user_id, status);

alter table public.volunteer_invites enable row level security;

-- ======================================================================
-- Helpers
-- ======================================================================

/** Has an invite to this opportunity that's waiting or that they said yes to. */
create function app.invited_to(o uuid, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from volunteer_invites where opportunity_id = o and user_id = u and status in ('pending', 'accepted'))
$$;

/** "Tue, Nov 10": an opportunity's first day, for notifications. */
create function app.volunteer_day(o public.volunteer_opportunities) returns text
language sql stable as $$
  select to_char(o.starts_on, 'FMDy, FMMon FMDD') || case when o.ends_on is not null and o.ends_on <> o.starts_on
    then ' – ' || to_char(o.ends_on, 'FMDy, FMMon FMDD') else '' end
$$;

-- Invite-only opportunities: only their leaders, the people invited and their volunteers see them.
drop policy "open opportunities, or ones you're part of" on public.volunteer_opportunities;
create policy "open opportunities, or ones you're part of" on public.volunteer_opportunities for select to authenticated
  using (app.can_volunteer() and ((status = 'open' and not invite_only) or app.in_volunteer_chat(id) or app.invited_to(id) or app.runs_volunteer(id))
         or app.has_permission('groups.manage'));

-- Who said yes, for the opportunities you can see (so an invite-only one's volunteers stay private too).
drop policy "everyone who can volunteer sees who signed up" on public.volunteer_signups;
create policy "everyone who can volunteer sees who signed up" on public.volunteer_signups for select to authenticated
  using (app.can_volunteer() and exists (select 1 from volunteer_opportunities o where o.id = opportunity_id)
         or app.has_permission('groups.manage'));

create policy "your own invites, or the opportunities you run" on public.volunteer_invites for select to authenticated
  using (user_id = auth.uid() or app.runs_volunteer(opportunity_id));

-- ======================================================================
-- API
-- ======================================================================

-- Posting takes "Only people I invite" (p_invite_only, last so older calls still work).
drop function public.volunteer_post(text, text, date, date, time, time, text, int, text, text, int, uuid);
create function public.volunteer_post(
  p_title text, p_description text, p_starts_on date, p_ends_on date default null,
  p_start_time time default null, p_end_time time default null, p_location text default null, p_spots int default null,
  p_kind text default 'help', p_item text default null, p_quantity int default null, p_event uuid default null,
  p_invite_only boolean default false
) returns public.volunteer_opportunities
language plpgsql security definer set search_path = public as $$
declare r volunteer_opportunities%rowtype; items boolean := coalesce(p_kind, 'help') = 'items';
begin
  if not app.is_volunteer_lead() then
    raise exception 'Only Volunteer Leaders can post opportunities.' using errcode = '42501';
  end if;
  if items and nullif(trim(p_item), '') is null then raise exception 'Say what you need, like "boxes of tissues".'; end if;
  if items and coalesce(p_quantity, 0) < 1 then raise exception 'Say how many you need.'; end if;
  if items and coalesce(p_invite_only, false) then raise exception 'Item requests go to everyone; invite people to help instead.'; end if;
  if p_event is not null and not exists (select 1 from volunteer_events where id = p_event and status = 'open') then
    raise exception 'That event isn''t open anymore.';
  end if;
  insert into volunteer_opportunities (lead_id, title, description, starts_on, ends_on, start_time, end_time, location, spots,
                                       kind, item, quantity, event_id, invite_only)
  values (auth.uid(), trim(p_title), coalesce(trim(p_description), ''), p_starts_on, p_ends_on, p_start_time, p_end_time,
          nullif(trim(p_location), ''), case when items then null else p_spots end,
          case when items then 'items' else 'help' end, case when items then trim(p_item) end, case when items then p_quantity end, p_event,
          coalesce(p_invite_only, false))
  returning * into r;
  return r;
end $$;

/**
 * Say Yes! (until it's full). An invite-only opportunity takes only the people invited, and on one everyone sees,
 * the spots open invites wait on are held for them. Saying yes answers your invite. The leader hears about it.
 */
create or replace function public.volunteer_say_yes(p_opportunity uuid) returns void
language plpgsql security definer set search_path = public as $$
declare o volunteer_opportunities%rowtype; taken int; held int; invited boolean;
begin
  if not app.can_volunteer() then raise exception 'Volunteering is for parents and staff.' using errcode = '42501'; end if;
  select * into o from volunteer_opportunities where id = p_opportunity for update;  -- one sign-up at a time, so spots hold
  if not found or o.status <> 'open' then raise exception 'This opportunity isn''t available anymore.'; end if;
  if o.kind = 'items' then raise exception 'Choose how many you''ll bring.'; end if;
  if coalesce(o.ends_on, o.starts_on) < app.school_today() then raise exception 'This opportunity is over.'; end if;
  if o.lead_id = auth.uid() then raise exception 'You''re leading this one.'; end if;
  invited := exists (select 1 from volunteer_invites where opportunity_id = o.id and user_id = auth.uid() and status = 'pending');
  if o.invite_only and not invited then raise exception 'This opportunity is by invitation only.' using errcode = '42501'; end if;
  select count(*) into taken from volunteer_signups where opportunity_id = o.id;
  select count(*) into held from volunteer_invites i where i.opportunity_id = o.id and i.status = 'pending' and i.user_id <> auth.uid()
    and not exists (select 1 from volunteer_signups s where s.opportunity_id = o.id and s.user_id = i.user_id);
  if o.spots is not null and taken >= o.spots then raise exception 'All spots are filled.'; end if;
  if o.spots is not null and not invited and taken + held >= o.spots then
    raise exception 'All spots are filled or held for people who were invited.';
  end if;
  insert into volunteer_signups (opportunity_id, user_id) values (o.id, auth.uid());
  update volunteer_invites set status = 'accepted', answered_at = now()
    where opportunity_id = o.id and user_id = auth.uid() and status = 'pending';
  perform app.notify_user(o.lead_id, '🙋 ' || app.short_name(auth.uid()) || ' said yes',
    o.title || coalesce(' · ' || (taken + 1) || ' of ' || o.spots || ' spots filled', ' · ' || (taken + 1) || ' signed up') || '.',
    jsonb_build_object('opportunityId', o.id));
exception when unique_violation then
  raise exception 'You''ve already said yes.';
end $$;

/** A volunteer removes themselves; the leader is told. An invite they'd said yes to counts as declined again. */
create or replace function public.volunteer_withdraw(p_opportunity uuid) returns void
language plpgsql security definer set search_path = public as $$
declare o volunteer_opportunities%rowtype; q int;
begin
  delete from volunteer_signups where opportunity_id = p_opportunity and user_id = auth.uid() returning quantity into q;
  if not found then raise exception 'You''re not signed up for this.'; end if;
  update volunteer_invites set status = 'declined', answered_at = now()
    where opportunity_id = p_opportunity and user_id = auth.uid() and status = 'accepted';
  select * into o from volunteer_opportunities where id = p_opportunity;
  if o.status = 'open' and o.kind = 'items' then
    perform app.notify_user(o.lead_id, app.short_name(auth.uid()) || ' took back their pledge',
      app.short_name(auth.uid()) || ' won''t bring the ' || q || ' ' || o.item || ' for ' || o.title || '.', jsonb_build_object('opportunityId', o.id));
  elsif o.status = 'open' then
    perform app.notify_user(o.lead_id, app.short_name(auth.uid()) || ' can''t make it',
      app.short_name(auth.uid()) || ' removed themselves from ' || o.title || '.', jsonb_build_object('opportunityId', o.id));
  end if;
end $$;

/**
 * The leader (or an admin) deletes an opportunity: every volunteer gets the reason, and anyone still invited is
 * told it's called off. Until someone has said yes (a draft waiting on invites) no reason is needed.
 */
create or replace function public.volunteer_delete(p_opportunity uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare o volunteer_opportunities%rowtype; v record; why text := nullif(trim(p_reason), ''); volunteers boolean;
begin
  select * into o from volunteer_opportunities where id = p_opportunity for update;
  if not found or o.status <> 'open' then raise exception 'This opportunity is already gone.'; end if;
  if o.lead_id <> auth.uid() and not app.has_permission('groups.manage') then
    raise exception 'Only the leader can delete this opportunity.' using errcode = '42501';
  end if;
  volunteers := exists (select 1 from volunteer_signups where opportunity_id = o.id);
  if why is null and volunteers then raise exception 'Say why you''re deleting it; volunteers will see the reason.'; end if;
  update volunteer_opportunities set status = 'deleted', delete_reason = coalesce(why, 'Deleted before anyone said yes.') where id = o.id;
  for v in select user_id from volunteer_signups where opportunity_id = o.id loop
    perform app.notify_user(v.user_id, 'Cancelled: ' || o.title,
      app.short_name(auth.uid()) || ' cancelled this volunteer opportunity: ' || why, jsonb_build_object('opportunityId', o.id));
  end loop;
  for v in update volunteer_invites set status = 'cancelled', answered_at = now()
           where opportunity_id = o.id and status = 'pending' returning user_id loop
    perform app.notify_user(v.user_id, 'Invite called off: ' || o.title,
      app.short_name(auth.uid()) || ' doesn''t need help with ' || o.title || ' anymore.' || coalesce(' ' || why, ''),
      jsonb_build_object('opportunityId', o.id, 'volunteerList', true));
  end loop;
  if o.lead_id <> auth.uid() then
    perform app.audit(null, 'volunteer.deleted', o.lead_id::text, jsonb_build_object('opportunity', o.id, 'title', o.title, 'reason', why));
  end if;
end $$;

/**
 * Its leaders (the opportunity's or its event's leader, or groups.manage) invite people who can volunteer, with an
 * optional note; each is told. Someone who said no before can be asked again. On an opportunity with spots, open
 * invites and volunteers together can't be more than the spots. Returns how many were invited.
 */
create function public.volunteer_invite(p_opportunity uuid, p_users uuid[], p_note text default null) returns int
language plpgsql security definer set search_path = public as $$
declare o volunteer_opportunities%rowtype; u uuid; n int := 0; taken int; why text := nullif(trim(p_note), '');
begin
  select * into o from volunteer_opportunities where id = p_opportunity for update;
  if not found or o.status <> 'open' then raise exception 'This opportunity isn''t available anymore.'; end if;
  if not app.runs_volunteer(o.id) then raise exception 'Only its leader can invite people.' using errcode = '42501'; end if;
  if o.kind = 'items' then raise exception 'Item requests go to everyone; invite people to help instead.'; end if;
  if coalesce(o.ends_on, o.starts_on) < app.school_today() then raise exception 'This opportunity is over.'; end if;
  if coalesce(cardinality(p_users), 0) = 0 then raise exception 'Choose who to invite.'; end if;
  if char_length(why) > 300 then raise exception 'Keep the note under 300 characters.'; end if;
  foreach u in array (select array_agg(distinct x) from unnest(p_users) x) loop
    if u = o.lead_id then raise exception 'You lead this one.'; end if;
    if not app.can_volunteer(u) then raise exception '% can''t volunteer.', app.short_name(u); end if;
    if exists (select 1 from volunteer_signups where opportunity_id = o.id and user_id = u) then
      raise exception '% already said yes.', app.short_name(u);
    end if;
    if exists (select 1 from volunteer_invites where opportunity_id = o.id and user_id = u and status = 'pending') then
      raise exception '% is already invited.', app.short_name(u);
    end if;
    insert into volunteer_invites (opportunity_id, user_id, invited_by, note)
    values (o.id, u, auth.uid(), why)
    on conflict (opportunity_id, user_id) do update
      set status = 'pending', invited_by = auth.uid(), note = why, created_at = now(), answered_at = null;
    perform app.notify_user(u, '✉️ ' || app.short_name(auth.uid()) || ' invited you to volunteer',
      o.title || ' on ' || app.volunteer_day(o) || '.' || coalesce(' "' || why || '"', ''),
      jsonb_build_object('opportunityId', o.id));
    n := n + 1;
  end loop;
  select (select count(*) from volunteer_signups where opportunity_id = o.id)
       + (select count(*) from volunteer_invites where opportunity_id = o.id and status = 'pending') into taken;
  if o.spots is not null and taken > o.spots then
    raise exception 'That''s more people than the % spot(s): invite fewer, or add spots.', o.spots;
  end if;
  return n;
end $$;

/**
 * Answer an invite: Say Yes! signs you up (as volunteer_say_yes, which tells the leader), Deny tells whoever invited
 * you, so they can invite someone else.
 */
create function public.volunteer_invite_answer(p_opportunity uuid, p_yes boolean) returns void
language plpgsql security definer set search_path = public as $$
declare o volunteer_opportunities%rowtype; i volunteer_invites%rowtype; who uuid;
begin
  select * into i from volunteer_invites where opportunity_id = p_opportunity and user_id = auth.uid();
  if not found then raise exception 'You don''t have an invite to this.'; end if;
  if i.status <> 'pending' then
    raise exception '%', case i.status when 'accepted' then 'You''ve already said yes.' when 'declined' then 'You already said no to this one.'
      else 'This invite was called off.' end;
  end if;
  select * into o from volunteer_opportunities where id = p_opportunity;
  who := coalesce(i.invited_by, o.lead_id);
  if p_yes then
    perform public.volunteer_say_yes(p_opportunity);
    -- The leader heard from volunteer_say_yes; someone else who sent it (the event's leader) hears too.
    if who <> o.lead_id then
      perform app.notify_user(who, '🙋 ' || app.short_name(auth.uid()) || ' said yes to your invite',
        o.title || ' on ' || app.volunteer_day(o) || '.', jsonb_build_object('opportunityId', o.id));
    end if;
    return;
  end if;
  update volunteer_invites set status = 'declined', answered_at = now() where opportunity_id = o.id and user_id = auth.uid();
  if o.status = 'open' then
    perform app.notify_user(who, app.short_name(auth.uid()) || ' can''t help with ' || o.title,
      case when o.invite_only and not exists (select 1 from volunteer_signups where opportunity_id = o.id)
        then 'Invite someone else, or delete the draft.' else 'Invite someone else from the opportunity.' end,
      jsonb_build_object('opportunityId', o.id));
  end if;
end $$;

/** Its leaders call off an invite that's still waiting; the person is told. */
create function public.volunteer_invite_cancel(p_opportunity uuid, p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
declare o volunteer_opportunities%rowtype;
begin
  select * into o from volunteer_opportunities where id = p_opportunity;
  if not found or not app.runs_volunteer(o.id) then raise exception 'Only its leader can call off an invite.' using errcode = '42501'; end if;
  update volunteer_invites set status = 'cancelled', answered_at = now()
    where opportunity_id = o.id and user_id = p_user and status = 'pending';
  if not found then raise exception 'That invite isn''t waiting for an answer.'; end if;
  perform app.notify_user(p_user, 'Invite called off: ' || o.title,
    app.short_name(auth.uid()) || ' called off the invite to ' || o.title || '.',
    jsonb_build_object('opportunityId', o.id, 'volunteerList', true));
end $$;

/**
 * For inviting: people who can volunteer whose name matches (names and roles only, never email), with where they
 * stand on this opportunity: invited (pending / accepted / declined), signed up, or nothing yet. Its leaders only.
 */
create function public.volunteer_invite_people(p_opportunity uuid, p_search text default '')
returns table (id uuid, name text, school_role text, invite text, signed_up boolean)
language plpgsql stable security definer set search_path = public as $$
declare q text := lower(trim(coalesce(p_search, '')));
begin
  if not app.runs_volunteer(p_opportunity) then raise exception 'Only its leader can invite people.' using errcode = '42501'; end if;
  return query
  select p.id, trim(p.first_name || ' ' || p.last_name), p.school_role, i.status,
         exists (select 1 from volunteer_signups s where s.opportunity_id = p_opportunity and s.user_id = p.id)
  from profiles p
  left join volunteer_invites i on i.opportunity_id = p_opportunity and i.user_id = p.id and i.status <> 'cancelled'
  where app.can_volunteer(p.id) and p.id <> auth.uid()
    and p.id <> (select lead_id from volunteer_opportunities where volunteer_opportunities.id = p_opportunity)
    and (q = '' or lower(p.first_name || ' ' || p.last_name) like '%' || q || '%' or lower(p.last_name) like q || '%')
  order by p.last_name, p.first_name
  limit 25;
end $$;

