-- ===== 20261104000066_staff_today.sql =====
-- "Needs you today" on a teacher's or staff member's Planner.
--
-- One call counts what's waiting on the person across the apps, so the Planner shows it without asking each app:
-- the roll still to take in the classes they lead, today's absence reports for their students (or, for the office,
-- the ones nobody has marked seen), questions assigned to them (and, for routers, ones to route), volunteer shifts
-- they lead that nobody marked, a sub covering their class today and today's lunch visitors. Admin counts (feedback
-- to triage, accounts and family requests waiting) come only with the permission, so only in a verified session.
-- Counts only: the screens they open show the details, with their own checks.

/**
 * What's waiting on the caller on p_day (today unless given): counts by key, each only where it applies to them
 * (teachers, staff and admins; everyone else gets {}). The Planner shows the ones above zero (src/info/needsYou.ts).
 */
create function public.staff_today(p_day date default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  d date := coalesce(p_day, app.school_today());
  me uuid := auth.uid();
  school_day boolean;
  mine text[];      -- the class sections they lead
  covered text[];   -- …that a sub has that day
begin
  if not app.is_staff() then return '{}'::jsonb; end if;
  school_day := extract(isodow from d) <= 5 and not exists (
    select 1 from events where group_id is null and category in ('No School', 'Teacher In-Service', 'E-Learning')
      and d between starts_on and coalesce(ends_on, starts_on));
  select coalesce(array_agg(id), '{}') into mine from rosters where kind = 'section' and lead_id = me;
  select coalesce(array_agg(distinct ss.section_id), '{}') into covered
    from sub_assignment_sections ss join sub_assignments a on a.id = ss.assignment_id
    where ss.section_id = any (mine) and d between a.starts_on and a.ends_on;

  return jsonb_strip_nulls(jsonb_build_object(
    -- Their classes whose roll nobody has started (not on a no-school day, nor where a sub takes it).
    'roll', case when school_day and cardinality(mine) > 0 then (
      select count(*) from unnest(mine) as s(id) cross join lateral app.attendance_counts(s.id, d) as c(v)
      where not s.id = any (covered) and (c.v->>'students')::int > 0 and (c.v->>'unmarked')::int = (c.v->>'students')::int) end,
    'subCovering', case when cardinality(covered) > 0 then cardinality(covered) end,
    -- Parents' reports for the day: their students' (teachers); the ones still to mark seen (the office).
    'absencesToday', case when cardinality(mine) > 0 then (
      select count(*) from absence_reports r where r.status = 'reported' and d between r.starts_on and r.ends_on
        and app.teaches(me, r.student_id)) end,
    'absencesToSee', case when app.has_permission('checkin.manage') then (
      select count(*) from absence_reports r where r.status = 'reported' and r.seen_at is null and r.ends_on >= d) end,
    'questionsAssigned', (select count(*) from school_questions where assignee_id = me and status in ('new', 'assigned')),
    'questionsToRoute', case when app.has_permission('questions.manage') then (
      select count(*) from school_questions where status = 'new' and assignee_id is null) end,
    'feedbackNew', case when app.has_permission('feedback.triage') then (select count(*) from feedback where status = 'new') end,
    'accountsWaiting', case when app.has_permission('people.approve') then (select count(*) from profiles where school_role is null) end,
    'familyRequests', case when app.has_permission('people.family') then (select count(*) from family_requests where status = 'pending') end,
    -- Lunch visitors that day: every one for the office, or the ones coming to see their students.
    'lunchVisitors', (select count(*) from lunch_visits v where v.day = d and v.status = 'booked'
      and (app.has_permission('lunch.manage') or app.has_permission('checkin.manage') or app.teaches(me, v.student_id))),
    -- Days in the last two weeks of help opportunities they lead where a volunteer who said yes is still unmarked.
    'volunteerToMark', (
      select count(*) from volunteer_signups s
      join volunteer_opportunities o on o.id = s.opportunity_id and o.kind = 'help' and o.status = 'open' and o.lead_id = me
      cross join lateral generate_series(greatest(o.starts_on, d - 14), least(coalesce(o.ends_on, o.starts_on), d - 1), interval '1 day') g
      where not exists (select 1 from volunteer_attendance a where a.opportunity_id = o.id and a.user_id = s.user_id and a.day = g::date))
  ));
end $$;

revoke all on function public.staff_today(date) from public, anon;
grant execute on function public.staff_today(date) to authenticated, service_role;

insert into app.applied_migrations (name) values ('20261104000066_staff_today.sql') on conflict do nothing;

-- ===== 20261105000067_volunteer_coaches.sql =====
-- Coaches post in Volunteer.
--
-- An activity's coaches and directors (sport_coaches, who are staff) post volunteer opportunities and start volunteer
-- events the way Volunteer Leaders do: concession stand helpers for a game, drivers to an away meet, a cast party.
-- They lead what they post (check-in, invites, marking who came). Volunteer analytics stay with Volunteer Leaders
-- and directors (app.sees_volunteer_stats).

/** Coaches or directs an activity: on its sport_coaches (staff only, as app.can_manage_sport). */
create function app.is_coach(u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.is_staff(u) and exists (select 1 from sport_coaches where user_id = u)
$$;

/** Posts volunteer opportunities and starts volunteer events: Volunteer Leaders and coaches. */
create function app.posts_volunteer(u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.is_volunteer_lead(u) or app.is_coach(u)
$$;

/** Posting an opportunity: Volunteer Leaders and coaches (as before otherwise). */
create or replace function public.volunteer_post(
  p_title text, p_description text, p_starts_on date, p_ends_on date default null,
  p_start_time time default null, p_end_time time default null, p_location text default null, p_spots int default null,
  p_kind text default 'help', p_item text default null, p_quantity int default null, p_event uuid default null,
  p_invite_only boolean default false
) returns public.volunteer_opportunities
language plpgsql security definer set search_path = public as $$
declare r volunteer_opportunities%rowtype; items boolean := coalesce(p_kind, 'help') = 'items';
begin
  if not app.posts_volunteer() then
    raise exception 'Only Volunteer Leaders and coaches can post opportunities.' using errcode = '42501';
  end if;
  if items and nullif(trim(p_item), '') is null then raise exception 'Say what you need, like "boxes of tissues".'; end if;
  if items and coalesce(p_quantity, 0) < 1 then raise exception 'Say how many you need.'; end if;
  if items and coalesce(p_invite_only, false) then raise exception 'Item requests go to everyone; invite people to help instead.'; end if;
  if p_event is not null and not exists (select 1 from volunteer_events where id = p_event and status = 'open') then
    raise exception 'That event isn''t open anymore.';
  end if;
  insert into volunteer_opportunities (lead_id, title, description, starts_on, ends_on, start_time, end_time, location, spots,
                                       kind, item, quantity, event_id, invite_only)
  values (auth.uid(), trim(p_title), coalesce(trim(p_description), ''), p_starts_on, p_ends_on, p_start_time, p_end_time,
          nullif(trim(p_location), ''), case when items then null else p_spots end,
          case when items then 'items' else 'help' end, case when items then trim(p_item) end, case when items then p_quantity end, p_event,
          coalesce(p_invite_only, false))
  returning * into r;
  return r;
end $$;

/** Volunteer Leaders and coaches: start an event (p_id null) or change one you started. */
create or replace function public.volunteer_event_save(p_id uuid, p_title text, p_description text, p_starts_on date,
                                            p_ends_on date default null, p_location text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare new_id uuid;
begin
  if not app.posts_volunteer() then raise exception 'Only Volunteer Leaders and coaches can start events.' using errcode = '42501'; end if;
  if coalesce(trim(p_title), '') = '' then raise exception 'Give the event a name, like "Harvest Fest".'; end if;
  if p_starts_on is null then raise exception 'Choose the day of the event.'; end if;
  if p_ends_on is not null and p_ends_on < p_starts_on then raise exception 'The event has to end on or after the day it starts.'; end if;
  if p_id is null then
    insert into volunteer_events (lead_id, title, description, starts_on, ends_on, location)
    values (auth.uid(), trim(p_title), coalesce(trim(p_description), ''), p_starts_on, p_ends_on, nullif(trim(p_location), ''))
    returning id into new_id;
    return new_id;
  end if;
  update volunteer_events set title = trim(p_title), description = coalesce(trim(p_description), ''), starts_on = p_starts_on,
    ends_on = p_ends_on, location = nullif(trim(p_location), '')
  where id = p_id and lead_id = auth.uid() and status = 'open';
  if not found then raise exception 'You can only change events you started.' using errcode = '42501'; end if;
  return p_id;
end $$;

revoke all on function app.is_coach(uuid), app.posts_volunteer(uuid) from public, anon;
grant execute on function app.is_coach(uuid), app.posts_volunteer(uuid) to authenticated, service_role;

